import React, { useState, useEffect } from 'react';
import { MatchSetup } from './components/MatchSetup';
import { MatchLive } from './components/MatchLive';
import { MatchSummary } from './components/MatchSummary';
import { MatchArchive } from './components/MatchArchive';
import { MatchSpectator } from './components/MatchSpectator';
import { MatchState, Team, SanctionType, MatchSet, Substitution } from './types';

const DEFAULT_PLAYERS_A = [
  "Amine Ziyech", "Youssef Bounou", "Karim Hakimi", "Sofiane Amrabat", "Nordin En-Nesyri", "Mehdi Benatia",
  "Adil Rami", "Younès Belhanda", "Omar El Kaddouri", "Marouane Chamakh", "Houssine Kharja", "Mounir El Hamdaoui"
];

const DEFAULT_PLAYERS_B = [
  "Badr Hari", "Rachid Yazami", "Kamal Oudrhiri", "Ismaël Ferroukhi", "Tariq El-Jamil", "Samir Ait Said",
  "Anas Zniti", "Walid Regragui", "Mustapha Hadji", "Noureddine Naybet", "Salaheddine Bassir", "Ahmed Faras"
];

const INITIAL_TEAM = (name: string, identityColor: string, jerseyColor: string, liberoColor: string): Team => {
  const playersList = name === 'Équipe A' ? DEFAULT_PLAYERS_A : DEFAULT_PLAYERS_B;
  const licPrefix = name === 'Équipe A' ? 'A' : 'B';

  return {
    name,
    color: identityColor,
    playerColor: jerseyColor,
    liberoColor: liberoColor,
    players: Array.from({ length: 12 }, (_, i) => ({
      id: `${name}-${i+1}`,
      number: i + 1,
      name: playersList[i] || `Joueur ${i + 1}`,
      licenseNumber: `${licPrefix}-25-${(i + 1).toString().padStart(3, '0')}`,
      isLibero: i >= 10,
      isCaptain: i === 0,
      status: 'ACTIVE'
    })),
    score: 0,
    setsWon: 0,
    timeoutsTaken: 0,
    substitutionsCount: 0,
    formation: [0, 1, 2, 3, 4, 5],
    substitutionHistory: [],
    hasDelayWarning: false,
    coach: name === 'Équipe A' ? 'M. DUPONT Jean' : 'M. MARTIN Pierre',
    assistantCoach1: name === 'Équipe A' ? 'ALAMI Samir' : 'BENALI Karim',
    assistantCoach2: '',
    assistantCoach3: '',
    medical: 'DR. RAOUL',
    sanctionedStaff: []
  };
};

const createInitialMatchState = (): MatchState => ({
  matchId: `M-${Date.now().toString().slice(-6)}`,
  league: 'NATIONAL DEUXIÈME DIVISION',
  city: 'TAOURIRT',
  hall: 'SALLE COUVERTE',
  category: 'Sénior',
  gender: 'M',
  date: new Date().toISOString().split('T')[0],
  scheduledTime: new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
  referee1: 'KARIM ALAMI',
  referee2: 'FATIMA ZAHRA',
  scorer: 'ALI BENJELLOUN',
  lineJudge1: '',
  lineJudge2: '',
  lineJudge3: '',
  lineJudge4: '',
  teamA: INITIAL_TEAM('Équipe A', '#4f46e5', '#4f46e5', '#f97316'),
  teamB: INITIAL_TEAM('Équipe B', '#1e40af', '#1e40af', '#fbbf24'),
  servingTeam: null,
  sets: [],
  currentSetIndex: 0,
  currentSetStartTime: '',
  currentSetPoints: [],
  currentSetStartingFormationA: [],
  currentSetStartingFormationB: [],
  currentSetFirstServingTeam: 'A',
  startTime: '',
  isLive: false,
  history: [],
  playerSanctions: [],
  isTeamAOnLeft: true,
  hasSwitchedInDecisiveSet: false,
  remarks: ''
});

const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'live' | 'summary' | 'archive' | 'spectator'>('setup');
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [selectedArchivedMatch, setSelectedArchivedMatch] = useState<MatchState | null>(null);
  const [match, setMatch] = useState<MatchState>(createInitialMatchState());

  useEffect(() => {
    const saved = localStorage.getItem('volleyref_history');
    if (saved) {
      try {
        setMatchHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Erreur chargement historique", e);
      }
    }
  }, []);

  const handleStartMatch = (setupData: Partial<MatchState>) => {
    const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    const firstServer = setupData.servingTeam || 'A';

    setMatch(prev => ({
      ...prev,
      ...setupData,
      isLive: true,
      startTime: now,
      currentSetStartTime: now,
      currentSetFirstServingTeam: firstServer,
      currentSetStartingFormationA: setupData.teamA?.formation || prev.teamA.formation,
      currentSetStartingFormationB: setupData.teamB?.formation || prev.teamB.formation,
      history: [{
        time: now,
        setIndex: 0,
        team: 'NONE',
        type: 'SET_START',
        description: `Début Match & Set 1`,
        score: "0-0"
      }]
    }));
    setView('live');
  };

  const handleEndMatch = () => {
    const finalMatch = { ...match, isLive: false };
    setMatch(finalMatch);
    const newHistory = [finalMatch, ...matchHistory].slice(0, 50);
    setMatchHistory(newHistory);
    localStorage.setItem('volleyref_history', JSON.stringify(newHistory));
    setView('summary');
  };

  const handleViewArchivedMatch = (archivedMatch: MatchState) => {
    setSelectedArchivedMatch(archivedMatch);
    setView('summary');
  };

  const handleDeleteMatch = (matchId: string) => {
    const newHistory = matchHistory.filter(m => m.matchId !== matchId);
    setMatchHistory(newHistory);
    localStorage.setItem('volleyref_history', JSON.stringify(newHistory));
  };

  const handleGenerateDemoMatch = () => {
    const demo: MatchState = createInitialMatchState();
    demo.matchId = "DEMO-32";
    demo.league = "LIGUE NATIONALE PRO - FINALE";
    demo.city = "CASABLANCA";
    demo.hall = "COMPLEXE MOHAMMED V";
    demo.startTime = "20:00";
    demo.teamA.name = "DRAGONS VOLLEY";
    demo.teamB.name = "TITANS CLUB";

    // Simuler 5 sets (3:2 pour A)
    const setResults = [
      { a: 25, b: 23, dur: 22, server: 'A' as const },
      { a: 22, b: 25, dur: 25, server: 'B' as const },
      { a: 25, b: 18, dur: 20, server: 'A' as const },
      { a: 24, b: 26, dur: 28, server: 'B' as const },
      { a: 15, b: 13, dur: 15, server: 'A' as const }
    ];

    demo.sets = setResults.map((res, i) => ({
      scoreA: res.a,
      scoreB: res.b,
      startTime: "20:" + (i * 30).toString().padStart(2, '0'),
      endTime: "20:" + (i * 30 + 25).toString().padStart(2, '0'),
      duration: res.dur,
      firstServingTeam: res.server,
      startingFormationA: [0, 1, 2, 3, 4, 5],
      startingFormationB: [0, 1, 2, 3, 4, 5],
      subsA: i === 0 ? [{ playerOutId: demo.teamA.players[0].id, playerInId: demo.teamA.players[6].id, isReturn: false, scoreAtSub: "10:08" }] : [],
      subsB: i === 1 ? [{ playerOutId: demo.teamB.players[1].id, playerInId: demo.teamB.players[7].id, isReturn: false, scoreAtSub: "15:15" }] : [],
      timeoutsTakenA: i % 2,
      timeoutsTakenB: (i + 1) % 2,
      points: [] // Simplifié pour la démo
    }));

    demo.teamA.setsWon = 3;
    demo.teamB.setsWon = 2;
    demo.playerSanctions = [
      { playerId: demo.teamA.players[2].id, type: SanctionType.WARNING, setIndex: 0, scoreAtSanction: "12:10", team: 'A' },
      { playerId: demo.teamB.players[4].id, type: SanctionType.PENALTY, setIndex: 1, scoreAtSanction: "15:18", team: 'B' },
      { playerId: demo.teamA.players[1].id, type: SanctionType.EXPULSION, setIndex: 3, scoreAtSanction: "20:21", team: 'A' },
      { playerId: demo.teamB.players[0].id, type: SanctionType.DISQUALIFICATION, setIndex: 4, scoreAtSanction: "08:10", team: 'B' }
    ];
    demo.remarks = "Match de haute intensité. Expulsion au set 4 suite à contestation répétée. Disqualification au set 5 pour conduite grossière.";

    const newHistory = [demo, ...matchHistory];
    setMatchHistory(newHistory);
    localStorage.setItem('volleyref_history', JSON.stringify(newHistory));
    handleViewArchivedMatch(demo);
  };

  const handleBackFromSummary = () => {
    if (selectedArchivedMatch) {
      setSelectedArchivedMatch(null);
      setView('archive');
    } else {
      setMatch(createInitialMatchState());
      setView('setup');
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 selection:bg-indigo-500/30">
      {view !== 'spectator' && (
      <header className="bg-slate-900/80 backdrop-blur-md border-b border-slate-800 p-4 sticky top-0 z-50 print:hidden">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center font-black shadow-lg shadow-indigo-500/20">V</div>
            <h1 className="text-xl font-black tracking-tighter uppercase italic">VolleyRef <span className="text-indigo-400">Pro</span></h1>
          </div>
          {view === 'setup' && (
            <button 
              onClick={() => setView('archive')}
              className="text-[10px] font-black uppercase text-indigo-400 bg-indigo-500/10 px-4 py-2 rounded-full border border-indigo-500/20 active:scale-95 transition-all flex items-center gap-2 hover:bg-indigo-500/20"
            >
              <span>📂</span>
              <span>Archives ({matchHistory.length})</span>
            </button>
          )}
        </div>
      </header>
      )}

      <main className={view === 'spectator' ? "" : "max-w-4xl mx-auto p-4 pb-24"}>
        {view === 'setup' && <MatchSetup onStart={handleStartMatch} initialData={match} onGenerateDemo={handleGenerateDemoMatch} />}
        {view === 'live' && <MatchLive match={match} setMatch={setMatch} onEnd={handleEndMatch} onSpectator={() => setView('spectator')} />}
        {view === 'summary' && <MatchSummary match={selectedArchivedMatch || match} setMatch={setMatch} onReset={handleBackFromSummary} />}
        {view === 'spectator' && <MatchSpectator match={match} onExit={() => setView('live')} />}
        {view === 'archive' && (
          <MatchArchive 
            history={matchHistory} 
            onSelect={handleViewArchivedMatch} 
            onBack={() => setView('setup')} 
            onDelete={handleDeleteMatch}
            onGenerateDemo={handleGenerateDemoMatch}
            onClear={() => {
              if(confirm("Effacer tout l'historique ?")) {
                setMatchHistory([]);
                localStorage.removeItem('volleyref_history');
              }
            }}
          />
        )}
      </main>

      {view !== 'spectator' && (
      <footer className="fixed bottom-0 left-0 right-0 p-4 bg-slate-950/50 backdrop-blur-sm pointer-events-none flex justify-center text-[10px] font-bold text-slate-600 uppercase tracking-widest z-0">
        FIVB Official Rules Compliant • 2025-2028
      </footer>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MatchState, Player, Team } from '../types';

interface Props {
  onStart: (data: Partial<MatchState>) => void;
  initialData: MatchState;
  onGenerateDemo?: () => void;
}

const ProgressBar: React.FC<{ step: number }> = ({ step }) => {
  const labels = ["Match", "Arbitres", "Équipe A", "Équipe B", "Formations"];
  return (
    <div className="mb-8">
      <div className="flex justify-between mb-2">
        {labels.map((l, i) => (
          <span key={i} className={`text-[8px] font-black uppercase tracking-widest ${step === i + 1 ? 'text-indigo-400' : 'text-slate-600'}`}>
            {l}
          </span>
        ))}
      </div>
      <div className="h-1.5 w-full bg-slate-900 rounded-full overflow-hidden flex">
        {[1, 2, 3, 4, 5].map(i => (
          <div key={i} className={`h-full flex-1 transition-all duration-500 border-r border-slate-950 last:border-0 ${i <= step ? 'bg-indigo-600' : 'bg-transparent'}`} />
        ))}
      </div>
    </div>
  );
};

const TeamConfig: React.FC<{
  team: Team;
  teamId: 'A' | 'B';
  onUpdatePlayer: (teamId: 'A' | 'B', index: number, field: keyof Player, value: any) => void;
  onUpdateTeam: (teamId: 'A' | 'B', field: keyof Team, value: any) => void;
  onAddPlayer: () => void;
  onRemovePlayer: (index: number) => void;
}> = ({ team, teamId, onUpdatePlayer, onUpdateTeam, onAddPlayer, onRemovePlayer }) => {
  const canAddPlayer = team.players.length < 14;
  const liberosCount = team.players.filter(p => p.isLibero).length;
  const captainCount = team.players.filter(p => p.isCaptain).length;

  // État pour la modale de suppression
  const [playerToDeleteIndex, setPlayerToDeleteIndex] = useState<number | null>(null);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-right duration-300">
      <div className="flex items-center gap-4 bg-slate-900/50 p-4 rounded-2xl border border-slate-800">
        <input 
          type="color" 
          value={team.color} 
          onChange={e => onUpdateTeam(teamId, 'color', e.target.value)} 
          className="w-12 h-12 rounded-xl cursor-pointer border-2 border-slate-700 bg-slate-800" 
        />
        <div className="flex-1">
          <label className="text-[9px] font-black text-slate-500 uppercase block mb-1">Nom de l'équipe {teamId}</label>
          <input 
            type="text" 
            value={team.name} 
            onChange={e => onUpdateTeam(teamId, 'name', e.target.value)} 
            className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm font-black text-white outline-none focus:border-indigo-500 transition-colors" 
            placeholder="Ex: Volley Club..."
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800 space-y-2">
          <label className="text-[9px] font-black text-slate-500 uppercase block">Couleur Maillot</label>
          <div className="flex items-center gap-3">
             <input type="color" value={team.playerColor} onChange={e => onUpdateTeam(teamId, 'playerColor', e.target.value)} className="w-8 h-8 rounded-lg border border-slate-700 cursor-pointer" />
             <span className="text-[10px] font-bold text-slate-300">Joueurs</span>
          </div>
        </div>
        <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800 space-y-2">
          <label className="text-[9px] font-black text-slate-500 uppercase block">Couleur Libero</label>
          <div className="flex items-center gap-3">
             <input type="color" value={team.liberoColor} onChange={e => onUpdateTeam(teamId, 'liberoColor', e.target.value)} className="w-8 h-8 rounded-lg border border-slate-700 cursor-pointer" />
             <span className="text-[10px] font-bold text-slate-300">Spécialiste</span>
          </div>
        </div>
      </div>

      <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800 space-y-3">
        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-800 pb-2">Staff Technique</h3>
        <input type="text" placeholder="Entraîneur Principal" value={team.coach} onChange={e => onUpdateTeam(teamId, 'coach', e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2.5 text-xs font-bold text-slate-200" />
        <input type="text" placeholder="Entraîneur Adjoint" value={team.assistantCoach1} onChange={e => onUpdateTeam(teamId, 'assistantCoach1', e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2.5 text-xs font-bold text-slate-200" />
      </div>

      <div className="space-y-3">
        <div className="flex flex-wrap justify-between items-end px-1 gap-2">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Effectif Joueurs</h3>
          <div className="flex gap-3">
            <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${captainCount === 1 ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'bg-rose-500/20 text-rose-500 border border-rose-500/30'}`}>
              {captainCount === 1 ? '✓ 1 Capitaine' : `⚠️ ${captainCount} Capitaine(s)`}
            </span>
            <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${team.players.length >= 6 ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30' : 'bg-rose-500/20 text-rose-500 border border-rose-500/30'}`}>
              {team.players.length} / 14 Joueurs
            </span>
          </div>
        </div>

        <div className="flex flex-col gap-2 max-h-[500px] overflow-y-auto custom-scrollbar pr-1">
          {team.players.map((p, index) => (
            <div key={p.id} className="bg-slate-900 border border-slate-800 rounded-xl p-2 flex flex-wrap sm:flex-nowrap items-center gap-2 shadow-sm hover:border-slate-700 transition-colors">

              {/* Numéro */}
              <div className="w-12 shrink-0">
                 <input 
                  type="number" 
                  value={p.number} 
                  onChange={e => onUpdatePlayer(teamId, index, 'number', parseInt(e.target.value) || 0)} 
                  className="w-full h-10 bg-slate-950 text-center rounded-lg font-black text-white border border-slate-700 text-sm focus:border-indigo-500 outline-none" 
                  placeholder="#" 
                />
              </div>

              {/* Infos Joueur (Nom & Licence) */}
              <div className="flex-1 min-w-[140px] flex flex-col gap-1">
                <input 
                  type="text" 
                  placeholder="Nom du joueur" 
                  value={p.name} 
                  onChange={e => onUpdatePlayer(teamId, index, 'name', e.target.value)} 
                  className="w-full bg-transparent rounded px-1 py-0.5 font-bold text-slate-200 text-xs outline-none border-b border-transparent focus:border-slate-700 placeholder:text-slate-600" 
                />
                <input 
                  type="text" 
                  placeholder="N° Licence" 
                  value={p.licenseNumber} 
                  onChange={e => onUpdatePlayer(teamId, index, 'licenseNumber', e.target.value)} 
                  className="w-full bg-transparent rounded px-1 py-0.5 font-mono text-slate-400 text-[10px] outline-none border-b border-transparent focus:border-slate-700 placeholder:text-slate-700" 
                />
              </div>

              {/* Contrôles Rôles */}
              <div className="flex items-center gap-1 shrink-0 bg-slate-950/50 p-1.5 rounded-lg border border-slate-800 ml-auto sm:ml-0">
                {/* CHECKBOX CAPITAINE */}
                <label className={`flex flex-col items-center justify-center cursor-pointer group px-1 ${p.isLibero ? 'opacity-30 cursor-not-allowed' : ''}`}>
                  <input 
                    type="checkbox"
                    checked={p.isCaptain}
                    disabled={p.isLibero}
                    onChange={(e) => {
                      if (e.target.checked) {
                        // Règle : Un seul capitaine. On décoche les autres.
                        team.players.forEach((_, i) => onUpdatePlayer(teamId, i, 'isCaptain', false));
                        // Règle : Libero ne peut pas être capitaine (déjà géré par disabled mais sécurité)
                        if (p.isLibero) onUpdatePlayer(teamId, index, 'isLibero', false);
                        onUpdatePlayer(teamId, index, 'isCaptain', true);
                      } else {
                        onUpdatePlayer(teamId, index, 'isCaptain', false);
                      }
                    }}
                    className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-indigo-600 accent-indigo-600 focus:ring-indigo-500 cursor-pointer disabled:cursor-not-allowed"
                  />
                  <span className={`text-[6px] font-black uppercase mt-0.5 ${p.isCaptain ? 'text-indigo-400' : 'text-slate-600 group-hover:text-slate-400'}`}>CAP</span>
                </label>

                <div className="w-px h-6 bg-slate-800 mx-1"></div>

                {/* CHECKBOX LIBERO */}
                <label className={`flex flex-col items-center justify-center cursor-pointer group px-1 ${p.isCaptain ? 'opacity-30 cursor-not-allowed' : ''}`}>
                  <input 
                    type="checkbox"
                    checked={p.isLibero}
                    disabled={p.isCaptain}
                    onChange={(e) => {
                       if (e.target.checked) {
                          if (liberosCount >= 2) {
                             alert("Maximum 2 Libéros autorisés.");
                             return;
                          }
                          // Règle : Capitaine ne peut pas être Libero
                          if (p.isCaptain) onUpdatePlayer(teamId, index, 'isCaptain', false);
                          onUpdatePlayer(teamId, index, 'isLibero', true);
                       } else {
                          onUpdatePlayer(teamId, index, 'isLibero', false);
                       }
                    }}
                    className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-amber-500 accent-amber-500 focus:ring-amber-500 cursor-pointer disabled:cursor-not-allowed"
                  />
                  <span className={`text-[6px] font-black uppercase mt-0.5 ${p.isLibero ? 'text-amber-500' : 'text-slate-600 group-hover:text-slate-400'}`}>LIB</span>
                </label>
              </div>

              <button 
                type="button"
                onClick={() => setPlayerToDeleteIndex(index)} 
                className="w-8 h-8 rounded-lg bg-rose-950/20 text-rose-500 border border-rose-900/20 flex items-center justify-center hover:bg-rose-500 hover:text-white transition-all shrink-0"
                title="Supprimer"
              >
                ×
              </button>
            </div>
          ))}
        </div>

        <button 
          onClick={onAddPlayer} 
          disabled={!canAddPlayer}
          className={`w-full py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 border-dashed ${canAddPlayer ? 'bg-indigo-500/5 border-indigo-500/20 text-indigo-400 hover:bg-indigo-500/10' : 'bg-slate-900 border-slate-800 text-slate-700 cursor-not-allowed'}`}
        >
          {canAddPlayer ? '+ Ajouter un joueur' : 'Effectif maximum atteint (14)'}
        </button>

        {/* MODALE DE CONFIRMATION DE SUPPRESSION DE JOUEUR */}
        {playerToDeleteIndex !== null && (
          <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-sm z-[700] flex items-center justify-center p-4" onClick={() => setPlayerToDeleteIndex(null)}>
            <div className="bg-slate-900 rounded-3xl border border-slate-800 p-6 w-full max-w-sm shadow-2xl animate-in zoom-in duration-200" onClick={e => e.stopPropagation()}>
               <div className="text-center space-y-4">
                  <div className="w-12 h-12 rounded-full bg-rose-500/20 text-rose-500 flex items-center justify-center text-2xl mx-auto">🗑️</div>
                  <h3 className="text-lg font-black text-white uppercase italic">Supprimer le joueur ?</h3>
                  <div className="text-sm text-slate-300 font-bold">
                     #{team.players[playerToDeleteIndex].number} {team.players[playerToDeleteIndex].name}
                  </div>
                  <p className="text-xs text-slate-400 font-medium">Voulez-vous vraiment retirer ce joueur de l'effectif ?</p>

                  <div className="grid grid-cols-2 gap-3 pt-4">
                     <button onClick={() => setPlayerToDeleteIndex(null)} className="py-3 rounded-xl bg-slate-800 text-slate-400 font-black text-xs uppercase hover:bg-slate-700 transition-all">Annuler</button>
                     <button onClick={() => { onRemovePlayer(playerToDeleteIndex); setPlayerToDeleteIndex(null); }} className="py-3 rounded-xl bg-rose-600 text-white font-black text-xs uppercase hover:bg-rose-500 transition-all shadow-lg shadow-rose-600/20">Supprimer</button>
                  </div>
               </div>
            </div>
         </div>
        )}
      </div>
    </div>
  );
};

export const MatchSetup: React.FC<Props> = ({ onStart, initialData, onGenerateDemo }) => {
  const [step, setStep] = useState<1 | 2 | 3 | 4 | 5>(1);
  const [formData, setFormData] = useState<Partial<MatchState>>({ ...initialData, servingTeam: 'A' });

  const handleFormChange = (field: keyof MatchState, value: any) => setFormData(prev => ({...prev, [field]: value }));
  const updateTeamInfo = (teamId: 'A' | 'B', field: keyof Team, value: any) => setFormData(p => ({...p, [teamId === 'A' ? 'teamA' : 'teamB']: { ...p[teamId === 'A' ? 'teamA' : 'teamB']!, [field]: value }}));

  const updatePlayer = (teamId: 'A' | 'B', index: number, field: keyof Player, value: any) => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    const players = [...team.players];
    players[index] = { ...players[index], [field]: value };
    setFormData(p => ({...p, [tk]: { ...team, players }}));
  };

  const addPlayer = (teamId: 'A' | 'B') => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    if (team.players.length >= 14) return;
    setFormData(p => ({...p, [tk]: { ...team, players: [...team.players, { id: Date.now().toString(), number: team.players.length + 1, name: '', licenseNumber: '', isLibero: false, isCaptain: false, status: 'ACTIVE' }]}}));
  };

  const removePlayer = (teamId: 'A' | 'B', index: number) => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    const players = team.players.filter((_, i) => i !== index);
    setFormData(p => ({...p, [tk]: { ...team, players }}));
  };

  const isStep1Valid = !!(formData.league && formData.city && formData.category && formData.date && formData.scheduledTime && formData.matchId);
  const isStep2Valid = true; 
  const isStep3Valid = (formData.teamA?.players.length || 0) >= 6 && !!formData.teamA?.name && formData.teamA?.players.filter(p => p.isCaptain).length === 1;
  const isStep4Valid = (formData.teamB?.players.length || 0) >= 6 && !!formData.teamB?.name && formData.teamB?.players.filter(p => p.isCaptain).length === 1;

  return (
    <div className="max-w-xl mx-auto p-4 space-y-6">
      <ProgressBar step={step} />

      {step === 1 && (
        <div className="space-y-4 animate-in fade-in slide-in-from-right duration-300">
          <div className="bg-slate-900/80 rounded-[2.5rem] p-8 border border-slate-800 shadow-2xl space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-black uppercase text-white tracking-tighter">1. Localisation & Type</h2>
              {onGenerateDemo && (
                <button 
                  onClick={onGenerateDemo}
                  className="text-[9px] font-black bg-indigo-600/20 text-indigo-400 px-3 py-1.5 rounded-lg border border-indigo-500/20 hover:bg-indigo-600 hover:text-white transition-all"
                >
                  Générer Démo 3:2
                </button>
              )}
            </div>
            <div className="space-y-4">
              <div className="bg-indigo-600/10 p-5 rounded-3xl border border-indigo-500/30 mb-4 ring-2 ring-indigo-500/10">
                <InputField 
                    label="Numéro Officiel du Match" 
                    value={formData.matchId} 
                    onChange={v => handleFormChange('matchId', v)} 
                    placeholder="Ex: 101"
                    highlight 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <InputField label="Compétition" value={formData.league} onChange={v => handleFormChange('league', v)} placeholder="Championnat..." />
                <InputField label="Ville" value={formData.city} onChange={v => handleFormChange('city', v)} placeholder="FES" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <InputField label="Salle / Hall" value={formData.hall} onChange={v => handleFormChange('hall', v)} placeholder="Gymnase..." />
                <InputField label="Catégorie" value={formData.category} onChange={v => handleFormChange('category', v)} placeholder="Sénior, Junior..." />
              </div>

              <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-800">
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-500 uppercase px-1 tracking-wider">Date de rencontre</label>
                  <input 
                    type="date"
                    value={formData.date} 
                    onChange={e => handleFormChange('date', e.target.value)} 
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 text-xs font-bold text-white uppercase outline-none focus:border-indigo-500 transition-colors" 
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-500 uppercase px-1 tracking-wider">Heure Prévue</label>
                  <input 
                    type="time"
                    value={formData.scheduledTime} 
                    onChange={e => handleFormChange('scheduledTime', e.target.value)} 
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 text-xs font-bold text-white uppercase outline-none focus:border-indigo-500 transition-colors" 
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-slate-500 uppercase px-1">Genre</label>
                <div className="flex gap-2">
                  <button onClick={() => handleFormChange('gender', 'M')} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 ${formData.gender === 'M' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-slate-900 border-slate-800 text-slate-600'}`}>Masculin</button>
                  <button onClick={() => handleFormChange('gender', 'F')} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 ${formData.gender === 'F' ? 'bg-rose-600 border-rose-400 text-white' : 'bg-slate-900 border-slate-800 text-slate-600'}`}>Féminin</button>
                </div>
              </div>
            </div>
          </div>
          <StepActions onNext={() => setStep(2)} nextDisabled={!isStep1Valid} />
        </div>
      )}

      {step === 2 && (
        <div className="space-y-4 animate-in fade-in slide-in-from-right duration-300">
          <div className="bg-slate-900/80 rounded-[2.5rem] p-8 border border-slate-800 shadow-2xl space-y-6">
            <h2 className="text-xl font-black uppercase text-white tracking-tighter">2. Corps Arbitral (Facultatif)</h2>
            <div className="space-y-4">
              <InputField label="1er Arbitre" value={formData.referee1} onChange={v => handleFormChange('referee1', v)} placeholder="Nom Prénom" />
              <InputField label="2e Arbitre" value={formData.referee2} onChange={v => handleFormChange('referee2', v)} placeholder="Nom Prénom" />
              <InputField label="Marqueur" value={formData.scorer} onChange={v => handleFormChange('scorer', v)} placeholder="Nom Prénom" />

              <div className="pt-4 border-t border-slate-800 space-y-3">
                <label className="text-[9px] font-black text-slate-500 uppercase px-1">Juges de ligne (Optionnel)</label>
                <div className="grid grid-cols-2 gap-3">
                  <input value={formData.lineJudge1} onChange={e => handleFormChange('lineJudge1', e.target.value)} placeholder="Juge 1" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge2} onChange={e => handleFormChange('lineJudge2', e.target.value)} placeholder="Juge 2" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge3} onChange={e => handleFormChange('lineJudge3', e.target.value)} placeholder="Juge 3" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge4} onChange={e => handleFormChange('lineJudge4', e.target.value)} placeholder="Juge 4" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                </div>
              </div>
            </div>
          </div>
          <StepActions onBack={() => setStep(1)} onNext={() => setStep(3)} nextDisabled={!isStep2Valid} />
        </div>
      )}

      {step === 3 && (
        <div className="space-y-6">
          <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">3. Données Équipe A</h2>
          <TeamConfig teamId="A" team={formData.teamA!} onUpdatePlayer={updatePlayer} onUpdateTeam={updateTeamInfo} onAddPlayer={() => addPlayer('A')} onRemovePlayer={(idx) => removePlayer('A', idx)} />
          <StepActions onBack={() => setStep(2)} onNext={() => setStep(4)} nextDisabled={!isStep3Valid} />
        </div>
      )}

      {step === 4 && (
        <div className="space-y-6">
          <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">4. Données Équipe B</h2>
          <TeamConfig teamId="B" team={formData.teamB!} onUpdatePlayer={updatePlayer} onUpdateTeam={updateTeamInfo} onAddPlayer={() => addPlayer('B')} onRemovePlayer={(idx) => removePlayer('B', idx)} />
          <StepActions onBack={() => setStep(3)} onNext={() => setStep(5)} nextDisabled={!isStep4Valid} />
        </div>
      )}

      {step === 5 && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom duration-500">

           {/* Section TOSS */}
           <div className="bg-gradient-to-br from-indigo-900/40 to-slate-900/40 p-6 rounded-3xl border border-indigo-500/20 text-center space-y-4">
             <h3 className="text-sm font-black text-white uppercase tracking-widest">Toss : Qui sert en premier ?</h3>
             <div className="flex gap-4">
                <button 
                  onClick={() => handleFormChange('servingTeam', 'A')}
                  className={`flex-1 py-4 rounded-2xl flex flex-col items-center justify-center border-2 transition-all gap-2 ${formData.servingTeam === 'A' ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl shadow-indigo-600/20 scale-105' : 'bg-slate-900 border-slate-800 text-slate-500 grayscale opacity-60'}`}
                >
                  <span className="text-2xl">🏐</span>
                  <span className="font-black text-xs uppercase">{formData.teamA?.name || 'Équipe A'}</span>
                </button>
                <button 
                  onClick={() => handleFormChange('servingTeam', 'B')}
                  className={`flex-1 py-4 rounded-2xl flex flex-col items-center justify-center border-2 transition-all gap-2 ${formData.servingTeam === 'B' ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl shadow-indigo-600/20 scale-105' : 'bg-slate-900 border-slate-800 text-slate-500 grayscale opacity-60'}`}
                >
                  <span className="text-2xl">🏐</span>
                  <span className="font-black text-xs uppercase">{formData.teamB?.name || 'Équipe B'}</span>
                </button>
             </div>
           </div>

           <div className="bg-slate-900/90 rounded-[2.5rem] p-8 shadow-2xl space-y-12 border border-slate-800">
             <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">5. Formations de Départ</h2>
             <FormationEntry team={formData.teamA!} tempF={formData.teamA!.formation} setTempF={f => updateTeamInfo('A', 'formation', f)} />
             <div className="h-px bg-slate-800" />
             <FormationEntry team={formData.teamB!} tempF={formData.teamB!.formation} setTempF={f => updateTeamInfo('B', 'formation', f)} />
           </div>

           <div className="flex gap-4">
             <button onClick={() => setStep(4)} className="flex-1 py-5 bg-slate-900 rounded-3xl font-black uppercase text-xs text-slate-500 border border-slate-800 hover:bg-slate-800 transition-all">← Précédent</button>
             <button 
               onClick={() => onStart(formData)} 
               disabled={formData.teamA!.formation.includes(-1) || formData.teamB!.formation.includes(-1)}
               className="flex-[2] bg-emerald-600 py-5 rounded-3xl font-black uppercase text-xs text-white shadow-xl shadow-emerald-600/20 disabled:opacity-30 border-b-4 border-emerald-900 active:border-b-0 transition-all"
             >
               Démarrer le Match 🏐
             </button>
           </div>
        </div>
      )}
    </div>
  );
};

const InputField = ({ label, value, onChange, placeholder, highlight }: any) => (
  <div className="space-y-1.5 w-full">
    <label className={`text-[9px] font-black uppercase px-1 tracking-wider ${highlight ? 'text-indigo-400' : 'text-slate-500'}`}>{label}</label>
    <input 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      placeholder={placeholder} 
      className={`w-full bg-slate-950 border rounded-2xl px-4 py-3 font-bold text-white uppercase outline-none transition-colors ${highlight ? 'border-indigo-500/50 text-base focus:border-indigo-400' : 'border-slate-800 text-xs focus:border-indigo-500'}`} 
    />
  </div>
);

const StepActions = ({ onBack, onNext, nextDisabled }: any) => (
  <div className="flex gap-4">
    {onBack && (
      <button onClick={onBack} className="flex-1 py-5 bg-slate-900 rounded-3xl font-black uppercase text-xs text-slate-500 border border-slate-800 hover:bg-slate-800 transition-all">
        Précédent
      </button>
    )}
    <button 
      onClick={onNext} 
      disabled={nextDisabled}
      className={`flex-[2] py-5 rounded-3xl font-black uppercase text-xs transition-all border-b-4 ${nextDisabled ? 'bg-slate-800 border-slate-900 text-slate-600 cursor-not-allowed opacity-50' : 'bg-indigo-600 border-indigo-900 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-500 active:border-b-0 active:translate-y-1'}`}
    >
      Continuer →
    </button>
  </div>
);

const FormationEntry = ({ team, tempF, setTempF }: any) => {
  const players = team.players.filter((p: any) => !p.isLibero);
  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <div className="w-4 h-4 rounded-full shadow-lg" style={{ backgroundColor: team.color }}></div>
        <span className="font-black text-sm text-white uppercase tracking-tighter">{team.name}</span>
      </div>
      <div className="grid grid-cols-6 gap-2">
        {tempF.map((pIdx: number, i: number) => (
           <div key={i} className={`bg-slate-950 border-2 rounded-2xl p-2.5 text-center transition-all ${pIdx === -1 ? 'border-dashed border-slate-800' : 'border-indigo-500 bg-indigo-500/5'}`}>
              <div className="text-[8px] text-slate-600 font-black mb-1">{['I','II','III','IV','V','VI'][i]}</div>
              <div className="text-base font-black text-white">{pIdx === -1 ? '?' : team.players[pIdx].number}</div>
           </div>
        ))}
      </div>
      <div className="bg-slate-950/40 p-4 rounded-[2rem] border border-slate-800">
        <label className="text-[8px] font-black text-slate-600 uppercase mb-3 block text-center">Sélectionner par ordre de position (I à VI)</label>
        <div className="grid grid-cols-6 gap-2">
          {players.map((p: any) => {
            const idx = team.players.indexOf(p);
            const used = tempF.includes(idx);
            return (
              <button 
                key={p.id} 
                disabled={used} 
                onClick={() => {
                  const nf = [...tempF];
                  const empty = nf.indexOf(-1);
                  if (empty !== -1) { nf[empty] = idx; setTempF(nf); }
                }} 
                className={`w-full aspect-square flex items-center justify-center rounded-xl font-black text-sm border-2 transition-all ${used ? 'bg-slate-900 border-slate-800 text-slate-700' : 'bg-slate-800 border-slate-700 text-white hover:border-indigo-500 active:scale-90'}`}
              >
                {p.number}
              </button>
            )
          })}
        </div>
        <button onClick={() => setTempF([-1,-1,-1,-1,-1,-1])} className="w-full mt-4 text-[9px] font-black text-rose-500 uppercase py-2 bg-rose-500/5 rounded-xl border border-rose-500/10 active:scale-95 transition-all">Réinitialiser la formation</button>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { MatchState } from '../types';

interface Props {
  history: MatchState[];
  onSelect: (match: MatchState) => void;
  onBack: () => void;
  onClear: () => void;
  onDelete: (matchId: string) => void;
  onGenerateDemo?: () => void;
}

export const MatchArchive: React.FC<Props> = ({ history, onSelect, onBack, onClear, onDelete, onGenerateDemo }) => {
  const [matchToDelete, setMatchToDelete] = useState<string | null>(null);

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom duration-300">
      <header className="flex justify-between items-center">
        <h2 className="text-xl font-black uppercase italic tracking-tighter text-white">Archives <span className="text-indigo-400">Matchs</span></h2>
        <div className="flex gap-2">
           {onGenerateDemo && (
             <button onClick={onGenerateDemo} className="text-[9px] font-black text-indigo-400 uppercase px-3 py-2 bg-indigo-500/10 border border-indigo-500/20 rounded-xl hover:bg-indigo-500 hover:text-white transition-all">Générer Test 3:2</button>
           )}
           <button onClick={onClear} className="text-[9px] font-black text-rose-500 uppercase px-3 py-2 bg-rose-500/10 border border-rose-500/20 rounded-xl hover:bg-rose-500 hover:text-white transition-all">Tout effacer</button>
           <button onClick={onBack} className="text-[9px] font-black text-slate-400 uppercase px-3 py-2 bg-slate-800 border border-slate-700 rounded-xl hover:bg-slate-700 transition-all">Retour</button>
        </div>
      </header>

      {history.length === 0 ? (
        <div className="bg-slate-900/50 border border-dashed border-slate-800 rounded-[2rem] p-12 text-center">
           <div className="text-4xl mb-4 opacity-20">📂</div>
           <p className="text-slate-500 font-bold uppercase text-xs tracking-widest">Aucun match dans les archives</p>
           {onGenerateDemo && (
             <button onClick={onGenerateDemo} className="mt-4 text-[10px] font-black text-indigo-400 uppercase border border-indigo-500/30 px-4 py-2 rounded-xl hover:bg-indigo-500/10">Créer un exemple complet</button>
           )}
        </div>
      ) : (
        <div className="grid gap-3">
          {history.map((match) => {
            const date = match.startTime ? match.startTime : 'Date inconnue';

            return (
              <div key={match.matchId} className="relative group">
                <button 
                  onClick={() => onSelect(match)}
                  className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-4 flex flex-col gap-3 text-left transition-all active:scale-[0.98] hover:border-indigo-500/50"
                >
                  <div className="flex justify-between items-center border-b border-slate-800/50 pb-2">
                     <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{match.league}</span>
                     <span className="text-[9px] font-black text-indigo-400 uppercase pr-8">{date}</span>
                  </div>

                  <div className="flex items-center justify-between py-1">
                     <div className="flex-1 flex flex-col">
                        <span className={`text-sm font-black uppercase ${match.teamA.setsWon > match.teamB.setsWon ? 'text-white' : 'text-slate-500'}`}>{match.teamA.name}</span>
                        <span className={`text-sm font-black uppercase ${match.teamB.setsWon > match.teamA.setsWon ? 'text-white' : 'text-slate-500'}`}>{match.teamB.name}</span>
                     </div>
                     <div className="flex flex-col items-center justify-center bg-slate-950 px-3 py-1 rounded-xl border border-slate-800">
                        <span className="text-lg font-black tabular-nums text-white leading-none">{match.teamA.setsWon}</span>
                        <div className="h-px w-4 bg-slate-800 my-1"></div>
                        <span className="text-lg font-black tabular-nums text-white leading-none">{match.teamB.setsWon}</span>
                     </div>
                  </div>

                  <div className="flex justify-between items-center pt-2">
                     <div className="flex gap-2">
                        <span className="text-[8px] font-bold text-slate-600 uppercase">Sets: {match.sets.length}</span>
                        <span className="text-[8px] font-bold text-slate-600 uppercase">Arbitre: {match.referee1 || '—'}</span>
                     </div>
                     <div className="text-indigo-500">→</div>
                  </div>
                </button>

                <button 
                  onClick={(e) => { e.stopPropagation(); setMatchToDelete(match.matchId); }}
                  className="absolute top-3 right-3 w-8 h-8 flex items-center justify-center bg-rose-500/10 text-rose-500 border border-rose-500/20 rounded-lg hover:bg-rose-500 hover:text-white transition-all z-10"
                  title="Supprimer ce match"
                >
                  <span className="text-xs">🗑️</span>
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* MODALE DE CONFIRMATION */}
      {matchToDelete && (
         <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-sm z-[700] flex items-center justify-center p-4" onClick={() => setMatchToDelete(null)}>
            <div className="bg-slate-900 rounded-3xl border border-slate-800 p-6 w-full max-w-sm shadow-2xl animate-in zoom-in duration-200" onClick={e => e.stopPropagation()}>
               <div className="text-center space-y-4">
                  <div className="w-12 h-12 rounded-full bg-rose-500/20 text-rose-500 flex items-center justify-center text-2xl mx-auto">🗑️</div>
                  <h3 className="text-lg font-black text-white uppercase italic">Supprimer le match ?</h3>
                  <p className="text-xs text-slate-400 font-medium">Cette action est irréversible. Voulez-vous vraiment supprimer ce match de l'historique ?</p>

                  <div className="grid grid-cols-2 gap-3 pt-4">
                     <button onClick={() => setMatchToDelete(null)} className="py-3 rounded-xl bg-slate-800 text-slate-400 font-black text-xs uppercase hover:bg-slate-700 transition-all">Annuler</button>
                     <button onClick={() => { if(matchToDelete) onDelete(matchToDelete); setMatchToDelete(null); }} className="py-3 rounded-xl bg-rose-600 text-white font-black text-xs uppercase hover:bg-rose-500 transition-all shadow-lg shadow-rose-600/20">Supprimer</button>
                  </div>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
