                    </div>
                    <div className={`h-full flex items-center justify-center ${scoreB > i ? 'bg-slate-300 relative' : ''}`}>
                         {scoreB > i && <div className="absolute inset-0 flex items-center justify-center text-[10px] leading-none">/</div>}
                        {i + 1}
                    </div>
                </div>
            ))}
        </div>
    </div>
);

const TeamSetColumn: React.FC<{set: MatchSet, team: Team, match: MatchState, setNumber: number, teamLabel: 'A' | 'B'}> = ({set, team, match, setNumber, teamLabel}) => {
    const formationIdx = teamLabel === 'A' ? set.startingFormationA : set.startingFormationB;
    const players = formationIdx.map(idx => team.players[idx]);
    const subs = teamLabel === 'A' ? set.subsA : set.subsB;
    const isReceivingTeam = set.firstServingTeam !== teamLabel;

    const serviceHistory = useMemo(() => {
        const rotationTurns: string[][] = Array.from({ length: 6 }, () => []);

        // Point initial 0 pour l'équipe qui reçoit si l'autre marque direct
        if (isReceivingTeam && set.points.length > 0 && set.points[0].team !== teamLabel) {
            // Dans les faits, on barre la première case.
        }

        // Grouper les points par tour de service
        let currentSvcPos = isReceivingTeam ? -1 : 0; 
        // Note: En volley, si on reçoit, on tourne AVANT le premier service. 
        // Donc la première case I (Svc 1) est utilisée par celui qui tourne en I.

        let lastScore = 0;
        let lastServerIndex = -1;

        for (let i = 0; i < set.points.length; i++) {
            const pt = set.points[i];
            const teamScore = teamLabel === 'A' ? pt.scoreA : pt.scoreB;

            // Si l'équipe gagne le point
            if (pt.team === teamLabel) {
                lastScore = teamScore;
                lastServerIndex = pt.servingPlayerIndex;
            } else {
                // Si l'équipe perd le service, on enregistre le score au moment de la perte
                if (lastServerIndex !== -1) {
                    let posIdx = formationIdx.indexOf(lastServerIndex);
                    // On gère les remplacements pour retrouver la position d'origine
                    if (posIdx === -1) {
                         const sub = subs.find(s => team.players.findIndex(p => p.id === s.playerInId) === lastServerIndex);
                         if (sub) posIdx = formationIdx.indexOf(team.players.findIndex(p => p.id === sub.playerOutId));
                    }

                    if (posIdx !== -1) {
                        rotationTurns[posIdx].push(lastScore.toString());
                        lastServerIndex = -1;
                    }
                }
            }
        }
        // Enregistrement final si le set se finit sur leur service
        if (lastServerIndex !== -1) {
            let posIdx = formationIdx.indexOf(lastServerIndex);
            if (posIdx !== -1) rotationTurns[posIdx].push(lastScore.toString());
        }

        return rotationTurns;
    }, [set.points, teamLabel, formationIdx, subs, isReceivingTeam]);

    return (
        <div className="flex-1 flex flex-col bg-white">
            <div className="text-center font-black py-0.5 border-b border-black uppercase bg-slate-100 text-[8px] italic flex justify-between px-2">
                <span>{teamLabel}</span><span>{team.name}</span><span></span>
            </div>
            <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center text-[6px] font-black uppercase bg-slate-50 border-b border-black">
                <div className="border-r border-black">Svc</div>
                {['I','II','III','IV','V','VI'].map(pos => <div key={pos} className="border-r border-black last:border-r-0">{pos}</div>)}
            </div>
            <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center h-4 items-center border-b border-black">
                <div className="border-r border-black text-[5px] font-black bg-slate-50 h-full flex items-center justify-center">N°</div>
                {players.map((p, i) => <div key={i} className="border-r border-black last:border-r-0 h-full flex items-center justify-center font-black text-[9px]">{p?.number}</div>)}
            </div>
            <div className="flex-1 grid grid-cols-[20px_repeat(6,1fr)] divide-x divide-black border-b border-black">
                <div className="flex flex-col bg-slate-50 border-r border-black divide-y divide-black">
                    {[1,2,3,4].map(n => <div key={n} className="flex-1 flex items-center justify-center text-[5px] font-bold">{n}</div>)}
                </div>
                {serviceHistory.map((history, colIdx) => (
                    <div key={colIdx} className="flex flex-col divide-y divide-black">
                        {[0,1,2,3].map(rowIdx => {
                            const score = history[rowIdx];
                            const isSkipped = isReceivingTeam && colIdx === 0 && rowIdx === 0;
                            return (
                                <div key={rowIdx} className={`flex-1 flex items-center justify-center text-[9px] font-black ${isSkipped ? 'bg-slate-200 relative' : ''}`}>
                                    {isSkipped && <div className="absolute inset-0 flex items-center justify-center text-black">X</div>}
                                    {score}
                                </div>
                            );
                        })}
                    </div>
                ))}
            </div>
        </div>
    );
};

