const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'live' | 'summary' | 'archive' | 'spectator'>('setup');
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [selectedArchivedMatch, setSelectedArchivedMatch] = useState<MatchState | null>(null);
  const [match, setMatch] = useState<MatchState>(createInitialMatchState());

  useEffect(() => {
    const saved = localStorage.getItem('volleyref_history');
    if (saved) {
      try {
        setMatchHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Erreur chargement historique", e);
      }
    }
  }, []);

  const handleStartMatch = (setupData: Partial<MatchState>) => {
    const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    const firstServer = setupData.servingTeam || 'A';

    setMatch(prev => ({
      ...prev,
      ...setupData,
      isLive: true,
      startTime: now,
      currentSetStartTime: now,
      currentSetFirstServingTeam: firstServer,
      currentSetStartingFormationA: setupData.teamA?.formation || prev.teamA.formation,
      currentSetStartingFormationB: setupData.teamB?.formation || prev.teamB.formation,
      history: [{
        time: now,
        setIndex: 0,
        team: 'NONE',
        type: 'SET_START',
        description: `Début Match & Set 1`,
        score: "0-0"
      }]
    }));
    setView('live');
  };

  const handleEndMatch = () => {
    const finalMatch = { ...match, isLive: false };
    setMatch(finalMatch);
    const newHistory = [finalMatch, ...matchHistory].slice(0, 50);
    setMatchHistory(newHistory);
    localStorage.setItem('volleyref_history', JSON.stringify(newHistory));
    setView('summary');
  };

  const handleViewArchivedMatch = (archivedMatch: MatchState) => {
    setSelectedArchivedMatch(archivedMatch);
    setView('summary');
  };

  const handleDeleteMatch = (matchId: string) => {
    const newHistory = matchHistory.filter(m => m.matchId !== matchId);
    setMatchHistory(newHistory);
    localStorage.setItem('volleyref_history', JSON.stringify(newHistory));
  };

  const handleGenerateDemoMatch = () => {
    const demo: MatchState = createInitialMatchState();
    demo.matchId = "DEMO-PRO";
    demo.league = "LIGUE NATIONALE PRO - FINALE";
    demo.city = "CASABLANCA";
    demo.hall = "COMPLEXE MOHAMMED V";
    demo.startTime = "20:00";
    demo.teamA.name = "DRAGONS VOLLEY";
    demo.teamB.name = "TITANS CLUB";

    const setResults = [
      { a: 25, b: 23, dur: 22, server: 'A' as const },
      { a: 22, b: 25, dur: 25, server: 'B' as const },
      { a: 25, b: 18, dur: 20, server: 'A' as const },
      { a: 24, b: 26, dur: 28, server: 'B' as const },
      { a: 15, b: 13, dur: 15, server: 'A' as const }
    ];

    demo.sets = setResults.map((res, i) => {
      const points: MatchSetPoint[] = [];
      let curA = 0;
      let curB = 0;
      let curServer = res.server;
      let formA = [0, 1, 2, 3, 4, 5];
      let formB = [0, 1, 2, 3, 4, 5];

      while(curA < res.a && curB < res.b) {
        const teamWins = Math.random() > 0.48 ? 'A' : 'B';

        // Rotation si changement de service
        if (teamWins === 'A' && curServer === 'B') {
           formA = [formA[1], formA[2], formA[3], formA[4], formA[5], formA[0]];
           curServer = 'A';
        } else if (teamWins === 'B' && curServer === 'A') {
           formB = [formB[1], formB[2], formB[3], formB[4], formB[5], formB[0]];
           curServer = 'B';
        }

        if (teamWins === 'A') curA++; else curB++;

        points.push({
          team: teamWins,
          servingPlayerIndex: teamWins === 'A' ? formA[0] : formB[0],
          scoreA: curA,
          scoreB: curB
        });
      }

      return {
        scoreA: res.a,
        scoreB: res.b,
        startTime: "20:" + (i * 30).toString().padStart(2, '0'),
        endTime: "20:" + (i * 30 + 25).toString().padStart(2, '0'),
        duration: res.dur,
        firstServingTeam: res.server,
        startingFormationA: [0, 1, 2, 3, 4, 5],
        startingFormationB: [0, 1, 2, 3, 4, 5],
        subsA: [], subsB: [],
        timeoutsTakenA: i % 2,
        timeoutsTakenB: (i + 1) % 2,
        points: points
      };
    });

    demo.teamA.setsWon = 3;
    demo.teamB.setsWon = 2;
    demo.remarks = "Match de démonstration avec scores de rotation complets.";

    const newHistory = [demo, ...matchHistory];
    setMatchHistory(newHistory);
    localStorage.setItem('volleyref_history', JSON.stringify(newHistory));
    handleViewArchivedMatch(demo);
  };

  const handleBackFromSummary = () => {
    if (selectedArchivedMatch) {
      setSelectedArchivedMatch(null);
      setView('archive');
    } else {
      setMatch(createInitialMatchState());
      setView('setup');
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 selection:bg-indigo-500/30">
      {view !== 'spectator' && (
      <header className="bg-slate-900/80 backdrop-blur-md border-b border-slate-800 p-4 sticky top-0 z-50 print:hidden">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center font-black shadow-lg shadow-indigo-500/20">V</div>
            <h1 className="text-xl font-black tracking-tighter uppercase italic">VolleyRef <span className="text-indigo-400">Pro</span></h1>
          </div>
          {view === 'setup' && (
            <button 
              onClick={() => setView('archive')}
              className="text-[10px] font-black uppercase text-indigo-400 bg-indigo-500/10 px-4 py-2 rounded-full border border-indigo-500/20 active:scale-95 transition-all flex items-center gap-2 hover:bg-indigo-500/20"
            >
              <span>📂</span>
              <span>Archives ({matchHistory.length})</span>
            </button>
          )}
        </div>
      </header>
      )}

      <main className={view === 'spectator' ? "" : "max-w-4xl mx-auto p-4 pb-24"}>
        {view === 'setup' && <MatchSetup onStart={handleStartMatch} initialData={match} onGenerateDemo={handleGenerateDemoMatch} />}
        {view === 'live' && <MatchLive match={match} setMatch={setMatch} onEnd={handleEndMatch} onSpectator={() => setView('spectator')} />}
        {view === 'summary' && <MatchSummary match={selectedArchivedMatch || match} setMatch={setMatch} onReset={handleBackFromSummary} />}
        {view === 'spectator' && <MatchSpectator match={match} onExit={() => setView('live')} />}
        {view === 'archive' && (
          <MatchArchive 
            history={matchHistory} 
            onSelect={handleViewArchivedMatch} 
            onBack={() => setView('setup')} 
            onDelete={handleDeleteMatch}
            onGenerateDemo={handleGenerateDemoMatch}
            onClear={() => {
              if(confirm("Effacer tout l'historique ?")) {
                setMatchHistory([]);
                localStorage.removeItem('volleyref_history');
              }
            }}
          />
        )}
      </main>

      {view !== 'spectator' && (
      <footer className="fixed bottom-0 left-0 right-0 p-4 bg-slate-950/50 backdrop-blur-sm pointer-events-none flex justify-center text-[10px] font-bold text-slate-600 uppercase tracking-widest z-0">
        FIVB Official Rules Compliant • 2025-2028
      </footer>
      )}
    </div>
  );
};

export default App;

