const FormationGrid = ({ team, tempF, setTempF }: any) => {
  const [activePos, setActivePos] = useState<number>(0);
  const regularPlayers = team.players.filter((p: any) => !p.isLibero && p.status === 'ACTIVE');

  const handleSelectPlayer = (playerIndex: number) => {
    const newF = [...tempF];
    if (newF.includes(playerIndex)) return;
    newF[activePos] = playerIndex;
    setTempF(newF);
    if (activePos < 5) setActivePos(activePos + 1);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
         <div className="w-3 h-3 rounded-full" style={{ backgroundColor: team.playerColor }}></div>
         <span className="text-white font-black uppercase text-xs">{team.name}</span>
      </div>
      <div className="grid grid-cols-6 gap-1">
        {['I','II','III','IV','V','VI'].map((pos, idx) => {
           const pIdx = tempF[idx];
           const player = pIdx !== -1 ? team.players[pIdx] : null;
           return (
             <button key={idx} onClick={() => setActivePos(idx)} className={`flex flex-col items-center justify-center p-1.5 rounded-xl border-2 transition-all ${activePos === idx ? 'border-indigo-500 bg-indigo-500/10' : 'border-slate-800 bg-slate-900'}`}>
               <span className="text-[8px] font-black text-slate-600 mb-0.5">{pos}</span>
               <span className={`text-xs font-black ${player ? 'text-white' : 'text-slate-700'}`}>{player ? player.number : '?'}</span>
             </button>
           );
        })}
      </div>
      <div className="bg-slate-900/40 rounded-2xl p-2 border border-slate-800">
         <div className="grid grid-cols-4 gap-2">
            {regularPlayers.map((p: any) => {
              const pIdx = team.players.indexOf(p);
              const isUsed = tempF.includes(pIdx);
              return (
                <button key={p.id} disabled={isUsed} onClick={() => handleSelectPlayer(pIdx)} className={`py-2 rounded-lg font-black text-xs border transition-all ${isUsed ? 'bg-slate-950 border-slate-900 text-slate-800' : 'bg-slate-800 border-slate-700 text-white'}`}>
                  {p.number}
                </button>
              );
            })}
         </div>
      </div>
    </div>
  );
};

import jsPDF from 'https://esm.sh/jspdf';
// Added missing type imports from types.ts
import { MatchState, Team, MatchSet } from './types';

const generateScoreSheetPDF = (match: MatchState) => {
    const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a3' });
    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();

    // Police et taille de base
    pdf.setFont('helvetica');
    pdf.setFontSize(8);

    let y = 10; // Position verticale de départ

    // --- EN-TÊTE ---
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'bold');
    pdf.text(`${match.league}`, 10, y);
    pdf.text(`${match.city} • ${match.hall || '—'}`, 10, y + 5);
    pdf.text(`MATCH N° ${match.matchId}`, pageWidth - 40, y);
    pdf.text(`${match.date} • ${match.scheduledTime}`, pageWidth - 40, y + 5);
    pdf.text(`${match.category} ${match.gender === 'M' ? 'HOMMES' : 'FEMMES'}`, pageWidth - 40, y + 10);
    y += 20;

    // Titre central
    pdf.setFontSize(12);
    pdf.text('FEUILLE DE MATCH OFFICIELLE', pageWidth / 2, y, { align: 'center' });
    pdf.setFontSize(6);
    pdf.text('FIVB 2025-2028', pageWidth / 2, y + 5, { align: 'center' });
    y += 15;

    // Équipes
    pdf.setFontSize(9);
    pdf.text(`(A) ${match.teamA.name}`, 10, y);
    pdf.text(`(B) ${match.teamB.name}`, pageWidth - 50, y);
    y += 10;

    // Ligne horizontale
    pdf.setLineWidth(0.5);
    pdf.line(10, y, pageWidth - 10, y);
    y += 5;

    // --- COLONNE GAUCHE : ÉQUIPE A ---
    // Fix: Using the return value of drawTeamRoster to update y
    y = drawTeamRoster(pdf, match.teamA, 'A', 10, y);

    // --- COLONNE DROITE : SETS ---
    for (let i = 0; i < match.sets.length; i++) {
        const set = match.sets[i];
        if (!set) continue;
        y = drawSetBlock(pdf, set, i + 1, match, y);
    }

    // --- REMARQUES / SANCTIONS ---
    pdf.setFontSize(8);
    pdf.setFont('helvetica', 'bold');
    pdf.text('REMARQUES / SANCTIONS', 10, y + 5);
    y += 10;
    pdf.setFont('helvetica', 'normal');
    if (match.playerSanctions.length > 0) {
        match.playerSanctions.forEach((s, i) => {
            const player = match.teamA.players.find(p => p.id === s.playerId) || match.teamB.players.find(p => p.id === s.playerId);
            pdf.text(`${s.type} - ${s.team} #${player?.number || '?' } (${s.scoreAtSanction})`, 10, y + i * 5);
        });
        y += match.playerSanctions.length * 5;
    } else if (match.remarks) {
        pdf.text(match.remarks, 10, y);
        y += 5;
    } else {
        pdf.text('Néant.', 10, y);
        y += 5;
    }

    // Sauvegarder le PDF
    pdf.save(`Feuille_Match_${match.matchId}_A3.pdf`);
};

// Fonction pour dessiner la liste des joueurs d'une équipe
const drawTeamRoster = (pdf: any, team: Team, label: string, startX: number, startY: number) => {
    // Fix: Changed const to let for yStart as it is reassigned
    let yStart = startY;
    const lineHeight = 5;
    const colWidths = [15, 60, 30]; // Largeurs des colonnes N°, Nom Prénom, Licence

    // Titre
    pdf.setFontSize(8);
    pdf.setFont('helvetica', 'bold');
    pdf.text(`ÉQUIPE ${label}`, startX, yStart);
    yStart += 5;

    // En-tête des colonnes
    pdf.setFontSize(6);
    pdf.setFont('helvetica', 'bold');
    pdf.text('N°', startX, yStart);
    pdf.text('Nom Prénom', startX + colWidths[0], yStart);
    pdf.text('Licence', startX + colWidths[0] + colWidths[1], yStart);
    yStart += 5;

    // Ligne horizontale
    pdf.setLineWidth(0.3);
    pdf.line(startX, yStart, startX + colWidths.reduce((a, b) => a + b, 0), yStart);
    yStart += 2;

    // Joueurs
    pdf.setFontSize(7);
    pdf.setFont('helvetica', 'normal');
    team.players.forEach((p, index) => {
        const y = yStart + index * lineHeight;
        pdf.text(p.number.toString(), startX, y);
        pdf.text(p.name, startX + colWidths[0], y);
        pdf.text(p.licenseNumber, startX + colWidths[0] + colWidths[1], y);

        // Indicateurs Captain/Libero
        if (p.isCaptain) {
            pdf.setFontSize(5);
            pdf.text('C', startX + colWidths[0] + colWidths[1] - 5, y);
            pdf.setFontSize(7);
        }
        if (p.isLibero) {
            pdf.setFontSize(5);
            pdf.text('L', startX + colWidths[0] + colWidths[1] - 10, y);
            pdf.setFontSize(7);
        }
    });

    // Remplissage vide
    const remainingRows = Math.max(0, 14 - team.players.length);
    for (let i = 0; i < remainingRows; i++) {
        const y = yStart + (team.players.length + i) * lineHeight;
        pdf.text('', startX, y);
        pdf.text('', startX + colWidths[0], y);
        pdf.text('', startX + colWidths[0] + colWidths[1], y);
    }

    // Libéros
    yStart += (team.players.length + remainingRows) * lineHeight + 5;
    pdf.setFontSize(6);
    pdf.setFont('helvetica', 'bold');
    pdf.text('LIBÉRO 1:', startX, yStart);
    pdf.text(team.players.filter(p => p.isLibero)[0]?.number || '-', startX + 20, yStart);
    yStart += 5;
    pdf.text('LIBÉRO 2:', startX, yStart);
    pdf.text(team.players.filter(p => p.isLibero)[1]?.number || '-', startX + 20, yStart);
    yStart += 5;

    // Coach et Adjoint
    pdf.setFontSize(6);
    pdf.setFont('helvetica', 'normal');
    pdf.text(`COACH: ${team.coach}`, startX, yStart);
    yStart += 5;
    pdf.text(`ADJOINT: ${team.assistantCoach1}`, startX, yStart);
    yStart += 5;

    return yStart;
};

// Fonction pour dessiner un bloc de set
const drawSetBlock = (pdf: any, set: MatchSet, setNumber: number, match: MatchState, startY: number) => {
    // Fix: Changed const to let for yStart as it is reassigned
    let yStart = startY;
    const lineHeight = 5;
    const colWidth = 20; // Largeur des colonnes I à VI

    // Titre du set
    pdf.setFontSize(8);
    pdf.setFont('helvetica', 'bold');
    pdf.text(`SET ${setNumber} - DURÉE: ${set.duration}MN`, 10, yStart);
    yStart += 5;

    // Fix: Calculate pageWidth within the function scope
    const pageWidth = pdf.internal.pageSize.getWidth();
    // Colonnes pour l'équipe A et B
    const startXLeft = 10;
    const startXRight = pageWidth / 2 + 10;

    // En-têtes
    pdf.setFontSize(6);
    pdf.setFont('helvetica', 'bold');
    pdf.text('(A) ÉQUIPE A', startXLeft, yStart);
    pdf.text('(B) ÉQUIPE B', startXRight, yStart);
    yStart += 5;

    // Sous-en-têtes (Svc, I, II, III, IV, V, VI)
    pdf.setFontSize(5);
    pdf.text('Svc', startXLeft, yStart);
    ['I','II','III','IV','V','VI'].forEach((pos, i) => {
        pdf.text(pos, startXLeft + 10 + i * colWidth, yStart);
    });
    pdf.text('Svc', startXRight, yStart);
    ['I','II','III','IV','V','VI'].forEach((pos, i) => {
        pdf.text(pos, startXRight + 10 + i * colWidth, yStart);
    });
    yStart += 5;

    // Départ (Starting Formation)
    pdf.setFontSize(6);
    pdf.setFont('helvetica', 'normal');
    pdf.text('Départ', startXLeft, yStart);
    pdf.text('Départ', startXRight, yStart);
    yStart += 5;

    // Dessiner les numéros des joueurs (exemple simplifié)
    // Vous devrez adapter selon la formation réelle
    const formationA = set.startingFormationA.map(idx => match.teamA.players[idx]);
    const formationB = set.startingFormationB.map(idx => match.teamB.players[idx]);

    formationA.forEach((p, i) => {
        if (p) {
            pdf.text(p.number.toString(), startXLeft + 10 + i * colWidth, yStart);
        }
    });
    formationB.forEach((p, i) => {
        if (p) {
            pdf.text(p.number.toString(), startXRight + 10 + i * colWidth, yStart);
        }
    });
    yStart += 5;

    // Autres lignes (Remplacements, Scores, etc.) - À adapter selon vos besoins
    // Pour l'instant, on ajoute juste une ligne vide
    yStart += 10;

    return yStart;
};

import React, { useRef, useMemo } from 'react';
