interface Props {
  match: MatchState;
  onBack: () => void;
}

export const ScoreSheet: React.FC<Props> = ({ match, onBack }) => {
  const sheetRef = useRef<HTMLDivElement>(null);

  const handleDownloadPDF = () => {
    const input = sheetRef.current;
    if (!input) return;

    const originalTransform = input.style.transform;
    const originalOverflow = input.style.overflow;

    input.style.transform = '';
    input.style.overflow = 'visible';

    setTimeout(() => {
      html2canvas(input, { 
        scale: 4,
        logging: false, 
        useCORS: true,
        backgroundColor: '#ffffff',
      }).then((canvas) => {
        input.style.transform = originalTransform;
        input.style.overflow = originalOverflow;

        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a3' });
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
        pdf.save(`Feuille_Match_${match.matchId}_A3.pdf`);
      }).catch(error => {
        console.error('Erreur PDF:', error);
        input.style.transform = originalTransform;
        input.style.overflow = originalOverflow;
      });
    }, 100);
  };

  return (
    <div className="bg-slate-900 min-h-screen p-4 md:p-8 font-sans print:bg-white print:p-0 flex flex-col items-center">
      <div className="no-print fixed top-4 right-4 z-[600] flex gap-3 flex-wrap justify-end">
          <button onClick={onBack} className="bg-slate-950 text-white px-4 py-3 rounded-2xl font-black uppercase text-[10px] border border-slate-700 hover:bg-slate-800 transition-all">← Retour</button>
          <button onClick={handleDownloadPDF} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black uppercase text-[10px] border-b-4 border-indigo-900 active:border-b-0 transition-all shadow-lg hover:bg-indigo-500">📄 PDF (A3)</button>
      </div>

      <div className="mx-auto print:mx-0">
        <div ref={sheetRef} className="w-[210mm] h-auto min-h-[297mm] bg-white text-black p-4 text-[7px] flex flex-col gap-2 shadow-2xl print:shadow-none font-sans">

            <HeaderInfo match={match} />

