const SetBlock: React.FC<{set: MatchSet | undefined, setNumber: number, match: MatchState}> = ({ set, setNumber, match }) => {
    if (!set) return null;
    const isTeamALeft = setNumber % 2 !== 0;
    const teamLeft = isTeamALeft ? match.teamA : match.teamB;
    const teamRight = isTeamALeft ? match.teamB : match.teamA;
    const labelLeft = isTeamALeft ? 'A' : 'B';
    const labelRight = isTeamALeft ? 'B' : 'A';

    return (
        <div className="border-[1.5px] border-black flex flex-col">
            <div className="bg-black text-white text-[8px] font-black py-0.5 px-3 flex justify-between items-center uppercase">
