            </div>
            <div className="flex divide-x-[1.5px] divide-black">
                <TeamSetColumn set={set} team={teamLeft} match={match} setNumber={setNumber} teamLabel={labelLeft} />
                <TeamSetColumn set={set} team={teamRight} match={match} setNumber={setNumber} teamLabel={labelRight} />
            </div>
        </div>
    );
};

const TeamSetColumn: React.FC<{set: MatchSet, team: Team, match: MatchState, setNumber: number, teamLabel: 'A' | 'B'}> = ({set, team, match, setNumber, teamLabel}) => {
    const formationIdx = teamLabel === 'A' ? set.startingFormationA : set.startingFormationB;
    const players = formationIdx.map(idx => team.players[idx]);
    const subs = teamLabel === 'A' ? set.subsA : set.subsB;
    const isReceivingTeam = set.firstServingTeam !== teamLabel;

    const serviceHistory = useMemo(() => {
        const rotationTurns: string[][] = Array.from({ length: 6 }, () => []);
        let lastServingTeam = set.firstServingTeam;

        set.points.forEach((pt, idx) => {
            const currentTeamScore = teamLabel === 'A' ? pt.scoreA : pt.scoreB;
            if (pt.team !== lastServingTeam) {
                if (lastServingTeam === teamLabel) {
                    const servingPlayerIdx = pt.servingPlayerIndex;
                    let posIdx = formationIdx.indexOf(servingPlayerIdx);
                    if (posIdx !== -1) {
                        rotationTurns[posIdx].push(currentTeamScore.toString());
                    }
                }
                lastServingTeam = pt.team;
            }
            if (idx === set.points.length - 1 && pt.team === teamLabel) {
                 const servingPlayerIdx = pt.servingPlayerIndex;
                 let posIdx = formationIdx.indexOf(servingPlayerIdx);
                 if (posIdx !== -1) {
                     rotationTurns[posIdx].push(currentTeamScore.toString());
                 }
            }
        });

        return rotationTurns;
    }, [set.points, teamLabel, formationIdx, set.firstServingTeam]);

    return (
        <div className="flex-1 flex flex-col bg-white">
            <div className="text-center font-black py-0.5 border-b border-black uppercase bg-slate-100 text-[8px] flex justify-between px-2">
                <span>{teamLabel}</span><span>{team.name}</span>
            </div>

            <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center text-[6px] font-black uppercase bg-slate-50 border-b border-black">
                <div className="border-r border-black">Svc</div>
                {['I','II','III','IV','V','VI'].map(pos => <div key={pos} className="border-r border-black last:border-r-0">{pos}</div>)}
            </div>

            {/* Formation de départ */}
            <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center h-4 items-center border-b border-black">
                <div className="border-r border-black text-[5px] font-black bg-slate-50 h-full flex items-center justify-center">N°</div>
                {players.map((p, i) => <div key={i} className="border-r border-black last:border-r-0 h-full flex items-center justify-center font-black text-[9px]">{p?.number}</div>)}
            </div>

            {/* Remplaçants (C'est ici qu'on applique la modification) */}
             <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center h-4 items-center border-b border-black">
                <div className="border-r border-black text-[5px] font-black bg-slate-50 h-full flex items-center justify-center italic">Remp.</div>
                {players.map((p, i) => {
                   // Trouver le premier remplacement où le titulaire p est sorti
                   const initialSub = subs.find(s => s.playerOutId === p?.id && !s.isReturn);
                   if (!initialSub) return <div key={i} className="border-r border-black last:border-r-0 h-full"></div>;

                   // Trouver le joueur remplaçant
                   const substitutePlayer = team.players.find(pl => pl.id === initialSub.playerInId);
                   if (!substitutePlayer) return <div key={i} className="border-r border-black last:border-r-0 h-full"></div>;

                   // Vérifier si le remplaçant est ressorti (titulaire revenu)
                   const hasReturned = subs.some(s => s.playerOutId === substitutePlayer.id && s.isReturn);

                   return (
                     <div key={i} className="border-r border-black last:border-r-0 h-full flex items-center justify-center font-black text-[9px]">
                        <span className={hasReturned ? "border border-black rounded-full w-3.5 h-3.5 flex items-center justify-center bg-transparent" : ""}>
                            {substitutePlayer.number}
                        </span>
                     </div>
                   );
                })}
            </div>

            <div className="flex-1 grid grid-cols-[20px_repeat(6,1fr)] divide-x divide-black border-b border-black">
                <div className="flex flex-col bg-slate-50 border-r border-black divide-y divide-black">
                    {[1,2,3,4].map(n => <div key={n} className="flex-1 flex items-center justify-center text-[5px] font-bold">{n}</div>)}
                </div>
                {serviceHistory.map((history, colIdx) => (
                    <div key={colIdx} className="flex flex-col divide-y divide-black">
                        {[0,1,2,3].map(rowIdx => {
                            const score = history[rowIdx];
                            const isFirstRecvBox = isReceivingTeam && colIdx === 0 && rowIdx === 0;
                            return (
                                <div key={rowIdx} className={`flex-1 flex items-center justify-center text-[9px] font-black h-4 ${isFirstRecvBox ? 'bg-slate-100' : ''}`}>
                                    {isFirstRecvBox && <div className="absolute flex items-center justify-center text-black font-normal">X</div>}
                                    {score}
                                </div>
                            );
                        })}
                    </div>
                ))}
            </div>

            <div className="bg-white h-6 flex items-center px-2 mt-auto">
                <span className="text-[7px] font-black uppercase text-slate-500 italic flex-1">T.M.</span>
                <div className="flex gap-1">
                    <div className="border border-black w-6 h-4 flex items-center justify-center text-[8px] font-black">
                        {match.history.find(e => e.type === 'TIMEOUT' && e.team === teamLabel && e.setIndex === setNumber-1)?.score || ''}
                    </div>
                    <div className="border border-black w-6 h-4 flex items-center justify-center text-[8px] font-black">
                        {match.history.filter(e => e.type === 'TIMEOUT' && e.team === teamLabel && e.setIndex === setNumber-1)[1]?.score || ''}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useRef, useMemo } from 'react';
