          </div>
        </div>

        <div className="flex flex-col gap-2 max-h-[500px] overflow-y-auto custom-scrollbar pr-1">
          {team.players.map((p, index) => (
            <div key={p.id} className="bg-slate-900 border border-slate-800 rounded-xl p-2 flex flex-wrap sm:flex-nowrap items-center gap-2 shadow-sm hover:border-slate-700 transition-colors">

              {/* Numéro */}
              <div className="w-12 shrink-0">
                 <input 
                  type="number" 
                  value={p.number} 
                  onChange={e => onUpdatePlayer(teamId, index, 'number', parseInt(e.target.value) || 0)} 
                  className="w-full h-10 bg-slate-950 text-center rounded-lg font-black text-white border border-slate-700 text-sm focus:border-indigo-500 outline-none" 
                  placeholder="#" 
                />
              </div>

              {/* Infos Joueur (Nom & Licence) */}
              <div className="flex-1 min-w-[140px] flex flex-col gap-1">
                <input 
                  type="text" 
                  placeholder="Nom du joueur" 
                  value={p.name} 
                  onChange={e => onUpdatePlayer(teamId, index, 'name', e.target.value)} 
                  className="w-full bg-transparent rounded px-1 py-0.5 font-bold text-slate-200 text-xs outline-none border-b border-transparent focus:border-slate-700 placeholder:text-slate-600" 
                />
                <input 
                  type="text" 
                  placeholder="N° Licence" 
                  value={p.licenseNumber} 
                  onChange={e => onUpdatePlayer(teamId, index, 'licenseNumber', e.target.value)} 
                  className="w-full bg-transparent rounded px-1 py-0.5 font-mono text-slate-400 text-[10px] outline-none border-b border-transparent focus:border-slate-700 placeholder:text-slate-700" 
                />
              </div>

              {/* Contrôles Rôles */}
              <div className="flex items-center gap-1 shrink-0 bg-slate-950/50 p-1.5 rounded-lg border border-slate-800 ml-auto sm:ml-0">
                {/* CHECKBOX CAPITAINE */}
                <label className={`flex flex-col items-center justify-center cursor-pointer group px-1 ${p.isLibero ? 'opacity-30 cursor-not-allowed' : ''}`}>
                  <input 
                    type="checkbox"
                    checked={p.isCaptain}
                    disabled={p.isLibero}
                    onChange={(e) => {
                      if (e.target.checked) {
                        // Règle : Un seul capitaine. On décoche les autres.
                        team.players.forEach((_, i) => onUpdatePlayer(teamId, i, 'isCaptain', false));
                        // Règle : Libero ne peut pas être capitaine (déjà géré par disabled mais sécurité)
                        if (p.isLibero) onUpdatePlayer(teamId, index, 'isLibero', false);
                        onUpdatePlayer(teamId, index, 'isCaptain', true);
                      } else {
                        onUpdatePlayer(teamId, index, 'isCaptain', false);
                      }
                    }}
                    className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-indigo-600 accent-indigo-600 focus:ring-indigo-500 cursor-pointer disabled:cursor-not-allowed"
                  />
                  <span className={`text-[6px] font-black uppercase mt-0.5 ${p.isCaptain ? 'text-indigo-400' : 'text-slate-600 group-hover:text-slate-400'}`}>CAP</span>
                </label>

                <div className="w-px h-6 bg-slate-800 mx-1"></div>

                {/* CHECKBOX LIBERO */}
                <label className={`flex flex-col items-center justify-center cursor-pointer group px-1 ${p.isCaptain ? 'opacity-30 cursor-not-allowed' : ''}`}>
                  <input 
                    type="checkbox"
                    checked={p.isLibero}
                    disabled={p.isCaptain}
                    onChange={(e) => {
                       if (e.target.checked) {
                          if (liberosCount >= 2) {
                             alert("Maximum 2 Libéros autorisés.");
                             return;
                          }
                          // Règle : Capitaine ne peut pas être Libero
                          if (p.isCaptain) onUpdatePlayer(teamId, index, 'isCaptain', false);
                          onUpdatePlayer(teamId, index, 'isLibero', true);
                       } else {
                          onUpdatePlayer(teamId, index, 'isLibero', false);
                       }
                    }}
                    className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-amber-500 accent-amber-500 focus:ring-amber-500 cursor-pointer disabled:cursor-not-allowed"
                  />
                  <span className={`text-[6px] font-black uppercase mt-0.5 ${p.isLibero ? 'text-amber-500' : 'text-slate-600 group-hover:text-slate-400'}`}>LIB</span>
                </label>
              </div>

              <button 
                type="button"
                onClick={() => setPlayerToDeleteIndex(index)} 
                className="w-8 h-8 rounded-lg bg-rose-950/20 text-rose-500 border border-rose-900/20 flex items-center justify-center hover:bg-rose-500 hover:text-white transition-all shrink-0"
                title="Supprimer"
              >
                ×
              </button>
            </div>
          ))}
        </div>

        <button 
          onClick={onAddPlayer} 
          disabled={!canAddPlayer}
          className={`w-full py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 border-dashed ${canAddPlayer ? 'bg-indigo-500/5 border-indigo-500/20 text-indigo-400 hover:bg-indigo-500/10' : 'bg-slate-900 border-slate-800 text-slate-700 cursor-not-allowed'}`}
        >
          {canAddPlayer ? '+ Ajouter un joueur' : 'Effectif maximum atteint (14)'}
        </button>

        {/* MODALE DE CONFIRMATION DE SUPPRESSION DE JOUEUR */}
        {playerToDeleteIndex !== null && (
          <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-sm z-[700] flex items-center justify-center p-4" onClick={() => setPlayerToDeleteIndex(null)}>
            <div className="bg-slate-900 rounded-3xl border border-slate-800 p-6 w-full max-w-sm shadow-2xl animate-in zoom-in duration-200" onClick={e => e.stopPropagation()}>
               <div className="text-center space-y-4">
                  <div className="w-12 h-12 rounded-full bg-rose-500/20 text-rose-500 flex items-center justify-center text-2xl mx-auto">🗑️</div>
                  <h3 className="text-lg font-black text-white uppercase italic">Supprimer le joueur ?</h3>
                  <div className="text-sm text-slate-300 font-bold">
                     #{team.players[playerToDeleteIndex].number} {team.players[playerToDeleteIndex].name}
                  </div>
                  <p className="text-xs text-slate-400 font-medium">Voulez-vous vraiment retirer ce joueur de l'effectif ?</p>

                  <div className="grid grid-cols-2 gap-3 pt-4">
                     <button onClick={() => setPlayerToDeleteIndex(null)} className="py-3 rounded-xl bg-slate-800 text-slate-400 font-black text-xs uppercase hover:bg-slate-700 transition-all">Annuler</button>
                     <button onClick={() => { onRemovePlayer(playerToDeleteIndex); setPlayerToDeleteIndex(null); }} className="py-3 rounded-xl bg-rose-600 text-white font-black text-xs uppercase hover:bg-rose-500 transition-all shadow-lg shadow-rose-600/20">Supprimer</button>
                  </div>
               </div>
            </div>
         </div>
        )}
      </div>
    </div>
  );
};

export const MatchSetup: React.FC<Props> = ({ onStart, initialData, onGenerateDemo }) => {
  const [step, setStep] = useState<1 | 2 | 3 | 4 | 5>(1);
  const [formData, setFormData] = useState<Partial<MatchState>>({ ...initialData, servingTeam: 'A' });

  const handleFormChange = (field: keyof MatchState, value: any) => setFormData(prev => ({...prev, [field]: value }));
  const updateTeamInfo = (teamId: 'A' | 'B', field: keyof Team, value: any) => setFormData(p => ({...p, [teamId === 'A' ? 'teamA' : 'teamB']: { ...p[teamId === 'A' ? 'teamA' : 'teamB']!, [field]: value }}));

  const updatePlayer = (teamId: 'A' | 'B', index: number, field: keyof Player, value: any) => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    const players = [...team.players];
    players[index] = { ...players[index], [field]: value };
    setFormData(p => ({...p, [tk]: { ...team, players }}));
  };

  const addPlayer = (teamId: 'A' | 'B') => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    if (team.players.length >= 14) return;
    setFormData(p => ({...p, [tk]: { ...team, players: [...team.players, { id: Date.now().toString(), number: team.players.length + 1, name: '', licenseNumber: '', isLibero: false, isCaptain: false, status: 'ACTIVE' }]}}));
  };

  const removePlayer = (teamId: 'A' | 'B', index: number) => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
