const FormationEntry = ({ team, tempF, setTempF }: any) => {
  const players = team.players.filter((p: any) => !p.isLibero);
  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <div className="w-4 h-4 rounded-full shadow-lg" style={{ backgroundColor: team.color }}></div>
        <span className="font-black text-sm text-white uppercase tracking-tighter">{team.name}</span>
      </div>
      <div className="grid grid-cols-6 gap-2">
        {tempF.map((pIdx: number, i: number) => (
           <div key={i} className={`bg-slate-950 border-2 rounded-2xl p-2.5 text-center transition-all ${pIdx === -1 ? 'border-dashed border-slate-800' : 'border-indigo-500 bg-indigo-500/5'}`}>
              <div className="text-[8px] text-slate-600 font-black mb-1">{['I','II','III','IV','V','VI'][i]}</div>
              <div className="text-base font-black text-white">{pIdx === -1 ? '?' : team.players[pIdx].number}</div>
           </div>
        ))}
      </div>
      <div className="bg-slate-950/40 p-4 rounded-[2rem] border border-slate-800">
        <label className="text-[8px] font-black text-slate-600 uppercase mb-3 block text-center">Sélectionner par ordre de position (I à VI)</label>
        <div className="grid grid-cols-6 gap-2">
          {players.map((p: any) => {
            const idx = team.players.indexOf(p);
            const used = tempF.includes(idx);
            return (
              <button 
                key={p.id} 
                disabled={used} 
                onClick={() => {
                  const nf = [...tempF];
                  const empty = nf.indexOf(-1);
                  if (empty !== -1) { nf[empty] = idx; setTempF(nf); }
                }} 
                className={`w-full aspect-square flex items-center justify-center rounded-xl font-black text-sm border-2 transition-all ${used ? 'bg-slate-900 border-slate-800 text-slate-700' : 'bg-slate-800 border-slate-700 text-white hover:border-indigo-500 active:scale-90'}`}
              >
                {p.number}
              </button>
            )
          })}
        </div>
        <button onClick={() => setTempF([-1,-1,-1,-1,-1,-1])} className="w-full mt-4 text-[9px] font-black text-rose-500 uppercase py-2 bg-rose-500/5 rounded-xl border border-rose-500/10 active:scale-95 transition-all">Réinitialiser la formation</button>
      </div>
    </div>
  );
}

