                  <button onClick={() => handleFormChange('gender', 'F')} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 ${formData.gender === 'F' ? 'bg-rose-600 border-rose-400 text-white' : 'bg-slate-900 border-slate-800 text-slate-600'}`}>Féminin</button>
