              <InputField label="Marqueur" value={formData.scorer} onChange={v => handleFormChange('scorer', v)} placeholder="Nom Prénom" />

              <div className="pt-4 border-t border-slate-800 space-y-3">
                <label className="text-[9px] font-black text-slate-500 uppercase px-1">Juges de ligne (Optionnel)</label>
                <div className="grid grid-cols-2 gap-3">
                  <input value={formData.lineJudge1} onChange={e => handleFormChange('lineJudge1', e.target.value)} placeholder="Juge 1" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge2} onChange={e => handleFormChange('lineJudge2', e.target.value)} placeholder="Juge 2" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge3} onChange={e => handleFormChange('lineJudge3', e.target.value)} placeholder="Juge 3" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge4} onChange={e => handleFormChange('lineJudge4', e.target.value)} placeholder="Juge 4" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                </div>
              </div>
            </div>
          </div>
