      {step === 3 && (
        <div className="space-y-6">
          <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">3. Données Équipe A</h2>
          <TeamConfig 
            teamId="A" 
            team={formData.teamA!} 
            onUpdatePlayer={updatePlayer} 
            onUpdateTeam={updateTeamInfo} 
