          <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">4. Données Équipe B</h2>
          <TeamConfig 
            teamId="B" 
            team={formData.teamB!} 
            onUpdatePlayer={updatePlayer} 
            onUpdateTeam={updateTeamInfo} 
            onAddPlayer={() => addPlayer('B')} 
            onRemovePlayer={(idx) => removePlayer('B', idx)} 
          />
          <StepActions onBack={() => setStep(3)} onNext={() => setStep(5)} nextDisabled={!isStep4Valid} />
        </div>
      )}

      {step === 5 && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom duration-500">

           {/* Section TOSS */}
           <div className="bg-gradient-to-br from-indigo-900/40 to-slate-900/40 p-4 rounded-3xl border border-indigo-500/20 text-center space-y-3 max-w-lg mx-auto">
             <h3 className="text-xs font-black text-white uppercase tracking-widest">Qui sert en premier ?</h3>
             <div className="flex gap-4">
                <button 
                  onClick={() => handleFormChange('servingTeam', 'B')}
