const FormationEntry = ({ team, tempF, setTempF }: any) => {
  const players = team.players.filter((p: any) => p.status === 'ACTIVE' && !p.isLibero);

  const handlePlayerToggle = (idx: number) => {
    // Si le joueur est déjà sur le terrain, on le retire
    const currentPos = tempF.indexOf(idx);
    if (currentPos !== -1) {
      const newF = [...tempF];
      newF[currentPos] = -1;
      setTempF(newF);
      return;
    }

    // Sinon on l'ajoute à la première place libre
    const firstEmpty = tempF.indexOf(-1);
    if (firstEmpty !== -1) {
      const newF = [...tempF];
      newF[firstEmpty] = idx;
      setTempF(newF);
    }
  };

  const removeFromPos = (posIndex: number) => {
      const newF = [...tempF];
      newF[posIndex] = -1;
      setTempF(newF);
  };

  return (
    <div className="space-y-4">
      {/* En-tête Équipe Compact */}
      <div className="flex items-center gap-2 bg-slate-950/50 p-2 rounded-xl border border-slate-800">
        <div className="w-5 h-5 rounded-full shadow-lg border border-white/10 shrink-0" style={{ backgroundColor: team.color }}></div>
        <span className="font-black text-xs text-white uppercase tracking-tighter truncate">{team.name}</span>
        <button onClick={() => setTempF([-1,-1,-1,-1,-1,-1])} className="ml-auto text-[8px] font-bold text-rose-500 hover:text-rose-400 uppercase bg-rose-500/10 px-2 py-1 rounded">Reset</button>
      </div>

      {/* Grille de Positionnement Compacte */}
      <div className="grid grid-cols-2 gap-2">
        {tempF.map((pIdx: number, i: number) => {
            const p = pIdx !== -1 ? team.players[pIdx] : null;
            return (
                <div key={i} className={`relative h-14 rounded-lg border transition-all flex items-center px-2 gap-2 group ${p ? 'bg-white border-white' : 'bg-slate-900 border-slate-800'}`}>
                    <div className="w-6 h-6 rounded bg-slate-200 text-slate-600 flex items-center justify-center text-[8px] font-black">{['I','II','III','IV','V','VI'][i]}</div>
                    {p ? (
                        <>
                            <span className={`text-xl font-black leading-none ${p.isLibero ? 'text-amber-500' : 'text-slate-900'}`}>{p.number}</span>
                             {p.isLibero && <span className="text-[6px] font-black uppercase text-amber-500 ml-1">L</span>}
                            <button 
                            onClick={() => removeFromPos(i)}
                            className="absolute top-1 right-1 w-4 h-4 bg-rose-500 text-white rounded-full flex items-center justify-center text-[9px] opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                            ×
                            </button>
                        </>
                    ) : (
                        <span className="text-[8px] font-bold uppercase text-slate-600 ml-1">Vide</span>
                    )}
                </div>
            )
        })}
      </div>

      {/* Liste des Joueurs Compacte */}
      <div className="bg-slate-950/30 rounded-2xl p-3 border border-slate-800/50">
        <div className="flex flex-wrap gap-1.5 justify-center">
          {players.map((p: any) => {
            const idx = team.players.indexOf(p);
            const isSelected = tempF.includes(idx);

            return (
              <button 
                key={p.id} 
                disabled={isSelected} 
                onClick={() => handlePlayerToggle(idx)} 
                className={`w-9 h-9 flex items-center justify-center rounded-lg border transition-all text-sm font-black
                    ${isSelected 
                        ? 'bg-slate-900 border-slate-800 text-slate-600 cursor-not-allowed' 
                        : p.isLibero 
                            ? 'bg-amber-100 border-amber-200 text-amber-700 hover:border-amber-500 active:scale-95'
                            : 'bg-white border-slate-200 text-slate-900 hover:border-indigo-500 active:scale-95'
                    }
                `}
              >
                {p.number}
              </button>
            )
          })}
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { Team, Player, PlayerSanction, SanctionType } from '../types';

interface Props {
  teamLeft: Team;
  teamRight: Team;
  servingTeamId: 'A' | 'B' | null;
  leftId: 'A' | 'B';
  rightId: 'A' | 'B';
  sanctions: PlayerSanction[];
}

export const CourtView: React.FC<Props> = ({ teamLeft, teamRight, servingTeamId, leftId, rightId, sanctions }) => {
  const getP = (team: Team, posIdx: number) => {
    const pIdx = team.formation[posIdx];
    return pIdx !== -1 ? team.players[pIdx] : null;
  };

  /**
   * Positionnement des joueurs sur le terrain (Vue Arbitre).
   * Le filet est vertical au centre (50%).
   * 
   * Team Left (Attaque vers la droite):
   * Front Row (Près du filet): 4 (Haut), 3 (Milieu), 2 (Bas)
   * Back Row (Fond de court): 5 (Haut), 6 (Milieu), 1 (Bas)
   * 
   * Team Right (Attaque vers la gauche):
   * Front Row (Près du filet): 2 (Haut), 3 (Milieu), 4 (Bas)
   * Back Row (Fond de court): 1 (Haut), 6 (Milieu), 5 (Bas)
   */
  const getCoords = (teamSide: 'left' | 'right', pos: number) => {
    // pos est l'index 0..5 correspondant à la position I..VI
    // I=0, II=1, III=2, IV=3, V=4, VI=5

    // Mapping Position FIVB -> Coordonnées CSS (left%, top%)
    // Pour l'équipe de GAUCHE (Team Left)
    const leftTeamMap: Record<number, [number, number]> = {
      3: [68, 20], // IV (Front-Left) -> Haut Droite (près filet)
      2: [68, 50], // III (Front-Center) -> Milieu Droite
      1: [68, 80], // II (Front-Right) -> Bas Droite
      0: [25, 80], // I (Back-Right) -> Bas Gauche
      5: [25, 50], // VI (Back-Center) -> Milieu Gauche
      4: [25, 20], // V (Back-Left) -> Haut Gauche
    };

    // Pour l'équipe de DROITE (Team Right) - Symétrie point par rapport au centre
    // IV (Front-Left) est en Bas Gauche (près filet)
    // II (Front-Right) est en Haut Gauche (près filet)
    const rightTeamMap: Record<number, [number, number]> = {
      1: [32, 20], // II (Front-Right) -> Haut Gauche (près filet)
      2: [32, 50], // III (Front-Center) -> Milieu Gauche
      3: [32, 80], // IV (Front-Left) -> Bas Gauche
      4: [75, 80], // V (Back-Left) -> Bas Droite
      5: [75, 50], // VI (Back-Center) -> Milieu Droite
      0: [75, 20], // I (Back-Right) -> Haut Droite
    };

    const [x, y] = teamSide === 'left' ? leftTeamMap[pos] : rightTeamMap[pos];

    // Si c'est l'équipe de droite, on ajoute 50% au left car elle commence à la moitié
    const finalLeft = teamSide === 'left' ? x/2 : 50 + (x/2);

    return { left: `${finalLeft}%`, top: `${y}%` };
  };

  return (
    <div className="w-full bg-slate-900/50 p-2 rounded-xl border border-slate-800 shadow-inner">
      <div className="relative aspect-[16/9] bg-[#e67e22] border-2 border-white/80 overflow-hidden rounded-md shadow-2xl relative">

        {/* Texture Sol */}
        <div className="absolute inset-0 opacity-10" style={{backgroundImage: 'radial-gradient(circle, #000 1px, transparent 1px)', backgroundSize: '10px 10px'}}></div>

        {/* Lignes structurelles */}
        {/* Filet Central */}
        <div className="absolute inset-y-0 left-1/2 -translate-x-1/2 w-1.5 h-full bg-white/90 z-10 shadow-[0_0_10px_rgba(0,0,0,0.5)] flex flex-col justify-between py-1">
             <div className="w-full h-full border-l border-r border-slate-300 bg-[url('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAYAAACp8Z5+AAAAIklEQVQIW2NkQAKrVq36zwjjgzjwqoAb4ODgQmIgC8AcBgA5UwfwVtZRqmAAAAAElFTkSuQmCC')] opacity-50"></div>
        </div>

        {/* Lignes des 3 mètres (Attack Lines) */}
        <div className="absolute inset-y-0 left-[33%] w-1 bg-white/40"></div>
        <div className="absolute inset-y-0 right-[33%] w-1 bg-white/40"></div>

        {/* Joueurs Gauche */}
        {[0, 1, 2, 3, 4, 5].map(pos => {
          const p = getP(teamLeft, pos);
          // La clé (key) doit être l'ID du joueur pour que React comprenne le mouvement
          // Si pas de joueur (p est null), on utilise la position comme fallback
          const key = p ? `p-${p.id}` : `left-pos-${pos}`;
          return (
            <Pos 
              key={key}
              label={['I','II','III','IV','V','VI'][pos]} 
              p={p} 
              team={teamLeft} 
              hasBall={servingTeamId === leftId && pos === 0}
              style={getCoords('left', pos)}
            />
          );
        })}

        {/* Joueurs Droite */}
        {[0, 1, 2, 3, 4, 5].map(pos => {
          const p = getP(teamRight, pos);
          const key = p ? `p-${p.id}` : `right-pos-${pos}`;
          return (
            <Pos 
              key={key}
              label={['I','II','III','IV','V','VI'][pos]} 
              p={p} 
              team={teamRight} 
              hasBall={servingTeamId === rightId && pos === 0}
              style={getCoords('right', pos)}
            />
          );
        })}

        {/* Labels Equipes */}
        <div className="absolute top-2 left-2 font-black text-white/20 text-xs uppercase pointer-events-none">{teamLeft.name}</div>
        <div className="absolute top-2 right-2 font-black text-white/20 text-xs uppercase pointer-events-none text-right">{teamRight.name}</div>
      </div>

      <div className="grid grid-cols-2 bg-slate-900/40 rounded-b-lg mt-1 overflow-hidden min-h-[44px]">
        <div className="p-1.5 border-r border-slate-800 flex items-center justify-center">
          <SanctionsDisplay team={teamLeft} teamId={leftId} allSanctions={sanctions} />
        </div>
        <div className="p-1.5 flex items-center justify-center">
          <SanctionsDisplay team={teamRight} teamId={rightId} allSanctions={sanctions} />
        </div>
      </div>
    </div>
  );
};

const Pos = ({ label, p, team, hasBall, style }: any) => {
  if (!p) return null;
  const col = p.isLibero ? team.liberoColor : team.playerColor;

  return (
    <div 
      className="absolute -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-[cubic-bezier(0.34,1.56,0.64,1)] z-20 group"
      style={style}
    >
      <div 
        style={{ backgroundColor: col }} 
        className={`w-11 h-11 rounded-xl flex items-center justify-center text-white shadow-xl shadow-black/50 relative border-[2px] border-white/20 transition-transform ${p.status !== 'ACTIVE' ? 'opacity-30 grayscale' : 'group-hover:scale-110'}`}
      >
        <span className="font-black text-lg leading-none text-white drop-shadow-[0_2px_1px_rgba(0,0,0,1)]">
          {p.number}
        </span>

        {/* Badge Position Romaine - Lié à la position actuelle du joueur */}
        <div className="absolute -top-2 -right-2 bg-slate-950 text-white text-[8px] px-1.5 py-0.5 rounded-md font-black border border-slate-800 shadow-md">
          {label}
        </div>

        {hasBall && (
          <div className="absolute -bottom-3 -left-3 text-lg animate-bounce drop-shadow-[0_8px_8px_rgba(0,0,0,0.6)] z-30 pointer-events-none">
            🏐
          </div>
        )}
      </div>
    </div>
  );
};

const SanctionsDisplay: React.FC<{ team: Team; teamId: 'A'|'B'; allSanctions: PlayerSanction[] }> = ({ team, teamId, allSanctions }) => {
  const teamSanctions = allSanctions.filter(s => {
    return (team.players.some(p => p.id === s.playerId) || s.playerId === 'team' || s.playerId === 'coach') && s.team === teamId;
  });

  if (teamSanctions.length === 0) {
    return <span className="text-[7px] font-black text-slate-700 uppercase tracking-widest">Aucune Sanction</span>;
  }

  return (
    <div className="flex flex-wrap gap-2 items-center">
      {teamSanctions.map((s, idx) => {
        const player = team.players.find(p => p.id === s.playerId);
        const number = player ? `#${player.number}` : (s.playerId === 'team' ? 'Banc' : 'Coach');
        return (
          <div key={idx} className="flex items-center gap-1 bg-slate-950/60 px-1.5 py-0.5 rounded border border-slate-800">
            <SanctionIcon type={s.type} />
            <span className="text-[9px] font-black text-white">{number}</span>
          </div>
        );
      })}
    </div>
  );
};

const SanctionIcon: React.FC<{ type: SanctionType }> = ({ type }) => {
  switch (type) {
    case SanctionType.WARNING:
    case SanctionType.DELAY_WARNING:
      return <div className="w-1.5 h-2.5 bg-yellow-400 rounded-sm"></div>;
    case SanctionType.PENALTY:
    case SanctionType.DELAY_PENALTY:
      return <div className="w-1.5 h-2.5 bg-rose-600 rounded-sm"></div>;
    case SanctionType.EXPULSION:
      return <div className="flex gap-px"><div className="w-1.5 h-2.5 bg-yellow-400 rounded-l-sm"></div><div className="w-1.5 h-2.5 bg-rose-600 rounded-r-sm"></div></div>;
    case SanctionType.DISQUALIFICATION:
       return <div className="flex gap-1"><div className="w-1.5 h-2.5 bg-yellow-400 rounded-sm"></div><div className="w-1.5 h-2.5 bg-rose-600 rounded-sm"></div></div>;
    default: return null;
  }
};

