          {team.players.map((p, index) => {
            // DÉTECTION DE DOUBLONS
            const isDuplicate = team.players.some((other, i) => i !== index && other.number === p.number && p.number !== 0);

            return (
            <div key={p.id} className={`bg-slate-900 border rounded-xl p-2 flex flex-wrap sm:flex-nowrap items-center gap-2 shadow-sm transition-all ${isDuplicate ? 'border-rose-500/50 bg-rose-950/10' : 'border-slate-800 hover:border-slate-700'}`}>

              {/* Numéro avec détection doublon et clavier numérique */}
              <div className="w-12 shrink-0 relative">
                 <input 
                  type="number" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  value={p.number} 
                  onChange={e => onUpdatePlayer(teamId, index, 'number', parseInt(e.target.value) || 0)} 
                  className={`w-full h-10 bg-slate-950 text-center rounded-lg font-black text-sm outline-none transition-all
                    ${isDuplicate 
                        ? 'border-2 border-rose-500 text-rose-500 shadow-[0_0_10px_rgba(225,29,72,0.3)]' 
                        : 'border border-slate-700 text-white focus:border-indigo-500'}
                  `} 
                  placeholder="#" 
                />
                {isDuplicate && (
                    <div className="absolute -bottom-2.5 left-0 right-0 text-[6px] text-center font-bold text-white bg-rose-500 rounded px-1 animate-pulse z-10">
                        EXISTE !
                    </div>
                )}
              </div>

              {/* Infos Joueur (Nom & Licence) */}
              <div className="flex-1 min-w-[140px] flex flex-col gap-1">
                <input 
                  type="text" 
                  placeholder="Nom du joueur" 
                  value={p.name} 
                  onChange={e => onUpdatePlayer(teamId, index, 'name', e.target.value)} 
                  className="w-full bg-transparent rounded px-1 py-0.5 font-bold text-slate-200 text-xs outline-none border-b border-transparent focus:border-slate-700 placeholder:text-slate-600" 
                />
                <input 
                  type="text" 
                  placeholder="N° Licence" 
                  value={p.licenseNumber} 
                  onChange={e => onUpdatePlayer(teamId, index, 'licenseNumber', e.target.value)} 
                  className="w-full bg-transparent rounded px-1 py-0.5 font-mono text-slate-400 text-[10px] outline-none border-b border-transparent focus:border-slate-700 placeholder:text-slate-700" 
                />
              </div>

              {/* Contrôles Rôles */}
              <div className="flex items-center gap-1 shrink-0 bg-slate-950/50 p-1.5 rounded-lg border border-slate-800 ml-auto sm:ml-0">
                {/* CHECKBOX CAPITAINE */}
                <label className={`flex flex-col items-center justify-center cursor-pointer group px-1 ${p.isLibero ? 'opacity-30 cursor-not-allowed' : ''}`}>
                  <input 
                    type="checkbox"
                    checked={p.isCaptain}
                    disabled={p.isLibero}
                    onChange={(e) => {
                      if (e.target.checked) {
                        team.players.forEach((_, i) => onUpdatePlayer(teamId, i, 'isCaptain', false));
                        if (p.isLibero) onUpdatePlayer(teamId, index, 'isLibero', false);
                        onUpdatePlayer(teamId, index, 'isCaptain', true);
                      } else {
                        onUpdatePlayer(teamId, index, 'isCaptain', false);
                      }
                    }}
                    className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-indigo-600 accent-indigo-600 focus:ring-indigo-500 cursor-pointer disabled:cursor-not-allowed"
                  />
                  <span className={`text-[6px] font-black uppercase mt-0.5 ${p.isCaptain ? 'text-indigo-400' : 'text-slate-600 group-hover:text-slate-400'}`}>CAP</span>
                </label>

                <div className="w-px h-6 bg-slate-800 mx-1"></div>

                {/* CHECKBOX LIBERO */}
                <label className={`flex flex-col items-center justify-center cursor-pointer group px-1 ${p.isCaptain ? 'opacity-30 cursor-not-allowed' : ''}`}>
                  <input 
                    type="checkbox"
                    checked={p.isLibero}
                    disabled={p.isCaptain}
                    onChange={(e) => {
                       if (e.target.checked) {
                          if (liberosCount >= 2) {
                             alert("Maximum 2 Libéros autorisés.");
                             return;
                          }
                          if (p.isCaptain) onUpdatePlayer(teamId, index, 'isCaptain', false);
                          onUpdatePlayer(teamId, index, 'isLibero', true);
                       } else {
                          onUpdatePlayer(teamId, index, 'isLibero', false);
                       }
                    }}
                    className="w-4 h-4 rounded border-slate-600 bg-slate-800 text-amber-500 accent-amber-500 focus:ring-amber-500 cursor-pointer disabled:cursor-not-allowed"
                  />
                  <span className={`text-[6px] font-black uppercase mt-0.5 ${p.isLibero ? 'text-amber-500' : 'text-slate-600 group-hover:text-slate-400'}`}>LIB</span>
                </label>
              </div>

              <button 
                type="button"
                onClick={() => setPlayerToDeleteIndex(index)} 
                className="w-8 h-8 rounded-lg bg-rose-950/20 text-rose-500 border border-rose-900/20 flex items-center justify-center hover:bg-rose-500 hover:text-white transition-all shrink-0"
                title="Supprimer"
              >
                ×
              </button>
            </div>
          )}}
        </div>

        <div className="flex gap-2">
            <button 
                onClick={onAddPlayer} 
                disabled={!canAddPlayer}
                className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 border-dashed ${canAddPlayer ? 'bg-indigo-500/5 border-indigo-500/20 text-indigo-400 hover:bg-indigo-500/10' : 'bg-slate-900 border-slate-800 text-slate-700 cursor-not-allowed'}`}
            >
                {canAddPlayer ? '+ Ajouter un joueur' : 'Effectif maximum atteint (14)'}
            </button>
        </div>

        {/* MODALE DE CONFIRMATION DE SUPPRESSION DE JOUEUR */}
        {playerToDeleteIndex !== null && (
          <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-sm z-[700] flex items-center justify-center p-4" onClick={() => setPlayerToDeleteIndex(null)}>
            <div className="bg-slate-900 rounded-3xl border border-slate-800 p-6 w-full max-w-sm shadow-2xl animate-in zoom-in duration-200" onClick={e => e.stopPropagation()}>
               <div className="text-center space-y-4">
                  <div className="w-12 h-12 rounded-full bg-rose-500/20 text-rose-500 flex items-center justify-center text-2xl mx-auto">🗑️</div>
                  <h3 className="text-lg font-black text-white uppercase italic">Supprimer le joueur ?</h3>
                  <div className="text-sm text-slate-300 font-bold">
                     #{team.players[playerToDeleteIndex].number} {team.players[playerToDeleteIndex].name}
                  </div>
                  <p className="text-xs text-slate-400 font-medium">Voulez-vous vraiment retirer ce joueur de l'effectif ?</p>

                  <div className="grid grid-cols-2 gap-3 pt-4">
                     <button onClick={() => setPlayerToDeleteIndex(null)} className="py-3 rounded-xl bg-slate-800 text-slate-400 font-black text-xs uppercase hover:bg-slate-700 transition-all">Annuler</button>
                     <button onClick={() => { onRemovePlayer(playerToDeleteIndex); setPlayerToDeleteIndex(null); }} className="py-3 rounded-xl bg-rose-600 text-white font-black text-xs uppercase hover:bg-rose-500 transition-all shadow-lg shadow-rose-600/20">Supprimer</button>
                  </div>
               </div>
            </div>
         </div>
        )}
      </div>
    </div>
  );
};

export const MatchSetup: React.FC<Props> = ({ onStart, initialData, onGenerateDemo }) => {
  const [step, setStep] = useState<number>(1);
  const [formData, setFormData] = useState<Partial<MatchState>>({ ...initialData, servingTeam: 'A' });

  const handleFormChange = (field: keyof MatchState, value: any) => setFormData(prev => ({...prev, [field]: value }));
  const updateTeamInfo = (teamId: 'A' | 'B', field: keyof Team, value: any) => setFormData(p => ({...p, [teamId === 'A' ? 'teamA' : 'teamB']: { ...p[teamId === 'A' ? 'teamA' : 'teamB']!, [field]: value }}));

  const updatePlayer = (teamId: 'A' | 'B', index: number, field: keyof Player, value: any) => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    const players = [...team.players];
    players[index] = { ...players[index], [field]: value };
    setFormData(p => ({...p, [tk]: { ...team, players }}));
  };

  const addPlayer = (teamId: 'A' | 'B') => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    if (team.players.length >= 14) return;
    setFormData(p => ({...p, [tk]: { ...team, players: [...team.players, { id: Date.now().toString(), number: team.players.length + 1, name: '', licenseNumber: '', isLibero: false, isCaptain: false, status: 'ACTIVE' }]}}));
  };

  const removePlayer = (teamId: 'A' | 'B', index: number) => {
    const tk = teamId === 'A' ? 'teamA' : 'teamB';
    const team = formData[tk]!;
    const players = team.players.filter((_, i) => i !== index);
    setFormData(p => ({...p, [tk]: { ...team, players }}));
  };

  const isStep1Valid = !!(formData.league && formData.city && formData.category && formData.date && formData.scheduledTime && formData.matchId);
  const isStep2Valid = true; 
  const isStep3Valid = (formData.teamA?.players.length || 0) >= 6 && !!formData.teamA?.name && formData.teamA?.players.filter(p => p.isCaptain).length === 1;
  const isStep4Valid = (formData.teamB?.players.length || 0) >= 6 && !!formData.teamB?.name && formData.teamB?.players.filter(p => p.isCaptain).length === 1;

  const handleStepClick = (targetStep: number) => {
      // Allow moving back freely
      if (targetStep < step) {
          setStep(targetStep as any);
          return;
      }

      // Validation check for moving forward
      if (step === 1 && !isStep1Valid) return;
      if (step === 2 && !isStep2Valid) return;
      if (step === 3 && !isStep3Valid) return;
      if (step === 4 && !isStep4Valid) return;

      setStep(targetStep as any);
  }

  return (
    <div className={`mx-auto p-4 space-y-6 ${step === 5 ? 'max-w-6xl' : 'max-w-xl'}`}>
      <ProgressBar step={step} onStepClick={handleStepClick} />

      {step === 1 && (
        <div className="space-y-4 animate-in fade-in slide-in-from-right duration-300">
          <div className="bg-slate-900/80 rounded-[2.5rem] p-8 border border-slate-800 shadow-2xl space-y-6">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-black uppercase text-white tracking-tighter">1. Localisation & Type</h2>
              {onGenerateDemo && (
                <button 
                  onClick={onGenerateDemo}
                  className="text-[9px] font-black bg-indigo-600/20 text-indigo-400 px-3 py-1.5 rounded-lg border border-indigo-500/20 hover:bg-indigo-600 hover:text-white transition-all"
                >
                  Générer Démo 3:2
                </button>
              )}
            </div>
            <div className="space-y-4">
              <div className="bg-indigo-600/10 p-5 rounded-3xl border border-indigo-500/30 mb-4 ring-2 ring-indigo-500/10">
                <InputField 
                    label="Numéro Officiel du Match" 
                    value={formData.matchId} 
                    onChange={v => handleFormChange('matchId', v)} 
                    placeholder="Ex: 101"
                    highlight 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <InputField label="Compétition" value={formData.league} onChange={v => handleFormChange('league', v)} placeholder="Championnat..." />
                <InputField label="Ville" value={formData.city} onChange={v => handleFormChange('city', v)} placeholder="FES" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <InputField label="Salle / Hall" value={formData.hall} onChange={v => handleFormChange('hall', v)} placeholder="Gymnase..." />
                <InputField label="Catégorie" value={formData.category} onChange={v => handleFormChange('category', v)} placeholder="Sénior, Junior..." />
              </div>

              <div className="grid grid-cols-2 gap-4 pt-2 border-t border-slate-800">
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-500 uppercase px-1 tracking-wider">Date de rencontre</label>
                  <input 
                    type="date"
                    value={formData.date} 
                    onChange={e => handleFormChange('date', e.target.value)} 
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 text-xs font-bold text-white uppercase outline-none focus:border-indigo-500 transition-colors" 
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-500 uppercase px-1 tracking-wider">Heure Prévue</label>
                  <input 
                    type="time"
                    value={formData.scheduledTime} 
                    onChange={e => handleFormChange('scheduledTime', e.target.value)} 
                    className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 text-xs font-bold text-white uppercase outline-none focus:border-indigo-500 transition-colors" 
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-slate-500 uppercase px-1">Genre</label>
                <div className="flex gap-2">
                  <button onClick={() => handleFormChange('gender', 'M')} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 ${formData.gender === 'M' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-slate-900 border-slate-800 text-slate-600'}`}>Masculin</button>
                  <button onClick={() => handleFormChange('gender', 'F')} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all border-2 ${formData.gender === 'F' ? 'bg-rose-600 border-rose-400 text-white' : 'bg-slate-900 border-slate-800 text-slate-600'}`}>Féminin</button>
                </div>
              </div>
            </div>
          </div>
          <StepActions onNext={() => setStep(2)} nextDisabled={!isStep1Valid} />
        </div>
      )}

      {step === 2 && (
        <div className="space-y-4 animate-in fade-in slide-in-from-right duration-300">
          <div className="bg-slate-900/80 rounded-[2.5rem] p-8 border border-slate-800 shadow-2xl space-y-6">
            <h2 className="text-xl font-black uppercase text-white tracking-tighter">2. Corps Arbitral (Facultatif)</h2>
            <div className="space-y-4">
              <InputField label="1er Arbitre" value={formData.referee1} onChange={v => handleFormChange('referee1', v)} placeholder="Nom Prénom" />
              <InputField label="2e Arbitre" value={formData.referee2} onChange={v => handleFormChange('referee2', v)} placeholder="Nom Prénom" />
              <InputField label="Marqueur" value={formData.scorer} onChange={v => handleFormChange('scorer', v)} placeholder="Nom Prénom" />

              <div className="pt-4 border-t border-slate-800 space-y-3">
                <label className="text-[9px] font-black text-slate-500 uppercase px-1">Juges de ligne (Optionnel)</label>
                <div className="grid grid-cols-2 gap-3">
                  <input value={formData.lineJudge1} onChange={e => handleFormChange('lineJudge1', e.target.value)} placeholder="Juge 1" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge2} onChange={e => handleFormChange('lineJudge2', e.target.value)} placeholder="Juge 2" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge3} onChange={e => handleFormChange('lineJudge3', e.target.value)} placeholder="Juge 3" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                  <input value={formData.lineJudge4} onChange={e => handleFormChange('lineJudge4', e.target.value)} placeholder="Juge 4" className="bg-slate-950 border border-slate-800 rounded-xl p-3 text-[10px] font-bold text-white outline-none focus:border-indigo-500" />
                </div>
              </div>
            </div>
          </div>
          <StepActions onBack={() => setStep(1)} onNext={() => setStep(3)} nextDisabled={!isStep2Valid} />
        </div>
      )}

      {step === 3 && (
        <div className="space-y-6">
          <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">3. Données Équipe A</h2>
          <TeamConfig 
            teamId="A" 
            team={formData.teamA!} 
            onUpdatePlayer={updatePlayer} 
            onUpdateTeam={updateTeamInfo} 
            onAddPlayer={() => addPlayer('A')} 
            onRemovePlayer={(idx) => removePlayer('A', idx)}
          />
          <StepActions onBack={() => setStep(2)} onNext={() => setStep(4)} nextDisabled={!isStep3Valid} />
        </div>
      )}

      {step === 4 && (
        <div className="space-y-6">
          <h2 className="text-xl font-black uppercase text-white tracking-tighter text-center">4. Données Équipe B</h2>
          <TeamConfig 
            teamId="B" 
            team={formData.teamB!} 
            onUpdatePlayer={updatePlayer} 
            onUpdateTeam={updateTeamInfo} 
            onAddPlayer={() => addPlayer('B')} 
            onRemovePlayer={(idx) => removePlayer('B', idx)} 
          />
          <StepActions onBack={() => setStep(3)} onNext={() => setStep(5)} nextDisabled={!isStep4Valid} />
        </div>
      )}

      {step === 5 && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom duration-500">

           {/* Section TOSS */}
           <div className="bg-gradient-to-br from-indigo-900/40 to-slate-900/40 p-4 rounded-3xl border border-indigo-500/20 text-center space-y-3 max-w-lg mx-auto">
             <h3 className="text-xs font-black text-white uppercase tracking-widest">Qui sert en premier ?</h3>
             <div className="flex gap-4">
                <button 
                  onClick={() => handleFormChange('servingTeam', 'B')}
                  className={`flex-1 py-3 rounded-2xl flex flex-col items-center justify-center border-2 transition-all gap-1 ${formData.servingTeam === 'B' ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl shadow-indigo-600/20 scale-105' : 'bg-slate-900 border-slate-800 text-slate-500 grayscale opacity-60'}`}
                >
                  <span className="text-xl">🏐</span>
                  <span className="font-black text-[10px] uppercase truncate px-2 max-w-full">{formData.teamB?.name || 'Équipe B'}</span>
                </button>
                <button 
                  onClick={() => handleFormChange('servingTeam', 'A')}
                  className={`flex-1 py-3 rounded-2xl flex flex-col items-center justify-center border-2 transition-all gap-1 ${formData.servingTeam === 'A' ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl shadow-indigo-600/20 scale-105' : 'bg-slate-900 border-slate-800 text-slate-500 grayscale opacity-60'}`}
                >
                  <span className="text-xl">🏐</span>
                  <span className="font-black text-[10px] uppercase truncate px-2 max-w-full">{formData.teamA?.name || 'Équipe A'}</span>
                </button>
             </div>
           </div>

           <div className="bg-slate-900/90 rounded-[2.5rem] p-4 lg:p-6 shadow-2xl space-y-6 border border-slate-800">
             <h2 className="text-lg font-black uppercase text-white tracking-tighter text-center">Formations de Départ</h2>

             {/* Disposition Compacte Côte à Côte : B à gauche, A à droite */}
             <div className="flex flex-col md:flex-row gap-4">
                 <div className="flex-1 min-w-0">
                     <FormationEntry team={formData.teamB!} tempF={formData.teamB!.formation} setTempF={f => updateTeamInfo('B', 'formation', f)} />
                 </div>
                 <div className="flex-1 min-w-0 border-t border-slate-800 md:border-t-0 pt-4 md:pt-0 md:pl-4 md:border-l md:border-slate-800">
                     <FormationEntry team={formData.teamA!} tempF={formData.teamA!.formation} setTempF={f => updateTeamInfo('A', 'formation', f)} />
                 </div>
             </div>
           </div>

           <div className="flex gap-4 max-w-xl mx-auto">
             <button onClick={() => setStep(4)} className="flex-1 py-5 bg-slate-900 rounded-3xl font-black uppercase text-xs text-slate-500 border border-slate-800 hover:bg-slate-800 transition-all">← Précédent</button>
             <button 
               onClick={() => onStart(formData)} 
               disabled={formData.teamA!.formation.includes(-1) || formData.teamB!.formation.includes(-1)}
               className="flex-[2] bg-emerald-600 py-5 rounded-3xl font-black uppercase text-xs text-white shadow-xl shadow-emerald-600/20 disabled:opacity-30 border-b-4 border-emerald-900 active:border-b-0 transition-all"
             >
               Démarrer le Match 🏐
             </button>
           </div>
        </div>
      )}
    </div>
  );
};

const InputField = ({ label, value, onChange, placeholder, highlight }: any) => (
  <div className="space-y-1.5 w-full">
    <label className={`text-[9px] font-black uppercase px-1 tracking-wider ${highlight ? 'text-indigo-400' : 'text-slate-500'}`}>{label}</label>
    <input 
      value={value} 
      onChange={e => onChange(e.target.value)} 
      placeholder={placeholder} 
      className={`w-full bg-slate-950 border rounded-2xl px-4 py-3 font-bold text-white uppercase outline-none transition-colors ${highlight ? 'border-indigo-500/50 text-base focus:border-indigo-400' : 'border-slate-800 text-xs focus:border-indigo-500'}`} 
    />
  </div>
);

const StepActions = ({ onBack, onNext, nextDisabled }: any) => (
  <div className="flex gap-4">
    {onBack && (
      <button onClick={onBack} className="flex-1 py-5 bg-slate-900 rounded-3xl font-black uppercase text-xs text-slate-500 border border-slate-800 hover:bg-slate-800 transition-all">
        Précédent
      </button>
    )}
    <button 
      onClick={onNext} 
      disabled={nextDisabled}
      className={`flex-[2] py-5 rounded-3xl font-black uppercase text-xs transition-all border-b-4 ${nextDisabled ? 'bg-slate-800 border-slate-900 text-slate-600 cursor-not-allowed opacity-50' : 'bg-indigo-600 border-indigo-900 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-500 active:border-b-0 active:translate-y-1'}`}
    >
      Continuer →
    </button>
  </div>
);

const FormationEntry = ({ team, tempF, setTempF }: any) => {
  const players = team.players.filter((p: any) => p.status === 'ACTIVE' && !p.isLibero);

  const handlePlayerToggle = (idx: number) => {
    // Si le joueur est déjà sur le terrain, on le retire
    const currentPos = tempF.indexOf(idx);
    if (currentPos !== -1) {
      const newF = [...tempF];
      newF[currentPos] = -1;
      setTempF(newF);
      return;
    }

    // Sinon on l'ajoute à la première place libre
    const firstEmpty = tempF.indexOf(-1);
    if (firstEmpty !== -1) {
      const newF = [...tempF];
      newF[firstEmpty] = idx;
      setTempF(newF);
    }
  };

  const removeFromPos = (posIndex: number) => {
      const newF = [...tempF];
      newF[posIndex] = -1;
      setTempF(newF);
  };

  return (
    <div className="space-y-4">
      {/* En-tête Équipe Compact */}
      <div className="flex items-center gap-2 bg-slate-950/50 p-2 rounded-xl border border-slate-800">
        <div className="w-5 h-5 rounded-full shadow-lg border border-white/10 shrink-0" style={{ backgroundColor: team.color }}></div>
        <span className="font-black text-xs text-white uppercase tracking-tighter truncate">{team.name}</span>
        <button onClick={() => setTempF([-1,-1,-1,-1,-1,-1])} className="ml-auto text-[8px] font-bold text-rose-500 hover:text-rose-400 uppercase bg-rose-500/10 px-2 py-1 rounded">Reset</button>
      </div>

      {/* Grille de Positionnement Compacte */}
      <div className="grid grid-cols-2 gap-2">
        {tempF.map((pIdx: number, i: number) => {
            const p = pIdx !== -1 ? team.players[pIdx] : null;
            return (
                <div key={i} className={`relative h-14 rounded-lg border transition-all flex items-center px-2 gap-2 group ${p ? 'bg-white border-white' : 'bg-slate-900 border-slate-800'}`}>
                    <div className="w-6 h-6 rounded bg-slate-200 text-slate-600 flex items-center justify-center text-[8px] font-black">{['I','II','III','IV','V','VI'][i]}</div>
                    {p ? (
                        <>
                            <span className={`text-xl font-black leading-none ${p.isLibero ? 'text-amber-500' : 'text-slate-900'}`}>{p.number}</span>
                             {p.isLibero && <span className="text-[6px] font-black uppercase text-amber-500 ml-1">L</span>}
                            <button 
                            onClick={() => removeFromPos(i)}
                            className="absolute top-1 right-1 w-4 h-4 bg-rose-500 text-white rounded-full flex items-center justify-center text-[9px] opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                            ×
                            </button>
                        </>
                    ) : (
                        <span className="text-[8px] font-bold uppercase text-slate-600 ml-1">Vide</span>
                    )}
                </div>
            )
        })}
      </div>

      {/* Liste des Joueurs Compacte */}
      <div className="bg-slate-950/30 rounded-2xl p-3 border border-slate-800/50">
        <div className="flex flex-wrap gap-1.5 justify-center">
          {players.map((p: any) => {
            const idx = team.players.indexOf(p);
            const isSelected = tempF.includes(idx);

            return (
              <button 
                key={p.id} 
                disabled={isSelected} 
                onClick={() => handlePlayerToggle(idx)} 
                className={`w-9 h-9 flex items-center justify-center rounded-lg border transition-all text-sm font-black
                    ${isSelected 
                        ? 'bg-slate-900 border-slate-800 text-slate-600 cursor-not-allowed' 
                        : p.isLibero 
                            ? 'bg-amber-100 border-amber-200 text-amber-700 hover:border-amber-500 active:scale-95'
                            : 'bg-white border-slate-200 text-slate-900 hover:border-indigo-500 active:scale-95'
                    }
                `}
              >
                {p.number}
              </button>
            )
          })}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { MatchState, SanctionType, Team, Player, MatchSet, MatchEvent, Substitution, PlayerSanction, MatchSetPoint } from '../types';
import { CourtView } from './CourtView';
import { SanctionModal } from './SanctionModal';
import { SubstitutionModal } from './SubstitutionModal';

interface Props {
  match: MatchState;
  setMatch: React.Dispatch<React.SetStateAction<MatchState>>;
  onEnd: () => void;
  onSpectator: () => void;
}

const useLongPress = (onLongPress: () => void, onClick: (e: React.MouseEvent | React.TouchEvent) => void, { delay = 500 } = {}) => {
    const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const isLongPress = useRef(false);

    const start = useCallback(() => {
        isLongPress.current = false;
        timerRef.current = setTimeout(() => {
            isLongPress.current = true;
            onLongPress();
        }, delay);
    }, [onLongPress, delay]);

    const stop = useCallback((e: React.MouseEvent | React.TouchEvent) => {
        if (timerRef.current) clearTimeout(timerRef.current);
        if (!isLongPress.current) onClick(e);
    }, [onClick]);

    return {
        onMouseDown: start,
        onTouchStart: start,
        onMouseUp: stop,
        onTouchEnd: stop,
        onMouseLeave: () => { if(timerRef.current) clearTimeout(timerRef.current) },
    };
};

const formatTime = (seconds: number) => {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

const getNowHHMM = () => {
  const now = new Date();
  const hours = now.getHours().toString().padStart(2, '0');
  const minutes = now.getMinutes().toString().padStart(2, '0');
  return `${hours}:${minutes}`;
};

const addMinutesToTime = (timeStr: string, minutesToAdd: number): string => {
    if (!timeStr) return getNowHHMM();
    try {
        const [h, m] = timeStr.split(':').map(Number);
        const totalMinutes = h * 60 + m + minutesToAdd;
        const newH = Math.floor(totalMinutes / 60) % 24;
        const newM = totalMinutes % 60;
        return `${newH.toString().padStart(2, '0')}:${newH.toString().padStart(2, '0')}`;
    } catch (e) {
        return getNowHHMM();
    }
};

const calculateDurationInMinutes = (startTime: string, endTime: string): number => {
    if (!startTime || !endTime) return 0;
    try {
        const [startH, startM] = startTime.split(':').map(Number);
        const [endH, endM] = endTime.split(':').map(Number);

        const startMinutes = startH * 60 + startM;
        const endMinutes = endH * 60 + endM;

        let diff = endMinutes - startMinutes;
        if (diff < 0) diff += 24 * 60;

        return diff > 0 ? diff : 1;
    } catch (e) {
        return 0;
    }
};

const getContrastYIQ = (hexcolor: string) => {
    if (!hexcolor) return '#ffffff';
    const hex = hexcolor.replace('#', '');
    const r = parseInt(hex.substr(0, 2), 16);
    const g = parseInt(hex.substr(2, 2), 16);
    const b = parseInt(hex.substr(4, 2), 16);
    const yiq = ((r * 299) + (g * 587) + (b * 114)) / 1000;
    return yiq >= 128 ? '#000000' : '#ffffff';
};

export const MatchLive: React.FC<Props> = ({ match, setMatch, onEnd, onSpectator }) => {
  const [showSanction, setShowSanction] = useState<{ team: 'A' | 'B' | null }>({ team: null });
  const [showSubModal, setShowSubModal] = useState<{team: 'A' | 'B', forcedPlayerOutId?: string | null} | null>(null);
  const [activeTab, setActiveTab] = useState('positions');
  const [timeoutTimer, setTimeoutTimer] = useState<number | null>(null);
  const [breakTimer, setBreakTimer] = useState<number | null>(null);
  const [isEnteringFormation, setIsEnteringFormation] = useState(false);
  const [tempFormationA, setTempFormationA] = useState<number[]>([-1, -1, -1, -1, -1, -1]);
  const [tempFormationB, setTempFormationB] = useState<number[]>([-1, -1, -1, -1, -1, -1]);
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [pendingStartFormations, setPendingStartFormations] = useState<{a: number[], b: number[]} | null>(null);

  // State pour le choix du serveur au Tie-Break
  const [tieBreakServer, setTieBreakServer] = useState<'A' | 'B' | null>(null);

  const lastClickTimeRef = useRef<number>(0);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const breakRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const leftTeam = match.isTeamAOnLeft ? match.teamA : match.teamB;
  const rightTeam = match.isTeamAOnLeft ? match.teamB : match.teamA;
  const leftId = match.isTeamAOnLeft ? 'A' : 'B';
  const rightId = match.isTeamAOnLeft ? 'B' : 'A';

  const saveStateForUndo = (currentState: MatchState) => {
    setMatchHistory(prev => [...prev.slice(-5), JSON.parse(JSON.stringify(currentState))]);
  };

  const handleUndo = () => {
    if (matchHistory.length === 0) return;
    const previousState = matchHistory[matchHistory.length - 1];
    setMatch(previousState);
    setMatchHistory(prev => prev.slice(0, -1));
    setTimeoutTimer(null);
  };

  const cancelLastActionForTeam = (teamId: 'A' | 'B', actionType: 'TIMEOUT' | 'SANCTION' | 'SUB') => {
    const lastEvent = match.history.length > 0 ? match.history[match.history.length - 1] : null;
    if (lastEvent && lastEvent.type === actionType && lastEvent.team === teamId) {
      handleUndo();
    }
  };

  useEffect(() => {
    if (timeoutTimer !== null) {
      if (timeoutTimer > 0) {
        timerRef.current = setTimeout(() => setTimeoutTimer(t => (t ? t - 1 : 0)), 1000);
      } else { setTimeoutTimer(null); }
    }
    return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [timeoutTimer]);

  useEffect(() => {
    if (breakTimer !== null) {
        if (breakTimer > 0) {
            breakRef.current = setTimeout(() => setBreakTimer(b => (b ? b - 1 : 0)), 1000);
        } else {
            setBreakTimer(null);
            if (pendingStartFormations) {
                commitSetStart(pendingStartFormations.a, pendingStartFormations.b);
                setPendingStartFormations(null);
            }
        }
    }
    return () => { if (breakRef.current) clearTimeout(breakRef.current); };
  }, [breakTimer, pendingStartFormations]);

  const checkSetEnd = (state: MatchState) => {
    const isTieBreak = state.currentSetIndex === 4;
    const limit = isTieBreak ? 15 : 25;
    const { scoreA, scoreB } = { scoreA: state.teamA.score, scoreB: state.teamB.score };

    if ((scoreA >= limit || scoreB >= limit) && Math.abs(scoreA - scoreB) >= 2) {
      const now = getNowHHMM();
      const duration = calculateDurationInMinutes(state.currentSetStartTime, now);

      state.sets.push({ 
        scoreA, scoreB, startTime: state.currentSetStartTime, endTime: now, duration: duration,
        firstServingTeam: state.currentSetFirstServingTeam, 
        startingFormationA: [...state.currentSetStartingFormationA], 
        startingFormationB: [...state.currentSetStartingFormationB],
        endFormationA: [...state.teamA.formation],
        endFormationB: [...state.teamB.formation],
        subsA: [...state.teamA.substitutionHistory], subsB: [...state.teamB.substitutionHistory],
        timeoutsTakenA: state.teamA.timeoutsTaken, timeoutsTakenB: state.teamB.timeoutsTaken,
        points: [...state.currentSetPoints]
      });
      state.currentSetPoints = [];

      if (scoreA > scoreB) state.teamA.setsWon += 1; else state.teamB.setsWon += 1;

      state.teamA.players.forEach(p => { if(p.status === 'EXPELLED') p.status = 'ACTIVE' });
      state.teamB.players.forEach(p => { if(p.status === 'EXPELLED') p.status = 'ACTIVE' });

      if (state.teamA.setsWon === 3 || state.teamB.setsWon === 3) { 
        state.isLive = false; 
        return; 
      }

      state.currentSetIndex += 1;
      state.servingTeam = null;
      state.isTeamAOnLeft = !state.isTeamAOnLeft; 
      state.hasSwitchedInDecisiveSet = false;

      setTempFormationA([-1, -1, -1, -1, -1, -1]);
      setTempFormationB([-1, -1, -1, -1, -1, -1]);
      setPendingStartFormations(null);
      setTieBreakServer(null); // Reset pour le nouveau set (si jamais on passe au 5e)

      setBreakTimer(180);
    }
  };

  const prepareFormationEntry = () => {
    setIsEnteringFormation(true);
  };

  const handleReopenLastSet = () => {
    if (match.currentSetIndex === 0) return;
    if (!window.confirm("Voulez-vous vraiment annuler la fin du dernier set et corriger le score ?")) return;

    const setIndexToReopen = match.currentSetIndex - 1;
    const setMap = match.sets[setIndexToReopen];

    setBreakTimer(null);
    setPendingStartFormations(null);
    setIsEnteringFormation(false);
    setTimeoutTimer(null);

    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.sets = next.sets.slice(0, setIndexToReopen);
        next.currentSetIndex = setIndexToReopen;
        next.teamA.score = setMap.scoreA;
        next.teamB.score = setMap.scoreB;
        if (setMap.scoreA > setMap.scoreB) next.teamA.setsWon--;
        else next.teamB.setsWon--;
        next.currentSetPoints = setMap.points;
        next.currentSetStartTime = setMap.startTime;
        next.currentSetFirstServingTeam = setMap.firstServingTeam;
        next.currentSetStartingFormationA = setMap.startingFormationA;
        next.currentSetStartingFormationB = setMap.startingFormationB;
        next.teamA.formation = setMap.endFormationA || setMap.startingFormationA; 
        next.teamB.formation = setMap.endFormationB || setMap.startingFormationB;
        next.teamA.timeoutsTaken = setMap.timeoutsTakenA;
        next.teamB.timeoutsTaken = setMap.timeoutsTakenB;
        next.teamA.substitutionHistory = setMap.subsA;
        next.teamB.substitutionHistory = setMap.subsB;
        next.teamA.substitutionsCount = setMap.subsA.length;
        next.teamB.substitutionsCount = setMap.subsB.length;
        next.isTeamAOnLeft = !next.isTeamAOnLeft;
        const lastPoint = setMap.points[setMap.points.length - 1];
        if (lastPoint) {
             next.servingTeam = lastPoint.team;
        } else {
             next.servingTeam = setMap.firstServingTeam;
        }
        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex,
            team: 'NONE',
            type: 'SYSTEM',
            description: `Correction: Retour au Set ${next.currentSetIndex + 1}`,
            score: `${next.teamA.score}-${next.teamB.score}`
        });
        return next;
    });
    setActiveTab('positions');
  };

  const handleSkipBreak = () => {
      if (pendingStartFormations) {
          commitSetStart(pendingStartFormations.a, pendingStartFormations.b);
          setPendingStartFormations(null);
      }
      setBreakTimer(null);
  };

  const onFormationSubmit = () => {
    if (tempFormationA.includes(-1) || tempFormationB.includes(-1)) return;

    // Validation pour le Tie-Break
    if (match.currentSetIndex === 4 && !tieBreakServer) {
        alert("Veuillez sélectionner l'équipe qui sert pour le set décisif.");
        return;
    }

    setIsEnteringFormation(false);
    if (breakTimer === null || breakTimer <= 0) {
        commitSetStart(tempFormationA, tempFormationB);
    } else {
        setPendingStartFormations({
            a: [...tempFormationA],
            b: [...tempFormationB]
        });
    }
  };

  const commitSetStart = (formationA: number[], formationB: number[]) => {
    saveStateForUndo(match);
    setBreakTimer(null);
    let calculatedStartTime = getNowHHMM();
    const lastSet = match.sets[match.sets.length - 1];
    if (lastSet && lastSet.endTime) {
        calculatedStartTime = addMinutesToTime(lastSet.endTime, 3);
    }

    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.teamA.score = 0;
        next.teamB.score = 0;
        next.teamA.timeoutsTaken = 0;
        next.teamB.timeoutsTaken = 0;
        next.teamA.substitutionsCount = 0;
        next.teamB.substitutionsCount = 0;
        next.teamA.substitutionHistory = [];
        next.teamB.substitutionHistory = [];

        let nextServer = prev.currentSetFirstServingTeam === 'A' ? 'B' : 'A';
        // Override pour le Tie-Break
        if (prev.currentSetIndex === 4 && tieBreakServer) {
            nextServer = tieBreakServer;
        }

        next.currentSetFirstServingTeam = nextServer;
        next.servingTeam = nextServer;
        next.teamA.formation = [...formationA];
        next.teamB.formation = [...formationB];
        next.currentSetStartingFormationA = [...formationA];
        next.currentSetStartingFormationB = [...formationB];
        next.currentSetStartTime = calculatedStartTime;
        next.history.push({
            time: calculatedStartTime,
            setIndex: next.currentSetIndex,
            team: 'NONE',
            type: 'SET_START',
            description: `Début Set ${next.currentSetIndex + 1}`,
            score: "0-0"
        });
        return next;
    });
  };

  const handleApplySanction = (type: SanctionType, subjectId?: string) => {
    if (!subjectId || !showSanction.team) return;

    if (type === SanctionType.WARNING) {
        const hasExistingWarning = match.playerSanctions.some(s => s.team === showSanction.team && s.type === SanctionType.WARNING);
        if (hasExistingWarning) {
            alert(`L'équipe ${showSanction.team === 'A' ? match.teamA.name : match.teamB.name} a déjà reçu son avertissement (Jaune).`);
            return;
        }
    }

    saveStateForUndo(match);
    const sanctionedTeamId = showSanction.team;
    setShowSanction({ team: null });

    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        const sanctionedTeam = sanctionedTeamId === 'A' ? next.teamA : next.teamB;
        const currentScore = sanctionedTeamId === 'A' ? `${next.teamA.score}:${next.teamB.score}` : `${next.teamB.score}:${next.teamA.score}`;
        const sanction: PlayerSanction = { 
          playerId: subjectId, type: type, setIndex: prev.currentSetIndex, scoreAtSanction: currentScore, team: sanctionedTeamId
        };
        next.playerSanctions.push(sanction);
        const player = sanctionedTeam.players.find((p: Player) => p.id === subjectId);
        if (player) {
            if (type === SanctionType.EXPULSION) player.status = 'EXPELLED';
            if (type === SanctionType.DISQUALIFICATION) player.status = 'DISQUALIFIED';
            if (sanctionedTeam.formation.includes(sanctionedTeam.players.indexOf(player)) && 
               (type === SanctionType.EXPULSION || type === SanctionType.DISQUALIFICATION)) {
                setTimeout(() => setShowSubModal({ team: sanctionedTeamId, forcedPlayerOutId: subjectId }), 100);
            }
        }

        const subjectDesc = player ? `#${player.number} ${player.name}` : 'Personnel';

        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex, team: sanctionedTeamId, type: 'SANCTION',
            description: `${type} pour ${subjectDesc} (${sanctionedTeam.name})`, 
            score: `${next.teamA.score}-${next.teamB.score}`
        });
        if (type === SanctionType.PENALTY || type === SanctionType.DELAY_PENALTY) {
            const otherTeamId = sanctionedTeamId === 'A' ? 'B' : 'A';
            const otherTeam = otherTeamId === 'A' ? next.teamA : next.teamB;
            const servingTeamId = next.servingTeam || next.currentSetFirstServingTeam;
            const servingTeam = servingTeamId === 'A' ? next.teamA : next.teamB;
            const serverIdx = servingTeam.formation[0];
            next.servingTeam = otherTeamId;
            otherTeam.score += 1;
            next.currentSetPoints.push({ 
                team: otherTeamId, 
                scoreA: next.teamA.score, 
                scoreB: next.teamB.score,
                isSideOut: servingTeamId !== otherTeamId,
                servedByTeam: servingTeamId,
                serverPlayerIndex: serverIdx
            });
            next.history.push({
                time: getNowHHMM(),
                setIndex: next.currentSetIndex,
                team: otherTeamId,
                type: 'POINT',
                description: `Point via Pénalité (${otherTeam.name})`,
                score: `${next.teamA.score}-${next.teamB.score}`
            });
            checkSetEnd(next);
        }
        return next;
    });
  };

  const handleApplySubstitution = (teamId: 'A' | 'B', playerOutId: string, playerInId: string) => {
    saveStateForUndo(match);
    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        const team = teamId === 'A' ? next.teamA : next.teamB;
        const outIdx = team.players.findIndex((p: Player) => p.id === playerOutId);
        const inIdx = team.players.findIndex((p: Player) => p.id === playerInId);
        const posInForm = team.formation.indexOf(outIdx);
        if (posInForm === -1 || inIdx === -1) return prev;

        const playerIn = team.players[inIdx];
        const playerOut = team.players[outIdx];

        team.formation[posInForm] = inIdx;
        const isReturn = team.substitutionHistory.some((s: Substitution) => s.playerInId === playerOutId && s.playerOutId === playerInId);
        const scoreString = teamId === 'A' ? `${next.teamA.score}:${next.teamB.score}` : `${next.teamB.score}:${next.teamA.score}`;
        team.substitutionHistory.push({ playerOutId, playerInId, isReturn, scoreAtSub: scoreString });
        team.substitutionsCount += 1;

        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex, team: teamId, type: 'SUB',
            description: `Remp: #${playerIn.number} ${playerIn.name} بدلاً من #${playerOut.number} ${playerOut.name}`,
            score: `${next.teamA.score}-${next.teamB.score}`
        });
        setShowSubModal(null);
        return next;
    });
  };

  const addPoint = (winnerTeamId: 'A' | 'B') => {
    // حماية ضد النقرات المتعددة السريعة (300ms)
    const now = Date.now();
    if (now - lastClickTimeRef.current < 300) return;
    lastClickTimeRef.current = now;

    if (isMatchOver || timeoutTimer !== null || breakTimer !== null) return;

    saveStateForUndo(match);
    setMatch(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      const winningTeam = winnerTeamId === 'A' ? next.teamA : next.teamB;
      const currentServingTeamId = prev.servingTeam;
      const actualServingTeamId = currentServingTeamId || next.currentSetFirstServingTeam;
      const servingTeam = actualServingTeamId === 'A' ? prev.teamA : prev.teamB;
      const serverIdx = servingTeam.formation[0]; 
      const isSideOut = actualServingTeamId !== winnerTeamId;

      if (isSideOut) {
        const f = winningTeam.formation;
        winningTeam.formation = [f[1], f[2], f[3], f[4], f[5], f[0]];
      }

      next.servingTeam = winnerTeamId;
      winningTeam.score += 1;

      next.currentSetPoints.push({ 
          team: winnerTeamId, 
          scoreA: next.teamA.score, 
          scoreB: next.teamB.score,
          isSideOut: isSideOut,
          servedByTeam: actualServingTeamId,
          serverPlayerIndex: serverIdx
      });

      next.history.push({
        time: getNowHHMM(),
        setIndex: next.currentSetIndex,
        team: winnerTeamId,
        type: 'POINT',
        description: `Point ${winningTeam.name}`,
        score: `${next.teamA.score}-${next.teamB.score}`
      });

      if (next.currentSetIndex === 4 && !next.hasSwitchedInDecisiveSet && (next.teamA.score === 8 || next.teamB.score === 8)) {
        next.isTeamAOnLeft = !next.isTeamAOnLeft;
        next.hasSwitchedInDecisiveSet = true;
        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex,
            team: 'NONE',
            type: 'SIDE_SWITCH',
            description: `Changement de camp (Score 8)`,
            score: `${next.teamA.score}-${next.teamB.score}`
        });
      }
      checkSetEnd(next);
      return next;
    });
  };

  const isMatchOver = match.teamA.setsWon === 3 || match.teamB.setsWon === 3;
  const timeoutHandlersLeft = useLongPress(() => cancelLastActionForTeam(leftId, 'TIMEOUT'), () => triggerTimeout(leftId));
  const timeoutHandlersRight = useLongPress(() => cancelLastActionForTeam(rightId, 'TIMEOUT'), () => triggerTimeout(rightId));

  const triggerTimeout = (teamId: 'A' | 'B') => {
    const team = teamId === 'A' ? match.teamA : match.teamB;
    if (team.timeoutsTaken >= 2 || timeoutTimer !== null || breakTimer !== null) return;
    saveStateForUndo(match);
    setMatch(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      const target = teamId === 'A' ? next.teamA : next.teamB;
      target.timeoutsTaken += 1;
       next.history.push({
        time: getNowHHMM(),
        setIndex: next.currentSetIndex, team: teamId, type: 'TIMEOUT',
        description: `TM ${target.name}`, score: `${next.teamA.score}-${next.teamB.score}`
      });
      return next;
    });
    setTimeoutTimer(30);
  };

  const leftTextColor = getContrastYIQ(leftTeam.playerColor);
  const rightTextColor = getContrastYIQ(rightTeam.playerColor);
  const leftSetColor = leftTeam.color;
  const rightSetColor = rightTeam.color;
  const leftSetTextColor = getContrastYIQ(leftSetColor);
  const rightSetTextColor = getContrastYIQ(rightSetColor);

  return (
    <div className="flex flex-col h-[92vh] max-w-md mx-auto p-2 bg-slate-950 border border-slate-900 rounded-[2rem] relative shadow-2xl overflow-hidden text-right">
      {timeoutTimer !== null && (
        <div className="absolute top-0 left-0 right-0 z-[520] bg-indigo-600 p-4 flex flex-col items-center justify-center shadow-2xl animate-in slide-in-from-top duration-300">
           <div className="flex items-center gap-4">
              <span className="text-white text-3xl font-black tabular-nums">{timeoutTimer}s</span>
              <div className="h-8 w-px bg-white/20"></div>
              <div className="text-right">
                <div className="text-white font-black uppercase text-[10px] tracking-widest">Temps Mort</div>
                <div className="text-indigo-200 text-[8px] font-bold uppercase">Reprise automatique dans...</div>
              </div>
