const FormationEntry = ({ team, tempF, setTempF }: any) => {
  const players = team.players.filter((p: any) => p.status === 'ACTIVE' && !p.isLibero);

  const handlePlayerToggle = (idx: number) => {
    // Si le joueur est déjà sur le terrain, on le retire
    const currentPos = tempF.indexOf(idx);
    if (currentPos !== -1) {
      const newF = [...tempF];
      newF[currentPos] = -1;
      setTempF(newF);
      return;
    }

    // Sinon on l'ajoute à la première place libre
    const firstEmpty = tempF.indexOf(-1);
    if (firstEmpty !== -1) {
      const newF = [...tempF];
      newF[firstEmpty] = idx;
      setTempF(newF);
    }
  };

  const removeFromPos = (posIndex: number) => {
      const newF = [...tempF];
      newF[posIndex] = -1;
      setTempF(newF);
  };

  return (
    <div className="space-y-4">
      {/* En-tête Équipe Compact */}
      <div className="flex items-center gap-2 bg-slate-950/50 p-2 rounded-xl border border-slate-800">
        <div className="w-5 h-5 rounded-full shadow-lg border border-white/10 shrink-0" style={{ backgroundColor: team.color }}></div>
        <span className="font-black text-xs text-white uppercase tracking-tighter truncate">{team.name}</span>
        <button onClick={() => setTempF([-1,-1,-1,-1,-1,-1])} className="ml-auto text-[8px] font-bold text-rose-500 hover:text-rose-400 uppercase bg-rose-500/10 px-2 py-1 rounded">Reset</button>
      </div>

      {/* Grille de Positionnement Compacte */}
      <div className="grid grid-cols-2 gap-2">
        {tempF.map((pIdx: number, i: number) => {
            const p = pIdx !== -1 ? team.players[pIdx] : null;
            return (
                <div key={i} className={`relative h-14 rounded-lg border transition-all flex items-center px-2 gap-2 group ${p ? 'bg-white border-white' : 'bg-slate-900 border-slate-800'}`}>
                    <div className="w-6 h-6 rounded bg-slate-200 text-slate-600 flex items-center justify-center text-[8px] font-black">{['I','II','III','IV','V','VI'][i]}</div>
                    {p ? (
                        <>
                            <span className={`text-xl font-black leading-none ${p.isLibero ? 'text-amber-500' : 'text-slate-900'}`}>{p.number}</span>
                             {p.isLibero && <span className="text-[6px] font-black uppercase text-amber-500 ml-1">L</span>}
                            <button 
                            onClick={() => removeFromPos(i)}
                            className="absolute top-1 right-1 w-4 h-4 bg-rose-500 text-white rounded-full flex items-center justify-center text-[9px] opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                            ×
                            </button>
                        </>
                    ) : (
                        <span className="text-[8px] font-bold uppercase text-slate-600 ml-1">Vide</span>
                    )}
                </div>
            )
        })}
      </div>

      {/* Liste des Joueurs Compacte */}
      <div className="bg-slate-950/30 rounded-2xl p-3 border border-slate-800/50">
        <div className="flex flex-wrap gap-1.5 justify-center">
          {players.map((p: any) => {
            const idx = team.players.indexOf(p);
            const isSelected = tempF.includes(idx);

            return (
              <button 
                key={p.id} 
                disabled={isSelected} 
                onClick={() => handlePlayerToggle(idx)} 
                className={`w-9 h-9 flex items-center justify-center rounded-lg border transition-all text-sm font-black
                    ${isSelected 
                        ? 'bg-slate-900 border-slate-800 text-slate-600 cursor-not-allowed' 
                        : p.isLibero 
                            ? 'bg-amber-100 border-amber-200 text-amber-700 hover:border-amber-500 active:scale-95'
                            : 'bg-white border-slate-200 text-slate-900 hover:border-indigo-500 active:scale-95'
                    }
                `}
              >
                {p.number}
              </button>
            )
          })}
        </div>
      </div>
    </div>
  );
}

export enum SanctionType {
  WARNING = 'Avertissement',
  PENALTY = 'Pénalité',
  EXPULSION = 'Expulsion',
  DISQUALIFICATION = 'Disqualification',
  DELAY_WARNING = 'Retard de Jeu (Avert)',
  DELAY_PENALTY = 'Retard de Jeu (Pénalité)'
}

export interface Substitution {
  playerOutId: string;
  playerInId: string;
  isReturn: boolean;
  scoreAtSub?: string; // e.g. "12:10"
}

export interface Player {
  id: string;
  number: number;
  name: string;
  licenseNumber: string; // AJOUTÉ : Numéro de licence
  isLibero: boolean;
  isCaptain: boolean;
  status: 'ACTIVE' | 'EXPELLED' | 'DISQUALIFIED';
}

export interface PlayerSanction {
  playerId: string;
  type: SanctionType;
  setIndex: number;
  scoreAtSanction: string;
  team: 'A' | 'B';
}

export interface Team {
  name: string;
  color: string;
