}

export interface MatchSetPoint {
  team: 'A' | 'B'; // L'équipe qui a MARQUÉ le point
  scoreA: number; // Score après le point
  scoreB: number; // Score après le point
  isSideOut: boolean; // Si vrai, l'équipe au service a perdu le point
  servedByTeam: 'A' | 'B'; // L'équipe qui a servi cet échange
  serverPlayerIndex: number; // L'index (dans players[]) du joueur qui a servi
}

export interface MatchSet {
  scoreA: number;
  scoreB: number;
