const App: React.FC = () => {
  const [view, setView] = useState<'setup' | 'live' | 'summary' | 'archive' | 'spectator' | 'sheet'>('setup');
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [selectedArchivedMatch, setSelectedArchivedMatch] = useState<MatchState | null>(null);
  const [match, setMatch] = useState<MatchState>(createInitialMatchState());
  const [syncing, setSyncing] = useState(false);

  const syncTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!match.matchId) return;

    const channel = supabase
      .channel(`match-realtime-${match.matchId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'vb_match_sets', filter: `vb_match_id=eq.${match.matchId}` },
        async () => {
          if (view === 'spectator') {
            const updated = await fetchFullMatch(match.matchId);
            if (updated) setMatch(prev => ({...updated, isTeamAOnLeft: prev.isTeamAOnLeft}));
          }
        }
      )
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'vb_match_event_logs', filter: `vb_match_id=eq.${match.matchId}` },
        async () => {
          if (view === 'spectator') {
            const updated = await fetchFullMatch(match.matchId);
            if (updated) setMatch(prev => ({...updated, isTeamAOnLeft: prev.isTeamAOnLeft}));
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [match.matchId, view]);

  useEffect(() => {
    if (view === 'live' && match.isLive) {
        if (syncTimeoutRef.current) clearTimeout(syncTimeoutRef.current);
        syncTimeoutRef.current = setTimeout(() => {
            handleSync();
        }, 500);
    }
  }, [
      match.history.length, 
      match.teamA.score, 
      match.teamB.score, 
      match.teamA.timeoutsTaken, 
      match.teamB.timeoutsTaken, 
      match.teamA.substitutionsCount, 
      match.teamB.substitutionsCount,
      match.signatures // Sync signatures too
    ]);

  const handleSync = async () => {
    setSyncing(true);
    await syncMatchToSupabase(match);
    setSyncing(false);
  };

  const handleStartMatch = (setupData: Partial<MatchState>) => {
    if (match.isLive) {
        // CAS: Mise à jour des paramètres pendant le match
        setMatch(prev => ({
            ...prev,
            ...setupData,
            // On s'assure de ne pas écraser les données critiques du match en cours
            teamA: { ...prev.teamA, ...setupData.teamA, score: prev.teamA.score, setsWon: prev.teamA.setsWon, timeoutsTaken: prev.teamA.timeoutsTaken, substitutionsCount: prev.teamA.substitutionsCount, formation: prev.teamA.formation, substitutionHistory: prev.teamA.substitutionHistory },
            teamB: { ...prev.teamB, ...setupData.teamB, score: prev.teamB.score, setsWon: prev.teamB.setsWon, timeoutsTaken: prev.teamB.timeoutsTaken, substitutionsCount: prev.teamB.substitutionsCount, formation: prev.teamB.formation, substitutionHistory: prev.teamB.substitutionHistory },
            sets: prev.sets,
            currentSetIndex: prev.currentSetIndex,
            currentSetStartTime: prev.currentSetStartTime,
            currentSetPoints: prev.currentSetPoints,
            history: prev.history,
            playerSanctions: prev.playerSanctions
        }));
        setView('live');
    } else {
        // CAS: Nouveau match
        const now = getFormattedTime();
        const firstServer = setupData.servingTeam || 'A';

        const newMatch = {
          ...match,
          ...setupData,
          isLive: true,
          startTime: now,
          currentSetStartTime: now,
          currentSetFirstServingTeam: firstServer,
          currentSetStartingFormationA: setupData.teamA?.formation || match.teamA.formation,
          currentSetStartingFormationB: setupData.teamB?.formation || match.teamB.formation,
          history: [{
            time: now,
            setIndex: 0,
            team: 'NONE' as const,
            type: 'SET_START' as const,
            description: `Début Match & Set 1`,
            score: "0-0"
          }]
        };

        setMatch(newMatch);
        setView('live');
        syncMatchToSupabase(newMatch);
    }
  };

  const handleEndMatch = async () => {
    const finalMatch = { ...match, isLive: false };
    setMatch(finalMatch);
    setSyncing(true);
    await syncMatchToSupabase(finalMatch);
    setSyncing(false);

    const history = await fetchMatchHistory();
    setMatchHistory(history);
    setView('summary');
  };

  const handleResumeMatch = () => {
    setMatch(prev => ({ ...prev, isLive: true }));
    setView('live');
  };

  const handleViewArchivedMatch = async (archivedMatch: MatchState) => {
    const full = await fetchFullMatch(archivedMatch.matchId);
    setSelectedArchivedMatch(full || archivedMatch);
    setView('summary');
  };

  const handleDeleteMatch = async (matchId: string) => {
    await supabase.from('vb_matches').delete().eq('id', matchId);
    setMatchHistory(prev => prev.filter(m => m.matchId !== matchId));
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 selection:bg-indigo-500/30">
      {view !== 'spectator' && (
      <header className="bg-slate-900/80 backdrop-blur-md border-b border-slate-800 p-4 sticky top-0 z-50 print:hidden">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center font-black shadow-lg shadow-indigo-500/20">V</div>
            <div className="flex flex-col">
                <h1 className="text-xl font-black tracking-tighter uppercase italic leading-none">VolleyRef <span className="text-indigo-400">Pro</span></h1>
                <div className="flex items-center gap-1.5">
                    <span className={`w-1.5 h-1.5 rounded-full ${syncing ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`}></span>
                    <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">{syncing ? 'Sync Cloud...' : 'Connecté Cloud'}</span>
                </div>
            </div>
          </div>

          <div className="flex gap-2">
            {view === 'setup' && (
                <button 
                onClick={() => setView('archive')}
                className="text-[10px] font-black uppercase text-indigo-400 bg-indigo-500/10 px-4 py-2 rounded-full border border-indigo-500/20 active:scale-95 transition-all flex items-center gap-2 hover:bg-indigo-500/20"
                >
                <span>📂</span>
                <span>Archives ({matchHistory.length})</span>
                </button>
            )}

            {view === 'live' && (
                <>
                <button 
                    onClick={() => setView('sheet')}
                    className="text-[10px] font-black uppercase text-slate-300 bg-slate-800 px-3 py-2 rounded-xl border border-slate-700 hover:text-white transition-all flex items-center gap-2 hover:bg-slate-700"
                >
                    <span>📄</span>
                    <span className="hidden sm:inline">Feuille de Match</span>
                </button>
                <button 
                    onClick={() => setView('setup')}
                    className="text-[10px] font-black uppercase text-slate-300 bg-slate-800 px-3 py-2 rounded-xl border border-slate-700 hover:text-white transition-all flex items-center gap-2 hover:bg-slate-700"
                >
                    <span>⚙️</span>
                    <span className="hidden sm:inline">Paramètres</span>
                </button>
                </>
            )}
          </div>
        </div>
      </header>
      )}

      <main className={view === 'spectator' ? "" : "max-w-4xl mx-auto p-4 pb-24"}>
        {view === 'setup' && <MatchSetup onStart={handleStartMatch} initialData={match} onGenerateDemo={!match.isLive ? () => {} : undefined} />}
        {view === 'live' && <MatchLive match={match} setMatch={setMatch} onEnd={handleEndMatch} onSpectator={() => setView('spectator')} />}
        {view === 'summary' && <MatchSummary match={selectedArchivedMatch || match} setMatch={setMatch} onReset={() => { setSelectedArchivedMatch(null); setView('setup'); }} onResume={handleResumeMatch} />}
        {view === 'spectator' && <MatchSpectator match={match} onExit={() => setView('live')} />}
        {view === 'archive' && (
          <MatchArchive 
            history={matchHistory} 
            onSelect={handleViewArchivedMatch} 
            onBack={() => setView('setup')} 
            onDelete={handleDeleteMatch}
            onClear={() => setMatchHistory([])}
          />
        )}
        {view === 'sheet' && (
            <ScoreSheet 
                match={match} 
                onBack={() => setView('live')} 
                setMatch={setMatch} // Passer setMatch pour les signatures
            />
        )}
      </main>

      {view !== 'spectator' && (
      <footer className="fixed bottom-0 left-0 right-0 p-4 bg-slate-950/50 backdrop-blur-sm pointer-events-none flex justify-center text-[10px] font-bold text-slate-600 uppercase tracking-widest z-0">
        FIVB Realtime Sync • Cloud Database Active
      </footer>
      )}
    </div>
  );
};

export default App;

