  { name: 'Jaune', value: '#eab308' },
];

const ProgressBar: React.FC<{ step: number; onStepClick: (step: number) => void }> = ({ step, onStepClick }) => {
  const labels = ["Match", "Arbitres", "Équipe A", "Équipe B", "Formations"];
  return (
    <div className="mb-8">
      <div className="flex justify-between mb-2">
        {labels.map((l, i) => (
          <button 
            key={i} 
            onClick={() => onStepClick(i + 1)}
            className={`text-[8px] font-black uppercase tracking-widest transition-colors hover:text-indigo-400 ${step === i + 1 ? 'text-indigo-400' : 'text-slate-600'}`}
          >
            {l}
          </button>
        ))}
      </div>
      <div className="h-1.5 w-full bg-slate-900 rounded-full overflow-hidden flex cursor-pointer">
        {[1, 2, 3, 4, 5].map(i => (
          <button 
            key={i} 
            onClick={() => onStepClick(i)}
            className={`h-full flex-1 transition-all duration-500 border-r border-slate-950 last:border-0 hover:opacity-80 ${i <= step ? 'bg-indigo-600' : 'bg-transparent'}`} 
          />
        ))}
      </div>
    </div>
  );
};

