/* COMPOSANT DE SIGNATURE */
const SignaturePad: React.FC<{ label: string, onSave: (data: string) => void, onClose: () => void }> = ({ label, onSave, onClose }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [isDrawing, setIsDrawing] = useState(false);

    const startDrawing = (e: any) => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const rect = canvas.getBoundingClientRect();
        const x = (e.clientX || e.touches[0].clientX) - rect.left;
        const y = (e.clientY || e.touches[0].clientY) - rect.top;

        ctx.beginPath();
        ctx.moveTo(x, y);
        setIsDrawing(true);
    };

    const draw = (e: any) => {
        if (!isDrawing) return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const rect = canvas.getBoundingClientRect();
        const x = (e.clientX || e.touches[0].clientX) - rect.left;
        const y = (e.clientY || e.touches[0].clientY) - rect.top;

        ctx.lineTo(x, y);
        ctx.stroke();
    };

    const stopDrawing = () => {
        setIsDrawing(false);
    };

    const clear = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        ctx?.clearRect(0, 0, canvas.width, canvas.height);
    };

    const save = () => {
        const canvas = canvasRef.current;
        if (canvas) {
            onSave(canvas.toDataURL());
        }
    };

    return (
        <div className="fixed inset-0 bg-slate-950/90 z-[700] flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl p-4 w-full max-w-sm flex flex-col gap-4">
                <h3 className="text-black font-black uppercase text-center text-sm">Signature: {label}</h3>
                <div className="border-2 border-dashed border-slate-300 rounded-xl overflow-hidden bg-white touch-none">
                    <canvas 
                        ref={canvasRef}
                        width={350}
                        height={200}
                        className="w-full h-48 cursor-crosshair"
                        onMouseDown={startDrawing}
                        onMouseMove={draw}
                        onMouseUp={stopDrawing}
                        onMouseLeave={stopDrawing}
                        onTouchStart={startDrawing}
                        onTouchMove={draw}
                        onTouchEnd={stopDrawing}
                    />
                </div>
                <div className="grid grid-cols-2 gap-2">
                    <button onClick={clear} className="bg-slate-200 text-slate-600 font-bold text-xs py-3 rounded-lg">Effacer</button>
                    <button onClick={save} className="bg-indigo-600 text-white font-bold text-xs py-3 rounded-lg">Valider</button>
                </div>
                <button onClick={onClose} className="text-slate-400 text-xs text-center font-bold">Annuler</button>
            </div>
        </div>
    );
};


