// Interface enrichie pour les cases de score
interface ScoreBox {
    value: string;
    isEnd: boolean;
    isBlocked: boolean;
    isSquare?: boolean; // AJOUTÉ : Pour le carré de fin sur side-out
}

const TeamSetColumn: React.FC<{set: MatchSet, team: Team, match: MatchState, setNumber: number, teamLabel: 'A' | 'B'}> = ({set, team, match, setNumber, teamLabel}) => {
    const formationIdx = teamLabel === 'A' ? set.startingFormationA : set.startingFormationB;
    const players = formationIdx.map(idx => team.players[idx]);
    const subs = teamLabel === 'A' ? set.subsA : set.subsB;
    const isReceivingTeam = set.firstServingTeam !== teamLabel;

    // Helper to find which column (starting position) a player belongs to, even if they are a substitute
    const getColumnForPlayerIndex = (playerIdx: number): number => {
        // 1. Direct match in starting lineup
        let col = formationIdx.indexOf(playerIdx);
        if (col !== -1) return col;

        // 2. Trace back substitutes
        let currentIdx = playerIdx;
        // Limit depth to prevent potential infinite loops
        for(let depth=0; depth<6; depth++) {
            const sub = subs.find(s => {
                const inPlayer = team.players.find(p => p.id === s.playerInId);
                const inIdx = inPlayer ? team.players.indexOf(inPlayer) : -1;
                return inIdx === currentIdx;
            });
            if (!sub) break;
            const outPlayer = team.players.find(p => p.id === sub.playerOutId);
            if (!outPlayer) break;
            const outIdx = team.players.indexOf(outPlayer);
            col = formationIdx.indexOf(outIdx);
            if (col !== -1) return col;
            currentIdx = outIdx;
        }
        return -1;
    };

    const serviceHistory = useMemo(() => {
        const rotationTurns: ScoreBox[][] = Array.from({ length: 6 }, () => []);

        // --- LOGIQUE DE DÉPART ---
        if (isReceivingTeam) {
            rotationTurns[0].push({ value: '', isEnd: false, isBlocked: true, isSquare: false });
        }

        let lastServiceColIndex = -1;

        // On parcourt les points pour trouver les "side-out" (perte de service)
        set.points.forEach((pt, idx) => {
            // Est-ce que c'était NOUS qui servions ?
            if (pt.servedByTeam === teamLabel) {
                // Est-ce qu'on a perdu le point ? (Side-Out)
                if (pt.isSideOut) {
                   const serverIdx = pt.serverPlayerIndex;
                   const colIdx = getColumnForPlayerIndex(serverIdx);
                   const myScore = teamLabel === 'A' ? pt.scoreA : pt.scoreB;

                   if (colIdx !== -1) {
                       lastServiceColIndex = colIdx;
                       rotationTurns[colIdx].push({
                           value: myScore.toString(),
                           isEnd: false, 
                           isBlocked: false,
                           isSquare: false
                       });
                   }
                }
            }
        });

        // --- LOGIQUE DE FIN DE SET : AFFICHER ET CERCLE LE DERNIER SCORE ---
        const finalScore = teamLabel === 'A' ? set.scoreA : set.scoreB;

        // 1. Chercher si le score final est déjà présent
        let found = false;
        let lastInsertedCoords = { col: -1, row: -1 };

        rotationTurns.forEach((col, cIdx) => {
            col.forEach((cell, rIdx) => {
                // Nettoyage préventif
                cell.isEnd = false;
                cell.isSquare = false;

                if (parseInt(cell.value) === finalScore) {
                    found = true;
                    // On note les coordonnées, on marquera la dernière occurrence plus tard
                    lastInsertedCoords = { col: cIdx, row: rIdx };
                }
            });
        });

        // 2. Si pas trouvé (Victoire sur Side-Out/Réception)
        if (!found && finalScore > 0) {
            // Le point doit aller dans la colonne du PROCHAIN serveur.
            let targetCol = 0;

            if (lastServiceColIndex !== -1) {
                // S'ils ont déjà servi, c'est la colonne suivante
                targetCol = (lastServiceColIndex + 1) % 6;
            } else {
                // Si équipe en réception au début: I(0) est bloqué. Le premier serveur aurait été II(1).
                if (isReceivingTeam) targetCol = 1;
                else targetCol = 0;
            }

            rotationTurns[targetCol].push({
                value: finalScore.toString(),
                isEnd: false,
                isBlocked: false,
                isSquare: true // Carré pour victoire sur side-out
            });
        } else if (lastInsertedCoords.col !== -1) {
            // Victoire sur service: On cercle la dernière occurrence
            rotationTurns[lastInsertedCoords.col][lastInsertedCoords.row].isEnd = true;
        }

        return rotationTurns;
    }, [set.points, teamLabel, formationIdx, set.firstServingTeam, subs, isReceivingTeam, set.scoreA, set.scoreB]);

    return (
        <div className="flex-1 flex flex-col bg-white">
            <div className="text-center font-black py-0.5 border-b border-black uppercase bg-slate-100 text-[8px] flex justify-between px-2 text-slate-800">
                <span className="text-blue-800">{teamLabel}</span><span>{team.name}</span>
            </div>

            <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center text-[6px] font-black uppercase bg-slate-50 border-b border-black text-slate-500">
                <div className="border-r border-black">Svc</div>
                {['I','II','III','IV','V','VI'].map(pos => <div key={pos} className="border-r border-black last:border-r-0">{pos}</div>)}
            </div>

            {/* Formation de départ */}
            <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center h-4 items-center border-b border-black">
                <div className="border-r border-black text-[5px] font-black bg-slate-50 h-full flex items-center justify-center text-slate-500">N°</div>
                {players.map((p, i) => <div key={i} className="border-r border-black last:border-r-0 h-full flex items-center justify-center font-black text-[9px] text-black">{p?.number}</div>)}
            </div>

            {/* Remplaçants + Scores associés (Format Horizontal + Lignes) */}
             <div className="grid grid-cols-[20px_repeat(6,1fr)] text-center border-b border-black">
                <div className="border-r border-black flex flex-col">
                    <div className="h-4 flex items-center justify-center text-[5px] font-black bg-slate-50 border-b border-black italic text-rose-600">Remp.</div>
                    <div className="h-6 flex items-center justify-center text-[4px] font-black bg-slate-100 italic leading-tight text-slate-400">Score</div>
                </div>

                {players.map((p, i) => {
                   const subEnter = subs.find(s => s.playerOutId === p?.id && !s.isReturn);
                   const subExit = subEnter ? subs.find(s => s.playerOutId === team.players.find(pl => pl.id === subEnter.playerInId)?.id && s.isReturn) : null;
                   const subNumber = subEnter ? team.players.find(pl => pl.id === subEnter.playerInId)?.number : null;
                   const hasReturned = !!subExit;

                   return (
                     <div key={i} className="border-r border-black last:border-r-0 flex flex-col">
                         <div className="h-4 flex items-center justify-center font-black text-[9px] border-b border-black text-rose-600">
                            {subNumber && (
                                <span className={hasReturned ? "border border-rose-600 rounded-full w-3.5 h-3.5 flex items-center justify-center bg-transparent leading-none" : ""}>
                                    {subNumber}
                                </span>
                            )}
                         </div>
                         <div className="h-6 flex flex-col items-center justify-center text-[5px] font-black leading-tight bg-slate-50 gap-0.5 text-slate-700">
                             {subEnter?.scoreAtSub && <span>{subEnter.scoreAtSub}</span>}
                             {subExit?.scoreAtSub && <span>{subExit.scoreAtSub}</span>}
                         </div>
                     </div>
                   );
                })}
            </div>

            <div className="flex-1 grid grid-cols-[20px_repeat(6,1fr)] divide-x divide-black border-b border-black">
                {/* COLONNE DES TOURS DE SERVICE (1ère, 2ème...) */}
                <div className="flex flex-col bg-slate-50 border-r border-black divide-y divide-black text-slate-500">
                    {[1,2,3,4].map(n => (
                        <div key={n} className="h-4 flex items-center justify-center leading-none">
                            <span className="text-[6px] font-black">{n}</span>
                            <sup className="text-[4px] font-bold -mt-1 ml-[0.5px]">{n === 1 ? 'ère' : 'ème'}</sup>
                        </div>
                    ))}
                </div>

                {/* GRILLE DES SCORES */}
                {serviceHistory.map((history, colIdx) => (
                    <div key={colIdx} className="flex flex-col divide-y divide-black">
                        {[0,1,2,3].map(rowIdx => {
                            const data = history[rowIdx];
                            const bgClass = data?.isBlocked ? 'bg-slate-300' : '';
                            const textColor = data?.isSquare ? 'text-emerald-700' : 'text-blue-900';

                            return (
                                <div key={rowIdx} className={`h-4 flex items-center justify-center text-[9px] font-black relative ${bgClass} ${textColor}`}>
                                    {!data?.isBlocked && data?.value}
                                    {data?.isEnd && (
                                        <div className="absolute inset-0 m-auto w-5 h-4 border-[1.5px] border-blue-900 rounded-full"></div>
                                    )}
                                    {data?.isSquare && (
                                        <div className="absolute inset-0 m-auto w-4 h-3.5 border-[1.5px] border-emerald-700"></div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                ))}
            </div>

            {/* TEMPS MORTS AGRANDIS (w-12) */}
            <div className="bg-white h-8 flex items-center px-2 mt-auto border-t border-black">
                <span className="text-[7px] font-black uppercase text-rose-600 italic flex-1">TEMPS MORTS</span>
                <div className="flex gap-2">
                    <div className="border border-black w-12 h-6 flex items-center justify-center text-[9px] font-black bg-slate-50 text-rose-600">
                        {match.history.find(e => e.type === 'TIMEOUT' && e.team === teamLabel && e.setIndex === setNumber-1)?.score || ''}
                    </div>
                    <div className="border border-black w-12 h-6 flex items-center justify-center text-[9px] font-black bg-slate-50 text-rose-600">
                        {match.history.filter(e => e.type === 'TIMEOUT' && e.team === teamLabel && e.setIndex === setNumber-1)[1]?.score || ''}
                    </div>
                </div>
            </div>
        </div>
    );
};

import { supabase } from './supabase';
import { MatchState, Team, MatchSet, Player, MatchEvent, MatchSetPoint } from './types';

// نظام قفل لمنع التداخل بين عمليات المزامنة
let isSyncing = false;
let pendingSync: (() => Promise<void>) | null = null;

/**
 * دالة المزامنة الأساسية مع نظام حماية من التداخل
 */
export async function syncMatchToSupabase(match: MatchState) {
  if (isSyncing) {
    // إذا كانت هناك عملية جارية، نقوم بجدولة العملية الحالية لتنفيذها لاحقاً
    pendingSync = () => syncMatchToSupabase(match).then(() => {});
    return { success: true, queued: true };
  }

  isSyncing = true;
  try {
    // 1. تحديث بيانات المباراة الأساسية
    const { error: matchError } = await supabase.from('vb_matches').upsert({
      id: match.matchId,
      vb_league: match.league,
      vb_city: match.city,
      vb_hall: match.hall,
      vb_category: match.category,
      vb_gender: match.gender,
      vb_match_date: match.date,
      vb_scheduled_time: match.scheduledTime,
      vb_start_time: match.startTime,
      vb_referee_1: match.referee1,
      vb_referee_2: match.referee2,
      vb_scorer: match.scorer,
      vb_line_judge_1: match.lineJudge1,
      vb_line_judge_2: match.lineJudge2,
      vb_line_judge_3: match.lineJudge3,
      vb_line_judge_4: match.lineJudge4,
      vb_remarks: match.remarks
    }, { onConflict: 'id' });

    if (matchError) throw matchError;

    // 2. تحديث الفرق واللاعبين
    await syncTeam(match.matchId, 'A', match.teamA);
    await syncTeam(match.matchId, 'B', match.teamB);

    // 3. تحديث الأشواط (المنتهية والجارية)
    if (match.sets.length > 0) {
      for (let i = 0; i < match.sets.length; i++) {
        await syncSet(match.matchId, i, match.sets[i]);
      }
    }

    if (match.isLive) {
        const currentSetObj: MatchSet = {
            scoreA: match.teamA.score,
            scoreB: match.teamB.score,
            startTime: match.currentSetStartTime,
            endTime: '',
            duration: 0,
            firstServingTeam: match.currentSetFirstServingTeam,
            startingFormationA: match.currentSetStartingFormationA,
            startingFormationB: match.currentSetStartingFormationB,
            points: match.currentSetPoints,
            subsA: match.teamA.substitutionHistory,
            subsB: match.teamB.substitutionHistory,
            timeoutsTakenA: match.teamA.timeoutsTaken,
            timeoutsTakenB: match.teamB.timeoutsTaken
        };
        await syncSet(match.matchId, match.currentSetIndex, currentSetObj);
    }

    // 4. تحديث سجل الأحداث (Logs)
    // المسح أولاً ثم الإدخال لضمان الترتيب
    await supabase.from('vb_match_event_logs').delete().eq('vb_match_id', match.matchId);

    if (match.history.length > 0) {
      const logs = match.history.map(ev => ({
        vb_match_id: match.matchId,
        vb_event_time: ev.time,
        vb_set_index: ev.setIndex,
        vb_team_side: ev.team,
        vb_event_type: ev.type,
        vb_description: ev.description,
        vb_score_display: ev.score
      }));

      const { error: logError } = await supabase.from('vb_match_event_logs').insert(logs);
      if (logError) throw logError;
    }

    return { success: true };
  } catch (error) {
    console.error("Erreur de synchronisation Supabase:", error);
    return { success: false, error };
  } finally {
    isSyncing = false;
    // إذا كان هناك طلب مزامنة معلق، نفذه الآن
    if (pendingSync) {
      const next = pendingSync;
      pendingSync = null;
      await next();
    }
  }
}

async function syncTeam(matchId: string, side: 'A' | 'B', team: Team) {
  const { data: existingTeam } = await supabase
    .from('vb_match_teams')
    .select('id')
    .eq('vb_match_id', matchId)
    .eq('vb_side', side)
    .single();

  const teamData = {
    vb_match_id: matchId,
    vb_side: side,
    vb_name: team.name,
    vb_color_primary: team.color,
    vb_color_libero: team.liberoColor,
    vb_coach_name: team.coach,
    vb_coach_license: team.coachLicense,
    vb_assistant_1_name: team.assistantCoach1,
    vb_assistant_1_license: team.assistantCoach1License,
    vb_assistant_2_name: team.assistantCoach2,
    vb_assistant_2_license: team.assistantCoach2License,
    vb_medical_name: team.medical,
    vb_medical_license: team.medicalLicense,
    vb_sets_won: team.setsWon,
    vb_timeouts_taken: team.timeoutsTaken,
    vb_substitutions_count: team.substitutionsCount
  };

  let teamId;
  if (existingTeam) {
    teamId = existingTeam.id;
    await supabase.from('vb_match_teams').update(teamData).eq('id', teamId);
  } else {
    const { data: newTeam } = await supabase.from('vb_match_teams').insert(teamData).select('id').single();
    teamId = newTeam?.id;
  }

  if (teamId) {
    await supabase.from('vb_match_players').delete().eq('vb_match_team_id', teamId);
    const players = team.players.map(p => ({
      vb_match_team_id: teamId,
      vb_jersey_number: p.number,
      vb_name: p.name,
      vb_license_number: p.licenseNumber,
      vb_is_libero: p.isLibero,
      vb_is_captain: p.isCaptain,
      vb_final_status: p.status
    }));
    await supabase.from('vb_match_players').insert(players);
  }
}

async function syncSet(matchId: string, index: number, set: MatchSet) {
  const setData = {
    vb_match_id: matchId,
    vb_set_index: index,
    vb_score_a: set.scoreA,
    vb_score_b: set.scoreB,
    vb_start_time: set.startTime,
    vb_end_time: set.endTime || '',
    vb_duration_minutes: set.duration || 0,
    vb_first_serving_team: set.firstServingTeam,
    vb_timeouts_a: set.timeoutsTakenA,
    vb_timeouts_b: set.timeoutsTakenB
  };

  const { data: existingSet } = await supabase
    .from('vb_match_sets')
    .select('id')
    .eq('vb_match_id', matchId)
    .eq('vb_set_index', index)
    .single();

  let setId;
  if (existingSet) {
    setId = existingSet.id;
    await supabase.from('vb_match_sets').update(setData).eq('id', setId);
  } else {
    const { data: newSet } = await supabase.from('vb_match_sets').insert(setData).select('id').single();
    setId = newSet?.id;
  }

  if (setId && set.points.length > 0) {
    await supabase.from('vb_set_points').delete().eq('vb_set_id', setId);
    const points = set.points.map(pt => ({
      vb_set_id: setId,
      vb_team_scored: pt.team,
      vb_score_a_after: pt.scoreA,
      vb_score_b_after: pt.scoreB,
      vb_is_side_out: pt.isSideOut,
      vb_served_by_team: pt.servedByTeam,
      vb_server_player_index: pt.serverPlayerIndex
    }));
    await supabase.from('vb_set_points').insert(points);
  }
}

export async function fetchFullMatch(matchId: string): Promise<MatchState | null> {
  const { data: m, error } = await supabase
    .from('vb_matches')
    .select(`
      *,
      vb_match_teams(*, vb_match_players(*)),
      vb_match_sets(*, vb_set_points(*)),
      vb_match_event_logs(*)
    `)
    .eq('id', matchId)
    .single();

  if (error || !m) return null;

  const teamAData = m.vb_match_teams.find((t: any) => t.vb_side === 'A');
  const teamBData = m.vb_match_teams.find((t: any) => t.vb_side === 'B');

  const mapTeam = (td: any): Team => ({
    name: td.vb_name,
    color: td.vb_color_primary,
    playerColor: td.vb_color_primary,
    liberoColor: td.vb_color_libero,
    players: td.vb_match_players.map((p: any) => ({
      id: p.id,
      number: p.vb_jersey_number,
      name: p.vb_name,
      licenseNumber: p.vb_license_number,
      isLibero: p.vb_is_libero,
      isCaptain: p.vb_is_captain,
      status: p.vb_final_status
    })),
    score: 0,
    setsWon: td.vb_sets_won,
    timeoutsTaken: td.vb_timeouts_taken,
    substitutionsCount: td.vb_substitutions_count,
    formation: [-1, -1, -1, -1, -1, -1],
    substitutionHistory: [],
    hasDelayWarning: false,
    coach: td.vb_coach_name,
    coachLicense: td.vb_coach_license,
    assistantCoach1: td.vb_assistant_1_name,
    assistantCoach1License: td.vb_assistant_1_license,
    assistantCoach2: td.vb_assistant_2_name || '',
    assistantCoach2License: td.vb_assistant_2_license || '',
    medical: td.vb_medical_name,
    medicalLicense: td.vb_medical_license,
    sanctionedStaff: []
  });

  const sets: MatchSet[] = m.vb_match_sets.sort((a:any, b:any) => a.vb_set_index - b.vb_set_index).map((s: any) => ({
    scoreA: s.vb_score_a,
    scoreB: s.vb_score_b,
    startTime: s.vb_start_time,
    endTime: s.vb_end_time,
    duration: s.vb_duration_minutes,
    firstServingTeam: s.vb_first_serving_team,
    startingFormationA: [],
    startingFormationB: [],
    subsA: [],
    subsB: [],
    timeoutsTakenA: s.vb_timeouts_a,
    timeoutsTakenB: s.vb_timeouts_b,
    points: s.vb_set_points.map((pt: any) => ({
      team: pt.vb_team_scored,
      scoreA: pt.vb_score_a_after,
      scoreB: pt.vb_score_b_after,
      isSideOut: pt.vb_is_side_out,
      servedByTeam: pt.vb_served_by_team,
      serverPlayerIndex: pt.vb_server_player_index
    }))
  }));

  const history: MatchEvent[] = m.vb_match_event_logs.sort((a: any, b: any) => a.id - b.id).map((l: any) => ({
    time: l.vb_event_time,
    setIndex: l.vb_set_index,
    team: l.vb_team_side,
    type: l.vb_event_type,
    description: l.vb_description,
    score: l.vb_score_display
  }));

  const currentSet = sets[sets.length - 1];
  const teamA = mapTeam(teamAData);
  const teamB = mapTeam(teamBData);
  teamA.score = currentSet?.scoreA || 0;
  teamB.score = currentSet?.scoreB || 0;

  return {
    matchId: m.id,
    league: m.vb_league,
    city: m.vb_city,
    hall: m.vb_hall,
    category: m.vb_category,
    gender: m.vb_gender,
    date: m.vb_match_date,
    scheduledTime: m.vb_scheduled_time,
    referee1: m.vb_referee_1,
    referee2: m.vb_referee_2,
    scorer: m.vb_scorer,
    lineJudge1: m.vb_line_judge_1,
    lineJudge2: m.vb_line_judge_2,
    lineJudge3: m.vb_line_judge_3,
    lineJudge4: m.vb_line_judge_4,
    teamA,
    teamB,
    servingTeam: null,
    sets,
    currentSetIndex: sets.length > 0 ? sets.length - 1 : 0,
    currentSetStartTime: currentSet?.startTime || '',
    currentSetPoints: currentSet?.points || [],
    currentSetStartingFormationA: [],
    currentSetStartingFormationB: [],
    currentSetFirstServingTeam: 'A',
    startTime: m.vb_start_time,
    isLive: true,
    history,
    playerSanctions: [],
    isTeamAOnLeft: true,
    hasSwitchedInDecisiveSet: false,
    remarks: m.vb_remarks,
    signatures: {}
  };
}

export async function fetchMatchHistory() {
  const { data, error } = await supabase
    .from('vb_matches')
    .select(`*, vb_match_teams(*)`)
    .order('vb_created_at', { ascending: false });

  if (error) return [];

  return data.map((m: any) => {
