interface Props {
  match: MatchState;
  setMatch: React.Dispatch<React.SetStateAction<MatchState>>;
  onEnd: () => void;
  onSpectator: () => void;
}

const useLongPress = (onLongPress: () => void, onClick: (e: React.MouseEvent | React.TouchEvent) => void, { delay = 500 } = {}) => {
    const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const isLongPress = useRef(false);

    const start = useCallback(() => {
        isLongPress.current = false;
        timerRef.current = setTimeout(() => {
            isLongPress.current = true;
            onLongPress();
        }, delay);
    }, [onLongPress, delay]);

    const stop = useCallback((e: React.MouseEvent | React.TouchEvent) => {
        if (timerRef.current) clearTimeout(timerRef.current);
        if (!isLongPress.current) onClick(e);
    }, [onClick]);

    return {
        onMouseDown: start,
        onTouchStart: start,
        onMouseUp: stop,
        onTouchEnd: stop,
        onMouseLeave: () => { if(timerRef.current) clearTimeout(timerRef.current) },
    };
};

const formatTime = (seconds: number) => {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

const getNowHHMM = () => {
  const now = new Date();
  const hours = now.getHours().toString().padStart(2, '0');
  const minutes = now.getMinutes().toString().padStart(2, '0');
  return `${hours}:${minutes}`;
};

const addMinutesToTime = (timeStr: string, minutesToAdd: number): string => {
    if (!timeStr) return getNowHHMM();
    try {
        const [h, m] = timeStr.split(':').map(Number);
        const totalMinutes = h * 60 + m + minutesToAdd;
        const newH = Math.floor(totalMinutes / 60) % 24;
        const newM = totalMinutes % 60;
        return `${newH.toString().padStart(2, '0')}:${newH.toString().padStart(2, '0')}`;
    } catch (e) {
        return getNowHHMM();
    }
};

const calculateDurationInMinutes = (startTime: string, endTime: string): number => {
    if (!startTime || !endTime) return 0;
    try {
        const [startH, startM] = startTime.split(':').map(Number);
        const [endH, endM] = endTime.split(':').map(Number);

        const startMinutes = startH * 60 + startM;
        const endMinutes = endH * 60 + endM;

        let diff = endMinutes - startMinutes;
        if (diff < 0) diff += 24 * 60;

        return diff > 0 ? diff : 1;
    } catch (e) {
        return 0;
    }
};

const getContrastYIQ = (hexcolor: string) => {
    if (!hexcolor) return '#ffffff';
    const hex = hexcolor.replace('#', '');
    const r = parseInt(hex.substr(0, 2), 16);
    const g = parseInt(hex.substr(2, 2), 16);
    const b = parseInt(hex.substr(4, 2), 16);
    const yiq = ((r * 299) + (g * 587) + (b * 114)) / 1000;
    return yiq >= 128 ? '#000000' : '#ffffff';
};

export const MatchLive: React.FC<Props> = ({ match, setMatch, onEnd, onSpectator }) => {
  const [showSanction, setShowSanction] = useState<{ team: 'A' | 'B' | null }>({ team: null });
  const [showSubModal, setShowSubModal] = useState<{team: 'A' | 'B', forcedPlayerOutId?: string | null} | null>(null);
  const [activeTab, setActiveTab] = useState('positions');
  const [timeoutTimer, setTimeoutTimer] = useState<number | null>(null);
  const [breakTimer, setBreakTimer] = useState<number | null>(null);
  const [isEnteringFormation, setIsEnteringFormation] = useState(false);
  const [tempFormationA, setTempFormationA] = useState<number[]>([-1, -1, -1, -1, -1, -1]);
  const [tempFormationB, setTempFormationB] = useState<number[]>([-1, -1, -1, -1, -1, -1]);
  const [matchHistory, setMatchHistory] = useState<MatchState[]>([]);
  const [pendingStartFormations, setPendingStartFormations] = useState<{a: number[], b: number[]} | null>(null);

  // State pour le choix du serveur au Tie-Break
  const [tieBreakServer, setTieBreakServer] = useState<'A' | 'B' | null>(null);

  const lastClickTimeRef = useRef<number>(0);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const breakRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const prevSetIndexRef = useRef(match.currentSetIndex);

  const leftTeam = match.isTeamAOnLeft ? match.teamA : match.teamB;
  const rightTeam = match.isTeamAOnLeft ? match.teamB : match.teamA;
  const leftId = match.isTeamAOnLeft ? 'A' : 'B';
  const rightId = match.isTeamAOnLeft ? 'B' : 'A';

  const saveStateForUndo = (currentState: MatchState) => {
    setMatchHistory(prev => [...prev.slice(-5), JSON.parse(JSON.stringify(currentState))]);
  };

  const handleUndo = () => {
    if (matchHistory.length === 0) return;
    const previousState = matchHistory[matchHistory.length - 1];
    setMatch(previousState);
    setMatchHistory(prev => prev.slice(0, -1));
    setTimeoutTimer(null);
  };

  const cancelLastActionForTeam = (teamId: 'A' | 'B', actionType: 'TIMEOUT' | 'SANCTION' | 'SUB') => {
    const lastEvent = match.history.length > 0 ? match.history[match.history.length - 1] : null;
    if (lastEvent && lastEvent.type === actionType && lastEvent.team === teamId) {
      handleUndo();
    }
  };

  // Gestion du Timer de Temps Mort
  useEffect(() => {
    if (timeoutTimer !== null) {
      if (timeoutTimer > 0) {
        timerRef.current = setTimeout(() => setTimeoutTimer(t => (t ? t - 1 : 0)), 1000);
      } else { setTimeoutTimer(null); }
    }
    return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [timeoutTimer]);

  // Gestion du Timer de Pause (3 min)
  useEffect(() => {
    if (breakTimer !== null) {
        if (breakTimer > 0) {
            breakRef.current = setTimeout(() => setBreakTimer(b => (b ? b - 1 : 0)), 1000);
        } else {
            setBreakTimer(null);
            if (pendingStartFormations) {
                commitSetStart(pendingStartFormations.a, pendingStartFormations.b);
                setPendingStartFormations(null);
            }
        }
    }
    return () => { if (breakRef.current) clearTimeout(breakRef.current); };
  }, [breakTimer, pendingStartFormations]);

  // Gestion des changements de set (Détection pour lancer le timer)
  useEffect(() => {
      const prev = prevSetIndexRef.current;
      const curr = match.currentSetIndex;

      // Si on passe au set suivant (Index augmente) ET que le match n'est pas fini
      if (curr > prev && match.isLive) {
          setBreakTimer(180); // 3 minutes
          setTempFormationA([-1, -1, -1, -1, -1, -1]);
          setTempFormationB([-1, -1, -1, -1, -1, -1]);
          setPendingStartFormations(null);
          setTieBreakServer(null);
      } 
      // Si on revient en arrière (Undo/Correction)
      else if (curr < prev) {
          setBreakTimer(null);
      }

      prevSetIndexRef.current = curr;
  }, [match.currentSetIndex, match.isLive]);

  const checkSetEnd = (state: MatchState) => {
    const isTieBreak = state.currentSetIndex === 4;
    const limit = isTieBreak ? 15 : 25;
    const { scoreA, scoreB } = { scoreA: state.teamA.score, scoreB: state.teamB.score };

    if ((scoreA >= limit || scoreB >= limit) && Math.abs(scoreA - scoreB) >= 2) {
      const now = getNowHHMM();
      const duration = calculateDurationInMinutes(state.currentSetStartTime, now);

      state.sets.push({ 
        scoreA, scoreB, startTime: state.currentSetStartTime, endTime: now, duration: duration,
        firstServingTeam: state.currentSetFirstServingTeam, 
        startingFormationA: [...state.currentSetStartingFormationA], 
        startingFormationB: [...state.currentSetStartingFormationB],
        endFormationA: [...state.teamA.formation],
        endFormationB: [...state.teamB.formation],
        subsA: [...state.teamA.substitutionHistory], subsB: [...state.teamB.substitutionHistory],
        timeoutsTakenA: state.teamA.timeoutsTaken, timeoutsTakenB: state.teamB.timeoutsTaken,
        points: [...state.currentSetPoints]
      });
      state.currentSetPoints = [];

      if (scoreA > scoreB) state.teamA.setsWon += 1; else state.teamB.setsWon += 1;

      state.teamA.players.forEach(p => { if(p.status === 'EXPELLED') p.status = 'ACTIVE' });
      state.teamB.players.forEach(p => { if(p.status === 'EXPELLED') p.status = 'ACTIVE' });

      if (state.teamA.setsWon === 3 || state.teamB.setsWon === 3) { 
        state.isLive = false; 
        return; 
      }

      state.currentSetIndex += 1;
      state.servingTeam = null;
      state.isTeamAOnLeft = !state.isTeamAOnLeft; 
      state.hasSwitchedInDecisiveSet = false;

      // Les effets de bord (setBreakTimer etc.) sont gérés par le useEffect qui surveille currentSetIndex
    }
  };

  const prepareFormationEntry = () => {
    setIsEnteringFormation(true);
  };

  const handleReopenLastSet = () => {
    if (match.currentSetIndex === 0) return;
    if (!window.confirm("Voulez-vous vraiment annuler la fin du dernier set et corriger le score ?")) return;

    const setIndexToReopen = match.currentSetIndex - 1;
    const setMap = match.sets[setIndexToReopen];

    setBreakTimer(null);
    setPendingStartFormations(null);
    setIsEnteringFormation(false);
    setTimeoutTimer(null);

    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.sets = next.sets.slice(0, setIndexToReopen);
        next.currentSetIndex = setIndexToReopen;
        next.teamA.score = setMap.scoreA;
        next.teamB.score = setMap.scoreB;
        if (setMap.scoreA > setMap.scoreB) next.teamA.setsWon--;
        else next.teamB.setsWon--;
        next.currentSetPoints = setMap.points;
        next.currentSetStartTime = setMap.startTime;
        next.currentSetFirstServingTeam = setMap.firstServingTeam;
        next.currentSetStartingFormationA = setMap.startingFormationA;
        next.currentSetStartingFormationB = setMap.startingFormationB;
        next.teamA.formation = setMap.endFormationA || setMap.startingFormationA; 
        next.teamB.formation = setMap.endFormationB || setMap.startingFormationB;
        next.teamA.timeoutsTaken = setMap.timeoutsTakenA;
        next.teamB.timeoutsTaken = setMap.timeoutsTakenB;
        next.teamA.substitutionHistory = setMap.subsA;
        next.teamB.substitutionHistory = setMap.subsB;
        next.teamA.substitutionsCount = setMap.subsA.length;
        next.teamB.substitutionsCount = setMap.subsB.length;
        next.isTeamAOnLeft = !next.isTeamAOnLeft;
        const lastPoint = setMap.points[setMap.points.length - 1];
        if (lastPoint) {
             next.servingTeam = lastPoint.team;
        } else {
             next.servingTeam = setMap.firstServingTeam;
        }
        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex,
            team: 'NONE',
            type: 'SYSTEM',
            description: `Correction: Retour au Set ${next.currentSetIndex + 1}`,
            score: `${next.teamA.score}-${next.teamB.score}`
        });
        return next;
    });
    setActiveTab('positions');
  };

  const handleSkipBreak = () => {
      if (pendingStartFormations) {
          commitSetStart(pendingStartFormations.a, pendingStartFormations.b);
          setPendingStartFormations(null);
      }
      setBreakTimer(null);
  };

  const onFormationSubmit = () => {
    if (tempFormationA.includes(-1) || tempFormationB.includes(-1)) return;

    // Validation pour le Tie-Break
    if (match.currentSetIndex === 4 && !tieBreakServer) {
        alert("Veuillez sélectionner l'équipe qui sert pour le set décisif.");
        return;
    }

    setIsEnteringFormation(false);
    if (breakTimer === null || breakTimer <= 0) {
        commitSetStart(tempFormationA, tempFormationB);
    } else {
        setPendingStartFormations({
            a: [...tempFormationA],
            b: [...tempFormationB]
        });
    }
  };

  const commitSetStart = (formationA: number[], formationB: number[]) => {
    saveStateForUndo(match);
    setBreakTimer(null);
    let calculatedStartTime = getNowHHMM();
    const lastSet = match.sets[match.sets.length - 1];
    if (lastSet && lastSet.endTime) {
        calculatedStartTime = addMinutesToTime(lastSet.endTime, 3);
    }

    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        next.teamA.score = 0;
        next.teamB.score = 0;
        next.teamA.timeoutsTaken = 0;
        next.teamB.timeoutsTaken = 0;
        next.teamA.substitutionsCount = 0;
        next.teamB.substitutionsCount = 0;
        next.teamA.substitutionHistory = [];
        next.teamB.substitutionHistory = [];

        let nextServer = prev.currentSetFirstServingTeam === 'A' ? 'B' : 'A';
        // Override pour le Tie-Break
        if (prev.currentSetIndex === 4 && tieBreakServer) {
            nextServer = tieBreakServer;
        }

        next.currentSetFirstServingTeam = nextServer;
        next.servingTeam = nextServer;
        next.teamA.formation = [...formationA];
        next.teamB.formation = [...formationB];
        next.currentSetStartingFormationA = [...formationA];
        next.currentSetStartingFormationB = [...formationB];
        next.currentSetStartTime = calculatedStartTime;
        next.history.push({
            time: calculatedStartTime,
            setIndex: next.currentSetIndex,
            team: 'NONE',
            type: 'SET_START',
            description: `Début Set ${next.currentSetIndex + 1}`,
            score: "0-0"
        });
        return next;
    });
  };

  const handleApplySanction = (type: SanctionType, subjectId?: string) => {
    if (!subjectId || !showSanction.team) return;

    if (type === SanctionType.WARNING) {
        const hasExistingWarning = match.playerSanctions.some(s => s.team === showSanction.team && s.type === SanctionType.WARNING);
        if (hasExistingWarning) {
            alert(`L'équipe ${showSanction.team === 'A' ? match.teamA.name : match.teamB.name} a déjà reçu son avertissement (Jaune).`);
            return;
        }
    }

    saveStateForUndo(match);
    const sanctionedTeamId = showSanction.team;
    setShowSanction({ team: null });

    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        const sanctionedTeam = sanctionedTeamId === 'A' ? next.teamA : next.teamB;
        const currentScore = sanctionedTeamId === 'A' ? `${next.teamA.score}:${next.teamB.score}` : `${next.teamB.score}:${next.teamA.score}`;
        const sanction: PlayerSanction = { 
          playerId: subjectId, type: type, setIndex: prev.currentSetIndex, scoreAtSanction: currentScore, team: sanctionedTeamId
        };
        next.playerSanctions.push(sanction);
        const player = sanctionedTeam.players.find((p: Player) => p.id === subjectId);
        if (player) {
            if (type === SanctionType.EXPULSION) player.status = 'EXPELLED';
            if (type === SanctionType.DISQUALIFICATION) player.status = 'DISQUALIFIED';
            if (sanctionedTeam.formation.includes(sanctionedTeam.players.indexOf(player)) && 
               (type === SanctionType.EXPULSION || type === SanctionType.DISQUALIFICATION)) {
                setTimeout(() => setShowSubModal({ team: sanctionedTeamId, forcedPlayerOutId: subjectId }), 100);
            }
        }

        const subjectDesc = player ? `#${player.number} ${player.name}` : 'Personnel';

        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex, team: sanctionedTeamId, type: 'SANCTION',
            description: `${type} pour ${subjectDesc} (${sanctionedTeam.name})`, 
            score: `${next.teamA.score}-${next.teamB.score}`
        });
        if (type === SanctionType.PENALTY || type === SanctionType.DELAY_PENALTY) {
            const otherTeamId = sanctionedTeamId === 'A' ? 'B' : 'A';
            const otherTeam = otherTeamId === 'A' ? next.teamA : next.teamB;
            const servingTeamId = next.servingTeam || next.currentSetFirstServingTeam;
            const servingTeam = servingTeamId === 'A' ? next.teamA : next.teamB;
            const serverIdx = servingTeam.formation[0];
            next.servingTeam = otherTeamId;
            otherTeam.score += 1;
            next.currentSetPoints.push({ 
                team: otherTeamId, 
                scoreA: next.teamA.score, 
                scoreB: next.teamB.score,
                isSideOut: servingTeamId !== otherTeamId,
                servedByTeam: servingTeamId,
                serverPlayerIndex: serverIdx
            });
            next.history.push({
                time: getNowHHMM(),
                setIndex: next.currentSetIndex,
                team: otherTeamId,
                type: 'POINT',
                description: `Point via Pénalité (${otherTeam.name})`,
                score: `${next.teamA.score}-${next.teamB.score}`
            });
            checkSetEnd(next);
        }
        return next;
    });
  };

  const handleApplySubstitution = (teamId: 'A' | 'B', playerOutId: string, playerInId: string) => {
    saveStateForUndo(match);
    setMatch(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        const team = teamId === 'A' ? next.teamA : next.teamB;
        const outIdx = team.players.findIndex((p: Player) => p.id === playerOutId);
        const inIdx = team.players.findIndex((p: Player) => p.id === playerInId);
        const posInForm = team.formation.indexOf(outIdx);
        if (posInForm === -1 || inIdx === -1) return prev;

        const playerIn = team.players[inIdx];
        const playerOut = team.players[outIdx];

        team.formation[posInForm] = inIdx;
        const isReturn = team.substitutionHistory.some((s: Substitution) => s.playerInId === playerOutId && s.playerOutId === playerInId);
        const scoreString = teamId === 'A' ? `${next.teamA.score}:${next.teamB.score}` : `${next.teamB.score}:${next.teamA.score}`;
        team.substitutionHistory.push({ playerOutId, playerInId, isReturn, scoreAtSub: scoreString });
        team.substitutionsCount += 1;

        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex, team: teamId, type: 'SUB',
            description: `Remp: #${playerIn.number} ${playerIn.name} بدلاً من #${playerOut.number} ${playerOut.name}`,
            score: `${next.teamA.score}-${next.teamB.score}`
        });
        setShowSubModal(null);
        return next;
    });
  };

  const addPoint = (winnerTeamId: 'A' | 'B') => {
    // حماية ضد النقرات المتعددة السريعة (300ms)
    const now = Date.now();
    if (now - lastClickTimeRef.current < 300) return;
    lastClickTimeRef.current = now;

    if (isMatchOver || timeoutTimer !== null || breakTimer !== null) return;

    saveStateForUndo(match);
    setMatch(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      const winningTeam = winnerTeamId === 'A' ? next.teamA : next.teamB;
      const currentServingTeamId = prev.servingTeam;
      const actualServingTeamId = currentServingTeamId || next.currentSetFirstServingTeam;
      const servingTeam = actualServingTeamId === 'A' ? prev.teamA : prev.teamB;
      const serverIdx = servingTeam.formation[0]; 
      const isSideOut = actualServingTeamId !== winnerTeamId;

      if (isSideOut) {
        const f = winningTeam.formation;
        winningTeam.formation = [f[1], f[2], f[3], f[4], f[5], f[0]];
      }

      next.servingTeam = winnerTeamId;
      winningTeam.score += 1;

      next.currentSetPoints.push({ 
          team: winnerTeamId, 
          scoreA: next.teamA.score, 
          scoreB: next.teamB.score,
          isSideOut: isSideOut,
          servedByTeam: actualServingTeamId,
          serverPlayerIndex: serverIdx
      });

      next.history.push({
        time: getNowHHMM(),
        setIndex: next.currentSetIndex,
        team: winnerTeamId,
        type: 'POINT',
        description: `Point ${winningTeam.name}`,
        score: `${next.teamA.score}-${next.teamB.score}`
      });

      if (next.currentSetIndex === 4 && !next.hasSwitchedInDecisiveSet && (next.teamA.score === 8 || next.teamB.score === 8)) {
        next.isTeamAOnLeft = !next.isTeamAOnLeft;
        next.hasSwitchedInDecisiveSet = true;
        next.history.push({
            time: getNowHHMM(),
            setIndex: next.currentSetIndex,
            team: 'NONE',
            type: 'SIDE_SWITCH',
            description: `Changement de camp (Score 8)`,
            score: `${next.teamA.score}-${next.teamB.score}`
        });
      }
      checkSetEnd(next);
      return next;
    });
  };

  const isMatchOver = match.teamA.setsWon === 3 || match.teamB.setsWon === 3;
  const timeoutHandlersLeft = useLongPress(() => cancelLastActionForTeam(leftId, 'TIMEOUT'), () => triggerTimeout(leftId));
  const timeoutHandlersRight = useLongPress(() => cancelLastActionForTeam(rightId, 'TIMEOUT'), () => triggerTimeout(rightId));

  const triggerTimeout = (teamId: 'A' | 'B') => {
    const team = teamId === 'A' ? match.teamA : match.teamB;
    if (team.timeoutsTaken >= 2 || timeoutTimer !== null || breakTimer !== null) return;
    saveStateForUndo(match);
    setMatch(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      const target = teamId === 'A' ? next.teamA : next.teamB;
      target.timeoutsTaken += 1;
       next.history.push({
        time: getNowHHMM(),
        setIndex: next.currentSetIndex, team: teamId, type: 'TIMEOUT',
        description: `TM ${target.name}`, score: `${next.teamA.score}-${next.teamB.score}`
      });
      return next;
    });
    setTimeoutTimer(30);
  };

  const leftTextColor = getContrastYIQ(leftTeam.playerColor);
  const rightTextColor = getContrastYIQ(rightTeam.playerColor);
  const leftSetColor = leftTeam.color;
  const rightSetColor = rightTeam.color;
  const leftSetTextColor = getContrastYIQ(leftSetColor);
  const rightSetTextColor = getContrastYIQ(rightSetColor);

  return (
    <div className="flex flex-col h-[92vh] max-w-md mx-auto p-2 bg-slate-950 border border-slate-900 rounded-[2rem] relative shadow-2xl overflow-hidden text-right">
      {timeoutTimer !== null && (
        <div className="absolute top-0 left-0 right-0 z-[520] bg-indigo-600 p-4 flex flex-col items-center justify-center shadow-2xl animate-in slide-in-from-top duration-300">
           <div className="flex items-center gap-4">
              <span className="text-white text-3xl font-black tabular-nums">{timeoutTimer}s</span>
              <div className="h-8 w-px bg-white/20"></div>
              <div className="text-right">
                <div className="text-white font-black uppercase text-[10px] tracking-widest">Temps Mort</div>
                <div className="text-indigo-200 text-[8px] font-bold uppercase">Reprise automatique dans...</div>
              </div>
              <button onClick={() => setTimeoutTimer(null)} className="ml-4 bg-white/20 hover:bg-white/30 text-white px-3 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all">Passer</button>
           </div>
           <div className="w-full mt-3 h-1.5 bg-indigo-900/50 rounded-full overflow-hidden">
              <div className="h-full bg-white transition-all duration-1000" style={{ width: `${(timeoutTimer/30) * 100}%` }}></div>
           </div>
        </div>
      )}

      {isEnteringFormation && (
        <div className="absolute inset-0 z-[510] bg-slate-950 flex flex-col animate-in slide-in-from-bottom duration-300">
          <header className="flex justify-between items-center px-4 py-3 border-b border-slate-800 bg-slate-900 flex-wrap gap-2">
             <div className="flex items-center gap-3">
                 <h2 className="text-white font-black uppercase text-sm italic tracking-widest leading-none">Formation Set {match.currentSetIndex + 1}</h2>
                 {breakTimer !== null && (
                     <div className="bg-slate-800 px-3 py-1 rounded-lg border border-slate-700 flex items-center gap-2">
                        <span className="text-[9px] font-black text-slate-500 uppercase hidden sm:inline">Repos</span>
                        <span className="text-lg font-black text-emerald-400 tabular-nums leading-none">{formatTime(breakTimer)}</span>
                     </div>
                 )}
             </div>

             {/* SÉLECTEUR DE TOSS POUR LE SET 5 */}
             {match.currentSetIndex === 4 && (
                 <div className="flex items-center gap-2 bg-slate-800/80 p-1.5 rounded-lg border border-slate-700/50 ml-auto mr-auto">
                     <span className="text-[9px] font-black uppercase text-indigo-300 pl-1">Qui sert ?</span>
                     <button 
                        onClick={() => setTieBreakServer('A')}
                        className={`w-8 h-8 rounded-md flex items-center justify-center font-black text-xs transition-all border ${tieBreakServer === 'A' ? 'border-white scale-105 shadow-lg' : 'border-transparent opacity-50'}`}
                        style={{ backgroundColor: match.teamA.color, color: getContrastYIQ(match.teamA.color) }}
                     >
                        A
                     </button>
                     <button 
                        onClick={() => setTieBreakServer('B')}
                        className={`w-8 h-8 rounded-md flex items-center justify-center font-black text-xs transition-all border ${tieBreakServer === 'B' ? 'border-white scale-105 shadow-lg' : 'border-transparent opacity-50'}`}
                        style={{ backgroundColor: match.teamB.color, color: getContrastYIQ(match.teamB.color) }}
                     >
                        B
                     </button>
                 </div>
             )}

             <button onClick={() => setIsEnteringFormation(false)} className="bg-slate-900 border border-slate-800 text-slate-500 px-3 py-1 rounded-lg text-[9px] font-black uppercase ml-auto">Fermer</button>
          </header>

          <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
             <div className="flex gap-2 h-full">
                <div className="flex-1 bg-white rounded-2xl p-2 border border-slate-200 flex flex-col h-full overflow-hidden">
                   <div className="mb-2 text-center bg-blue-100 rounded-lg py-1.5 flex justify-center items-center gap-2">
                       <span className="text-[10px] font-black uppercase text-blue-600">{leftTeam.name}</span>
                   </div>
                   <FormationGrid 
                       team={leftTeam} 
                       tempF={match.isTeamAOnLeft ? tempFormationA : tempFormationB} 
                       setTempF={match.isTeamAOnLeft ? setTempFormationA : setTempFormationB} 
                   />
                </div>
                <div className="flex-1 bg-white rounded-2xl p-2 border border-slate-200 flex flex-col h-full overflow-hidden">
                   <div className="mb-2 text-center bg-blue-100 rounded-lg py-1.5 flex justify-center items-center gap-2">
                       <span className="text-[10px] font-black uppercase text-blue-600">{rightTeam.name}</span>
                   </div>
                   <FormationGrid 
                       team={rightTeam} 
                       tempF={match.isTeamAOnLeft ? tempFormationB : tempFormationA} 
                       setTempF={match.isTeamAOnLeft ? setTempFormationB : setTempFormationA} 
                   />
                </div>
             </div>
          </div>

          <div className="p-4 border-t border-slate-800 bg-slate-900">
             <button onClick={onFormationSubmit} className="w-full py-4 bg-emerald-600 text-white rounded-xl font-black uppercase text-xs tracking-widest shadow-xl border-b-4 border-emerald-900 active:scale-95">Démarrer le Set 🏐</button>
          </div>
        </div>
      )}

      <div className={`shrink-0 flex flex-col gap-2 bg-slate-950 pb-2 z-10 transition-opacity ${(isEnteringFormation) ? 'opacity-20 pointer-events-none' : 'opacity-100'}`}>
        <div className="grid grid-cols-2 gap-2">
          <button 
             onClick={() => addPoint(leftId)} 
             className="h-28 rounded-2xl flex flex-col items-center justify-center transition-all shadow-lg border-b-4 border-black/30 active:scale-95 relative overflow-hidden group" 
             style={{ backgroundColor: leftTeam.playerColor }}
          >
             <div className="absolute -top-10 -right-10 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:bg-white/20 transition-all"></div>
            <span className="text-[11px] font-black uppercase truncate w-full px-2 text-center z-10 opacity-70" style={{ color: leftTextColor }}>{leftTeam.name}</span>
            <span className="text-6xl font-black leading-none z-10" style={{ color: leftTextColor }}>{leftTeam.score}</span>
          </button>

          <button 
             onClick={() => addPoint(rightId)} 
             className="h-28 rounded-2xl flex flex-col items-center justify-center transition-all shadow-lg border-b-4 border-black/30 active:scale-95 relative overflow-hidden group" 
             style={{ backgroundColor: rightTeam.playerColor }}
          >
             <div className="absolute -top-10 -right-10 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:bg-white/20 transition-all"></div>
            <span className="text-[11px] font-black uppercase truncate w-full px-2 text-center z-10 opacity-70" style={{ color: rightTextColor }}>{rightTeam.name}</span>
            <span className="text-6xl font-black leading-none z-10" style={{ color: rightTextColor }}>{rightTeam.score}</span>
          </button>
        </div>

        <div className="bg-slate-900/80 rounded-2xl p-2 border border-slate-800 flex flex-col items-center justify-center min-h-[50px] relative group gap-2">
           <div className="text-2xl font-black text-white flex gap-4 items-center">
             <div 
                className="w-10 h-10 flex items-center justify-center rounded-lg shadow-inner border-2 border-slate-800"
                style={{ backgroundColor: leftSetColor, color: leftSetTextColor }}
             >
                {leftTeam.setsWon}
             </div>
             <span className="text-slate-500 text-[9px] font-black uppercase tracking-widest flex flex-col items-center">
                <span>SET</span>
                <span className="text-white text-xs">{match.currentSetIndex + 1}</span>
             </span>
             <div 
                className="w-10 h-10 flex items-center justify-center rounded-lg shadow-inner border-2 border-slate-800"
                style={{ backgroundColor: rightSetColor, color: rightSetTextColor }}
             >
                {rightTeam.setsWon}
             </div>
           </div>

           {breakTimer !== null && (
             <div className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2 flex items-center justify-between animate-in slide-in-from-top duration-300">
                <div className="flex items-center gap-3">
                   <span className="text-[9px] font-black uppercase text-slate-500 tracking-widest">Repos</span>
                   <span className="text-2xl font-black text-emerald-400 tabular-nums">{formatTime(breakTimer)}</span>
                </div>
                {pendingStartFormations ? (
                    <div className="flex-1 text-center px-2">
                         <span className="text-[8px] font-bold text-indigo-400 uppercase animate-pulse">Formation validée</span>
                    </div>
                ) : null}
                <div className="flex gap-2">
                    <button onClick={handleSkipBreak} className="bg-slate-800 text-slate-400 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase hover:text-white transition-all">Sauter</button>
                    <button onClick={prepareFormationEntry} disabled={pendingStartFormations !== null} className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase shadow-lg border-b-2 transition-all ${pendingStartFormations !== null ? 'bg-indigo-900 border-indigo-950 text-indigo-300' : 'bg-emerald-600 text-white border-emerald-800 active:border-b-0 active:translate-y-0.5'}`}>{pendingStartFormations !== null ? 'Prêt' : 'Suite →'}</button>
                </div>
             </div>
           )}
        </div>

        <div className="grid grid-cols-5 gap-2 shrink-0">
          <MiniBtn icon="⏱️" label="TM" count={leftTeam.timeoutsTaken} disabled={isMatchOver} {...timeoutHandlersLeft} />
          <MiniBtn icon="🎴" label="SANCTION" disabled={isMatchOver} onClick={() => setShowSanction({ team: leftId })} />
          <MiniBtn icon="↩️" label="UNDO" disabled={matchHistory.length === 0} onClick={handleUndo} />
          <MiniBtn icon="🎴" label="SANCTION" disabled={isMatchOver} onClick={() => setShowSanction({ team: rightId })} />
          <MiniBtn icon="⏱️" label="TM" count={rightTeam.timeoutsTaken} disabled={isMatchOver} {...timeoutHandlersRight} />
        </div>

        <div className="bg-slate-900 rounded-lg p-0.5 flex border border-slate-800 shrink-0">
          <Tab icon="🏐" active={activeTab === 'positions'} onClick={() => setActiveTab('positions')} />
          <Tab icon="⇅" active={activeTab === 'subs'} onClick={() => setActiveTab('subs')} />
          <Tab icon="📈" active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} />
          <Tab icon="🗂️" active={activeTab === 'archive'} onClick={() => setActiveTab('archive')} />
        </div>
      </div>

      <div className={`flex-1 overflow-hidden flex flex-col transition-opacity ${(isEnteringFormation) ? 'opacity-20 pointer-events-none' : 'opacity-100'}`}>
          {activeTab === 'positions' && (
            <div className="space-y-2 py-1 flex-1 overflow-y-auto custom-scrollbar flex flex-col">
              <CourtView teamLeft={leftTeam} teamRight={rightTeam} servingTeamId={match.servingTeam} leftId={leftId} rightId={rightId} sanctions={match.playerSanctions} />
              <div className="flex gap-2 shrink-0 mt-2">
                <button onClick={() => setMatch(p => ({...p, isTeamAOnLeft: !p.isTeamAOnLeft}))} className="flex-1 py-3 bg-slate-900 rounded-xl text-[9px] font-black uppercase text-slate-500 border border-slate-800">Camps</button>
                <button onClick={prepareFormationEntry} disabled={isMatchOver} className="flex-1 py-3 bg-indigo-900/20 rounded-xl text-[9px] font-black uppercase text-indigo-400 border border-indigo-800/30">Formation</button>
              </div>
            </div>
          )}
          {activeTab === 'subs' && (
            <div className="flex-1 grid grid-cols-2 gap-2 p-1 overflow-y-auto custom-scrollbar">
              <SubstitutionsPanel team={leftTeam} onSubstitute={() => setShowSubModal({ team: leftId })} />
              <SubstitutionsPanel team={rightTeam} onSubstitute={() => setShowSubModal({ team: rightId })} />
            </div>
          )}
          {activeTab === 'stats' && (
            <div className="flex-1 overflow-y-auto bg-slate-900/30 rounded-xl p-2 text-[10px] custom-scrollbar text-right">
              {match.history.slice().reverse().map((ev, i) => (
                <div key={i} className="flex gap-2 py-2 border-b border-slate-900 last:border-0 uppercase font-bold text-slate-400 italic">
                  <span className="text-slate-600">{ev.time}</span>
                  <span className="text-indigo-400">[{ev.score}]</span>
                  <span className="flex-1 truncate">{ev.description}</span>
                </div>
              ))}
            </div>
          )}
          {activeTab === 'archive' && (
              <div className="flex-1 flex flex-col items-center justify-center p-4 bg-slate-900/30 rounded-xl">
                 <h3 className="text-xs font-black uppercase text-slate-500 mb-4">Administration & Corrections</h3>
                 {match.currentSetIndex > 0 ? (
                     <div className="w-full space-y-4">
                         <div className="bg-slate-950 p-4 rounded-xl border border-slate-800 text-center">
                            <h4 className="text-[10px] font-black text-slate-300 uppercase mb-2">Correction Set Précédent</h4>
                            <p className="text-[9px] text-slate-500 mb-4">Annule la fin du Set {match.currentSetIndex}, restaure les scores, les formations et l'historique.</p>
                            <button onClick={handleReopenLastSet} className="w-full py-3 bg-rose-600/10 text-rose-500 border border-rose-600/30 rounded-xl font-black uppercase text-[10px] hover:bg-rose-600 hover:text-white transition-all">↩ Rouvrir le Set {match.currentSetIndex}</button>
                         </div>
                     </div>
                 ) : (
                     <div className="text-[9px] text-slate-600 italic">Aucune action disponible pour le moment.</div>
                 )}
              </div>
          )}
      </div>

      <div className={`mt-auto pt-2 shrink-0 transition-opacity ${(isEnteringFormation) ? 'opacity-20 pointer-events-none' : 'opacity-100'}`}>
         <button onClick={onEnd} className="w-full py-3 bg-slate-900 rounded-xl text-[10px] font-black uppercase text-slate-600 hover:text-white transition-all">Terminer le Match</button>
      </div>

      {showSanction.team && (
        <SanctionModal team={showSanction.team === 'A' ? match.teamA : match.teamB} onClose={() => setShowSanction({ team: null })} onApply={handleApplySanction} />
      )}
      {showSubModal && (
        <SubstitutionModal team={showSubModal.team === 'A' ? match.teamA : match.teamB} onClose={() => setShowSubModal(null)} onApply={(outId, inId) => handleApplySubstitution(showSubModal.team!, outId, inId)} forcedPlayerOutId={showSubModal.forcedPlayerOutId} />
      )}
    </div>
  );
};

// ... Rest of the file unchanged ...
const MiniBtn = ({ icon, label, count, disabled, onClick, ...handlers }: any) => (
  <button disabled={disabled} onClick={onClick} {...handlers} className={`flex flex-col items-center gap-1 transition-opacity ${disabled ? 'opacity-20 pointer-events-none' : 'active:scale-90'}`}>
    <div className="w-10 h-10 bg-slate-900 border border-slate-800 rounded-lg flex items-center justify-center text-lg relative">
      {icon}
      {count !== undefined && count > 0 && <div className="absolute -top-1 -right-1 w-4 h-4 bg-white text-black text-[9px] font-black rounded-full flex items-center justify-center border border-slate-950">{count}</div>}
    </div>
    <span className="text-[8px] font-black text-slate-600 uppercase">{label}</span>
  </button>
);

const Tab = ({ icon, active, onClick }: any) => (
