const FormationGrid = ({ team, tempF, setTempF }: any) => {
  const [activePos, setActivePos] = useState<number>(0);
  const availablePlayers = team.players.filter((p: any) => p.status === 'ACTIVE' && !p.isLibero);

  const handleSelectPlayer = (playerIndex: number) => {
    const newF = [...tempF];
    const existingPos = newF.indexOf(playerIndex);
    if (existingPos !== -1) {
       if (existingPos === activePos) return;
       newF[existingPos] = -1;
    }
    newF[activePos] = playerIndex;
    setTempF(newF);
    if (activePos < 5) {
        setActivePos(activePos + 1);
    }
  };

  const handleReset = () => {
      setTempF([-1, -1, -1, -1, -1, -1]);
      setActivePos(0);
  };

  return (
    <div className="flex-1 flex flex-col gap-4 h-full">
      <div className="grid grid-cols-2 gap-3">
        {['I','II','III','IV','V','VI'].map((pos, idx) => {
           const pIdx = tempF[idx];
           const player = pIdx !== -1 ? team.players[pIdx] : null;
           const isActive = activePos === idx;
           return (
             <button key={idx} onClick={() => setActivePos(idx)} className={`relative aspect-[1/1.2] rounded-[1.5rem] flex flex-col items-center justify-center border-2 transition-all shadow-sm ${isActive ? 'bg-blue-600 border-blue-600 text-white shadow-blue-200' : 'bg-white border-slate-200 text-slate-800 hover:border-blue-400'}`}>
               <div className={`absolute top-3 left-3 w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-black border ${isActive ? 'bg-white text-blue-600 border-white' : 'bg-blue-600 text-white border-blue-600'}`}>{pos}</div>
               <div className="flex flex-col items-center mt-4 space-y-1">
                   {player ? (
                        <>
                            <span className={`text-3xl font-black leading-none ${player.isLibero && !isActive ? 'text-amber-500' : ''}`}>{player.number}</span>
                            <span className={`text-[7px] font-bold uppercase tracking-wide ${isActive ? 'text-blue-100' : 'text-slate-400'}`}>JOUEUR {player.number}</span>
                        </>
                   ) : (
                        <>
                            <span className={`text-3xl font-black leading-none ${isActive ? 'text-blue-200' : 'text-slate-200'}`}>?</span>
                            <span className={`text-[7px] font-bold uppercase tracking-wide ${isActive ? 'text-blue-100' : 'text-slate-400'}`}>LIBRE</span>
                        </>
                   )}
               </div>
             </button>
           );
        })}
      </div>
      <div className="bg-slate-50 rounded-[1.5rem] p-3 border border-slate-200 flex-1 flex flex-col relative overflow-hidden">
         <div className="text-[8px] font-black text-slate-400 uppercase mb-3 text-center tracking-widest">SÉLECTIONNER UN JOUEUR</div>
         <div className="flex-1 overflow-y-auto custom-scrollbar px-1">
             <div className="grid grid-cols-3 gap-2 pb-12">
                {availablePlayers.map((p: any) => {
                  const pIdx = team.players.indexOf(p);
                  const isUsed = tempF.includes(pIdx);
                  return (
                    <button key={p.id} onClick={() => handleSelectPlayer(pIdx)} className={`aspect-square rounded-xl font-black text-lg border-2 transition-all flex items-center justify-center shadow-sm ${isUsed ? 'bg-slate-200 border-slate-200 text-slate-400 opacity-50' : 'bg-white border-slate-200 text-slate-700 hover:border-blue-500 hover:text-blue-600 hover:shadow-md active:scale-95'}`}>
                      {p.number}
                    </button>
                  );
                })}
             </div>
         </div>
         <div className="absolute bottom-3 left-3 right-3">
             <button onClick={handleReset} className="w-full py-3 bg-rose-100 text-rose-600 rounded-xl text-[9px] font-black uppercase hover:bg-rose-200 transition-colors shadow-sm">RÉINITIALISER</button>
         </div>
      </div>
    </div>
  );
};

import jsPDF from 'https://esm.sh/jspdf';
import { MatchState, Team, MatchSet, MatchSetPoint, SanctionType, MatchSignatures } from './types';

// ============================================================================
// CONSTANTES COULEURS
// ============================================================================
const BLACK = '#000000';
const WHITE = '#FFFFFF';
const GREY_LIGHT = '#F1F5F9';
const GREY_DARK = '#E2E8F0';
const BLUE = '#1e40af';     // Blue-800
const RED = '#e11d48';      // Rose-600
const GREEN = '#047857';    // Emerald-700
const BLUE_DARK = '#0f172a'; // Slate-900 (Headers)

// ============================================================================
// LOGIQUE MÉTIER
// ============================================================================

const getColumnForPlayerIndex = (
    playerIdx: number, 
    team: Team, 
    formationIdx: number[], 
    subs: any[]
): number => {
    let col = formationIdx.indexOf(playerIdx);
    if (col !== -1) return col;

    let currentIdx = playerIdx;
    for(let depth=0; depth<6; depth++) {
        const sub = subs.find((s: any) => {
            const inPlayer = team.players.find(p => p.id === s.playerInId);
            const inIdx = inPlayer ? team.players.indexOf(inPlayer) : -1;
            return inIdx === currentIdx;
        });
        if (!sub) break;
        const outPlayer = team.players.find(p => p.id === sub.playerOutId);
        if (!outPlayer) break;
        const outIdx = team.players.indexOf(outPlayer);
        col = formationIdx.indexOf(outIdx);
        if (col !== -1) return col;
        currentIdx = outIdx;
    }
    return -1;
};

const getServiceHistory = (set: MatchSet, teamLabel: 'A' | 'B', team: Team) => {
    const formationIdx = teamLabel === 'A' ? set.startingFormationA : set.startingFormationB;
    const subs = teamLabel === 'A' ? set.subsA : set.subsB;
    const isReceivingTeam = set.firstServingTeam !== teamLabel;

    // Structure: value, isEnd (cercle), isBlocked (gris), isSquare (carré fin de set sur sideout)
    const rotationTurns: Array<Array<{value: string, isEnd: boolean, isBlocked: boolean, isSquare?: boolean}>> = Array.from({ length: 6 }, () => []);

    if (isReceivingTeam) {
        rotationTurns[0].push({ value: '', isEnd: false, isBlocked: true });
    }

    let lastServiceColIndex = -1;

    set.points.forEach((pt: MatchSetPoint) => {
        if (pt.servedByTeam === teamLabel) {
            if (pt.isSideOut) {
               const serverIdx = pt.serverPlayerIndex;
               const colIdx = getColumnForPlayerIndex(serverIdx, team, formationIdx, subs);
               const myScore = teamLabel === 'A' ? pt.scoreA : pt.scoreB;

               if (colIdx !== -1) {
                   lastServiceColIndex = colIdx;
                   rotationTurns[colIdx].push({
                       value: myScore.toString(),
                       isEnd: false,
                       isBlocked: false
                   });
               }
            }
        }
    });

    const finalScore = teamLabel === 'A' ? set.scoreA : set.scoreB;

    // --- LOGIQUE DE FIN DE SET ---

    // 1. Chercher si le score final est déjà présent (Victoire sur son propre service)
    let found = false;
    let lastInsertedCoords = { col: -1, row: -1 };

    rotationTurns.forEach((col, cIdx) => {
        col.forEach((cell, rIdx) => {
            // Nettoyage préventif
            cell.isEnd = false;
            cell.isSquare = false;

            if (parseInt(cell.value) === finalScore) {
                found = true;
                lastInsertedCoords = { col: cIdx, row: rIdx };
            }
        });
    });

    // 2. Si pas trouvé (Victoire sur Side-Out/Réception)
    if (!found && finalScore > 0) {
        // Le point doit aller dans la colonne du PROCHAIN serveur.
        let targetCol = 0;

        if (lastServiceColIndex !== -1) {
            // S'ils ont déjà servi, c'est la colonne suivante (rotation horaire, mais indices fixes)
            // Indices colonnes : 0(I), 1(II), 2(III), 3(IV), 4(V), 5(VI)
            targetCol = (lastServiceColIndex + 1) % 6;
        } else {
            // Cas rare: N'a jamais servi du set (ex: gagné sans perdre le service ? impossible si sideout final)
            // Si équipe en réception au début: I(0) est bloqué. Le premier serveur aurait été II(1).
            if (isReceivingTeam) targetCol = 1;
            else targetCol = 0;
        }

        rotationTurns[targetCol].push({
            value: finalScore.toString(),
            isEnd: false,
            isBlocked: false,
            isSquare: true // Marquer pour encadrer en carré
        });
    } else if (lastInsertedCoords.col !== -1) {
        // Victoire sur service: On cercle la dernière occurrence
        rotationTurns[lastInsertedCoords.col][lastInsertedCoords.row].isEnd = true;
    }

    return rotationTurns;
};

// ============================================================================
// DRAWING HELPERS
// ============================================================================

const drawCell = (
  pdf: jsPDF, 
  x: number, 
  y: number, 
  w: number, 
  h: number, 
  text: string, 
  fontSize: number = 6, 
  fontStyle: string = 'normal', 
  bg: string | null = null,
  textColor: string = BLACK
) => {
  if (bg) {
    pdf.setFillColor(bg);
    pdf.rect(x, y, w, h, 'F');
  }
  pdf.setDrawColor(0);
  pdf.setLineWidth(0.1);
  pdf.rect(x, y, w, h);

  if (text) {
    pdf.setFont('helvetica', fontStyle);
    pdf.setFontSize(fontSize);
    pdf.setTextColor(textColor);
    // Alignement vertical parfait au centre géométrique
    const textY = y + (h / 2); 
    pdf.text(text, x + w / 2, textY, { align: 'center', baseline: 'middle' }); 
  }
};

const drawTextLeft = (pdf: jsPDF, x: number, y: number, text: string, fontSize: number, fontStyle: string = 'normal', color: string = BLACK) => {
  pdf.setFont('helvetica', fontStyle);
  pdf.setFontSize(fontSize);
  pdf.setTextColor(color);
  pdf.text(text, x, y);
};

const drawImageInBox = (pdf: jsPDF, imgData: string, x: number, y: number, w: number, h: number) => {
    try {
        const imgProps = pdf.getImageProperties(imgData);
        const ratio = imgProps.width / imgProps.height;
        let imgH = h - 2; // padding
        let imgW = imgH * ratio;

        if (imgW > w - 2) {
            imgW = w - 2;
            imgH = imgW / ratio;
        }

        const ix = x + (w - imgW) / 2;
        const iy = y + (h - imgH) / 2;

        pdf.addImage(imgData, 'PNG', ix, iy, imgW, imgH);
    } catch (e) {
        // ignore error
    }
}

