// COMPOSANTS DE DESSIN
// ============================================================================

const drawHeader = (pdf: jsPDF, match: MatchState, x: number, y: number, w: number) => {
  const h = 25;
  pdf.setLineWidth(0.3);
  pdf.rect(x, y, w, h);

  let curY = y + 4;
  drawTextLeft(pdf, x + 2, curY, match.league, 9, 'bold', BLUE);
  drawTextLeft(pdf, x + 2, curY + 3.5, `${match.city} • ${match.hall || '—'}`, 7, 'bold');

  pdf.setFontSize(9);
  pdf.setFont('helvetica', 'bold');
  pdf.setTextColor(BLACK);
  pdf.text(`MATCH N° ${match.matchId}`, x + w - 2, curY, { align: 'right' });
  pdf.setFontSize(7);
  pdf.text(`${match.date} • ${match.scheduledTime}`, x + w - 2, curY + 3.5, { align: 'right' });
  pdf.text(`${match.category} ${match.gender === 'M' ? 'HOMMES' : 'FEMMES'}`, x + w - 2, curY + 7, { align: 'right' });

  pdf.setFontSize(12);
  pdf.setFont('helvetica', 'bold');
  pdf.text('FEUILLE DE MATCH OFFICIELLE', x + w / 2, curY + 2, { align: 'center' });
  pdf.setFontSize(6);
  pdf.text('FIVB 2025-2028', x + w / 2, curY + 5, { align: 'center' });

  const teamRowY = y + h - 6;
  const teamRowH = 6;

  pdf.line(x, teamRowY, x + w, teamRowY);
  pdf.line(x + w / 2, teamRowY, x + w / 2, y + h);

  pdf.setFillColor(GREY_LIGHT);
  pdf.rect(x, teamRowY, w, teamRowH, 'F');
  pdf.rect(x, teamRowY, w, teamRowH, 'S'); 

  pdf.setFontSize(9);
  pdf.setFont('helvetica', 'bolditalic');
  pdf.setTextColor(BLUE);
  pdf.text(`(A) ${match.teamA.name}`, x + w / 4, teamRowY + 4, { align: 'center' });
  pdf.text(`(B) ${match.teamB.name}`, x + (w * 3) / 4, teamRowY + 4, { align: 'center' });

  return y + h + 2; 
};

const drawRoster = (pdf: jsPDF, team: Team, label: string, x: number, y: number, w: number) => {
    let curY = y;

    // --- TABLEAU DES JOUEURS ---
    drawCell(pdf, x, curY, w, 5, `ÉQUIPE ${label}`, 8, 'bold', BLUE_DARK, WHITE);
    curY += 5;

    const colNumW = 8;
    const colLicW = 15;
    const colNameW = w - colNumW - colLicW;

    drawCell(pdf, x, curY, colNumW, 4, 'N°', 6, 'bold', GREY_LIGHT);
    drawCell(pdf, x + colNumW, curY, colNameW, 4, 'Nom Prénom', 6, 'bold', GREY_LIGHT);
    drawCell(pdf, x + colNumW + colNameW, curY, colLicW, 4, 'Licence', 6, 'bold', GREY_LIGHT);
    curY += 4;

    const sortedPlayers = [...team.players].sort((a, b) => {
        if (a.isCaptain && !b.isCaptain) return -1;
        if (!a.isCaptain && b.isCaptain) return 1;
        if (a.isLibero && !b.isLibero) return 1;
        if (!a.isLibero && b.isLibero) return -1;
        return a.number - b.number;
    });

    const rowH = 3.8; 
    for(let i=0; i<sortedPlayers.length; i++) {
        const p = sortedPlayers[i];
        const num = p ? p.number.toString() : '';
        const name = p ? p.name : '';
        const lic = p ? p.licenseNumber : '';

        let displayInfos = name;
        if(p?.isCaptain) displayInfos += ' (C)';
        if(p?.isLibero) displayInfos += ' (L)';

        // Libero en ROUGE, Capitaine en BLEU
        const numColor = p?.isLibero ? RED : BLACK;
        const nameColor = p?.isCaptain ? BLUE : BLACK;

        drawCell(pdf, x, curY, colNumW, rowH, num, 7, 'bold', GREY_LIGHT, numColor);
        pdf.rect(x + colNumW, curY, colNameW, rowH);
        if(p) {
            pdf.setFontSize(7);
            pdf.setFont('helvetica', 'bold');
            pdf.setTextColor(nameColor);
            pdf.text(displayInfos, x + colNumW + 1, curY + 2.8);
        }
        drawCell(pdf, x + colNumW + colNameW, curY, colLicW, rowH, lic, 5, 'normal');
        curY += rowH;
    }

    // --- SEPARATION ENTRE JOUEURS ET STAFF ---
    curY += 1.5; // Espace visuel

    // --- TABLEAU DU STAFF ---
    drawCell(pdf, x, curY, w, 4, 'OFFICIELS', 6, 'bold', GREY_LIGHT);
    curY += 4;

    const staffH = 3.5;
    const staffRoleW = 12;
    const staffLicW = 15;
    const staffNameW = w - staffRoleW - staffLicW;

    const drawStaff = (role: string, name: string, lic: string) => {
        drawCell(pdf, x, curY, staffRoleW, staffH, role, 5, 'bold', GREY_LIGHT);
        pdf.rect(x + staffRoleW, curY, staffNameW, staffH);
        pdf.setFontSize(6);
        pdf.setFont('helvetica', 'normal');
        pdf.setTextColor(BLACK);
        pdf.text(name || '', x + staffRoleW + 1, curY + 2.5);
        drawCell(pdf, x + staffRoleW + staffNameW, curY, staffLicW, staffH, lic, 5, 'normal');
        curY += staffH;
    }

    if (team.coach) drawStaff('COACH', team.coach, team.coachLicense);
    if (team.assistantCoach1) drawStaff('ADJ. 1', team.assistantCoach1, team.assistantCoach1License);
    if (team.assistantCoach2) drawStaff('ADJ. 2', team.assistantCoach2, team.assistantCoach2License);
    if (team.medical) drawStaff('MED', team.medical, team.medicalLicense);

    return curY + 2;
};

const drawResultsTable = (pdf: jsPDF, match: MatchState, x: number, y: number, w: number) => {
    let curY = y;

    drawCell(pdf, x, curY, w, 5, 'RÉSULTATS', 8, 'bold', BLUE_DARK, WHITE);
    curY += 5;

    const centerW = 12;
    const sideW = (w - centerW) / 2;
    const colW = sideW / 4;

    const drawHeaderRow = () => {
        drawCell(pdf, x, curY, colW, 4, 'T', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + colW, curY, colW, 4, 'S', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + colW*2, curY, colW, 4, 'W', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + colW*3, curY, colW, 4, 'P', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + sideW, curY, centerW, 4, 'SET', 6, 'bold', WHITE);
        drawCell(pdf, x + sideW + centerW, curY, colW, 4, 'P', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + sideW + centerW + colW, curY, colW, 4, 'W', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + sideW + centerW + colW*2, curY, colW, 4, 'S', 5, 'bold', GREY_LIGHT);
        drawCell(pdf, x + sideW + centerW + colW*3, curY, colW, 4, 'T', 5, 'bold', GREY_LIGHT);
        curY += 4;
    };
    drawHeaderRow();

    const rowH = 4;
    const totalStats = { tA: 0, sA: 0, wA: 0, pA: 0, tB: 0, sB: 0, wB: 0, pB: 0, duration: 0 };

    for(let i=0; i<5; i++) {
        const set = match.sets[i];
        const val = (v: any) => v !== undefined ? v.toString() : '';
        let winA = false;
        if(set) winA = set.scoreA > set.scoreB;

        if (set) {
            totalStats.tA += set.timeoutsTakenA;
            totalStats.sA += set.subsA.length;
            totalStats.wA += (winA ? 1 : 0);
            totalStats.pA += set.scoreA;
            totalStats.tB += set.timeoutsTakenB;
            totalStats.sB += set.subsB.length;
            totalStats.wB += (!winA ? 1 : 0);
            totalStats.pB += set.scoreB;
            totalStats.duration += set.duration;
        }

        drawCell(pdf, x, curY, colW, rowH, val(set?.timeoutsTakenA), 6, 'bold', null, RED);
        drawCell(pdf, x + colW, curY, colW, rowH, val(set?.subsA.length), 6, 'bold', null, RED);
        drawCell(pdf, x + colW*2, curY, colW, rowH, val(set ? (winA ? 1 : 0) : ''), 6, 'bold', null, winA ? GREEN : BLACK);
        drawCell(pdf, x + colW*3, curY, colW, rowH, val(set?.scoreA), 6, 'bold', null, winA ? GREEN : BLACK);

        drawCell(pdf, x + sideW, curY, centerW, rowH, val(set?.duration), 5, 'normal', GREY_LIGHT);

        drawCell(pdf, x + sideW + centerW, curY, colW, rowH, val(set?.scoreB), 6, 'bold', null, (set && !winA) ? GREEN : BLACK);
        drawCell(pdf, x + sideW + centerW + colW, curY, colW, rowH, val(set ? (!winA ? 1 : 0) : ''), 6, 'bold', null, (set && !winA) ? GREEN : BLACK);
        drawCell(pdf, x + sideW + centerW + colW*2, curY, colW, rowH, val(set?.subsB.length), 6, 'bold', null, RED);
        drawCell(pdf, x + sideW + centerW + colW*3, curY, colW, rowH, val(set?.timeoutsTakenB), 6, 'bold', null, RED);
        curY += rowH;
    }

    // Ligne TOTAL
    drawCell(pdf, x, curY, colW, rowH, totalStats.tA.toString(), 6, 'bold', GREY_LIGHT, RED);
    drawCell(pdf, x + colW, curY, colW, rowH, totalStats.sA.toString(), 6, 'bold', GREY_LIGHT, RED);
    drawCell(pdf, x + colW*2, curY, colW, rowH, totalStats.wA.toString(), 6, 'bold', GREY_LIGHT, GREEN);
    drawCell(pdf, x + colW*3, curY, colW, rowH, totalStats.pA.toString(), 6, 'bold', GREY_LIGHT, GREEN);

    // Affichage de la somme des temps (Total Duration)
    drawCell(pdf, x + sideW, curY, centerW, rowH, totalStats.duration.toString(), 6, 'bold', BLACK, WHITE);

    drawCell(pdf, x + sideW + centerW, curY, colW, rowH, totalStats.pB.toString(), 6, 'bold', GREY_LIGHT, GREEN);
    drawCell(pdf, x + sideW + centerW + colW, curY, colW, rowH, totalStats.wB.toString(), 6, 'bold', GREY_LIGHT, GREEN);
    drawCell(pdf, x + sideW + centerW + colW*2, curY, colW, rowH, totalStats.sB.toString(), 6, 'bold', GREY_LIGHT, RED);
    drawCell(pdf, x + sideW + centerW + colW*3, curY, colW, rowH, totalStats.tB.toString(), 6, 'bold', GREY_LIGHT, RED);
    curY += rowH;

    const winnerName = match.teamA.setsWon > match.teamB.setsWon ? match.teamA.name : (match.teamB.setsWon > match.teamA.setsWon ? match.teamB.name : '');
    const scoreStr = winnerName ? `(${match.teamA.setsWon}-${match.teamB.setsWon})` : '';

    // Affichage VAINQUEUR
    drawCell(pdf, x, curY, w, 6, `VAINQUEUR: ${winnerName} ${scoreStr}`, 8, 'bold', BLUE_DARK, WHITE);

    return curY + 6 + 2; 
};

const drawSignatures = (pdf: jsPDF, match: MatchState, x: number, y: number, w: number) => {
    let curY = y;

    drawCell(pdf, x, curY, w, 5, 'APPROBATION', 7, 'bold', GREY_LIGHT);
    curY += 5;

    const rowH = 8;
    const colW = w / 2;

    const drawSigBox = (role: string, name: string, bx: number, by: number, sigKey?: keyof MatchSignatures) => {
        pdf.rect(bx, by, colW, rowH);

        // Label (Bottom)
        pdf.setFontSize(5);
        pdf.setTextColor(BLACK);
        pdf.text(role, bx + colW/2, by + rowH - 1, {align: 'center'});

        // Signature Image (Middle/Background)
        if (sigKey && match.signatures && match.signatures[sigKey]) {
             drawImageInBox(pdf, match.signatures[sigKey]!, bx, by, colW, rowH - 2);
        }

        // Name (Top)
        pdf.setFontSize(7);
        pdf.setFont('helvetica', 'bold');
        pdf.setTextColor(BLUE);
        pdf.text(name, bx + colW/2, by + 2.5, {align: 'center'});
    };

    drawSigBox('1er ARBITRE', match.referee1, x, curY, 'referee1');
    drawSigBox('2e ARBITRE', match.referee2, x + colW, curY, 'referee2');
    curY += rowH;

    drawSigBox('MARQUEUR', match.scorer, x, curY, 'scorer');
    drawSigBox('ASSISTANT MARQUEUR', '', x + colW, curY);
    curY += rowH;

    const lineH = 4;
    drawCell(pdf, x, curY, w, 4, 'JUGES DE LIGNE', 5, 'normal', GREY_LIGHT);
    curY += 4;

    drawCell(pdf, x, curY, colW, lineH, `1. ${match.lineJudge1}`, 6);
    drawCell(pdf, x + colW, curY, colW, lineH, `2. ${match.lineJudge2}`, 6);
    curY += lineH;
    drawCell(pdf, x, curY, colW, lineH, `3. ${match.lineJudge3}`, 6);
    drawCell(pdf, x + colW, curY, colW, lineH, `4. ${match.lineJudge4}`, 6);
    curY += lineH;

    // Captains
    drawSigBox('CAPITAINE (A)', '', x, curY, 'captainA');
    drawSigBox('CAPITAINE (B)', '', x + colW, curY, 'captainB');
    curY += rowH;

    // Coaches
    drawSigBox('COACH (A)', match.teamA.coach, x, curY, 'coachA');
    drawSigBox('COACH (B)', match.teamB.coach, x + colW, curY, 'coachB');
    curY += rowH;

    return curY + 2;
};

const drawSanctions = (pdf: jsPDF, match: MatchState, x: number, y: number, w: number) => {
    const titleH = 5;
    const headerH = 4;
    const rowH = 4;

    const sanctionCount = match.playerSanctions.length;
    const rowsToDraw = Math.max(1, sanctionCount);

    const totalH = titleH + headerH + (rowsToDraw * rowH);

    pdf.setDrawColor(0);
    pdf.setLineWidth(0.3);
    pdf.rect(x, y, w, totalH);

    drawCell(pdf, x, y, w, titleH, 'SANCTIONS', 8, 'bold', BLUE_DARK, WHITE);
    let curY = y + titleH;

    const colTyp = 10;
    const colTeam = 10;
    const colNum = 10;
    const colSet = 10;
    const colPts = w - 40;

    drawCell(pdf, x, curY, colTyp, headerH, 'TYP', 5, 'bold', GREY_LIGHT);
    drawCell(pdf, x + colTyp, curY, colTeam, headerH, 'A/B', 5, 'bold', GREY_LIGHT);
    drawCell(pdf, x + colTyp + colTeam, curY, colNum, headerH, 'N°', 5, 'bold', GREY_LIGHT);
    drawCell(pdf, x + colTyp + colTeam + colNum, curY, colSet, headerH, 'SET', 5, 'bold', GREY_LIGHT);
    drawCell(pdf, x + colTyp + colTeam + colNum + colSet, curY, colPts, headerH, 'PTS', 5, 'bold', GREY_LIGHT);
    curY += headerH;

    const getCode = (type: SanctionType) => {
        switch(type) {
            case SanctionType.WARNING: return 'A'; 
            case SanctionType.PENALTY: return 'P'; 
            case SanctionType.EXPULSION: return 'E';
            case SanctionType.DISQUALIFICATION: return 'D';
            case SanctionType.DELAY_WARNING: return 'R(A)';
            case SanctionType.DELAY_PENALTY: return 'R(P)';
            default: return '';
        }
    };

    for(let i=0; i<rowsToDraw; i++) {
        const s = match.playerSanctions[i];

        let t = '', tm = '', n = '', st = '', sc = '';
        if (s) {
            t = getCode(s.type);
            tm = s.team;
            const player = match.teamA.players.find(p => p.id === s.playerId) || match.teamB.players.find(p => p.id === s.playerId);
            n = player ? player.number.toString() : (s.playerId.includes('coach') ? 'C' : 'T');
            st = (s.setIndex + 1).toString();
            sc = s.scoreAtSanction;
        }

        drawCell(pdf, x, curY, colTyp, rowH, t, 6, 'bold', null, RED);
        drawCell(pdf, x + colTyp, curY, colTeam, rowH, tm, 6, 'bold', null, BLUE);
        drawCell(pdf, x + colTyp + colTeam, curY, colNum, rowH, n);
        drawCell(pdf, x + colTyp + colTeam + colNum, curY, colSet, rowH, st);
        drawCell(pdf, x + colTyp + colTeam + colNum + colSet, curY, colPts, rowH, sc);
        curY += rowH;
    }

    return y + totalH;
};

const drawRemarks = (pdf: jsPDF, match: MatchState, x: number, y: number, w: number) => {
    const titleH = 5;
    let contentH = 10;

    let splitText: string[] = [];
    if (match.remarks) {
        pdf.setFontSize(7);
        splitText = pdf.splitTextToSize(match.remarks, w - 4);
        const textHeight = splitText.length * 3.5;
        contentH = Math.max(10, textHeight + 6);
    }

    const totalH = titleH + contentH;

    drawCell(pdf, x, y, w, titleH, 'REMARQUES', 8, 'bold', BLUE_DARK, WHITE);

    pdf.setDrawColor(0);
    pdf.setLineWidth(0.1);
    pdf.rect(x, y + titleH, w, contentH);

    if (match.remarks) {
       pdf.setFontSize(7);
       pdf.setFont('helvetica', 'normal');
       pdf.setTextColor(BLUE);
       pdf.text(splitText, x + 2, y + titleH + 4);
    } else {
       pdf.setFontSize(7);
       pdf.setFont('helvetica', 'italic');
       pdf.setTextColor(100);
       pdf.text("Néant.", x + 2, y + titleH + 4);
    }

    return y + totalH;
};

const drawSetColumn = (
    pdf: jsPDF, 
    set: MatchSet, 
    team: Team, 
    match: MatchState, 
    teamLabel: 'A' | 'B', 
    x: number, 
    y: number, 
    w: number
) => {
    drawCell(pdf, x, y, 6, 5, teamLabel, 7, 'bold', GREY_LIGHT, BLUE);
    pdf.rect(x + 6, y, w - 6, 5);
    pdf.setFontSize(7);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(BLACK);
    // Alignement du nom d'équipe
    pdf.text(team.name, x + 6 + (w-6)/2, y + 2.5 + 1, {align: 'center', baseline: 'middle'});

    let curY = y + 5;

    const svcW = 5;
    const posW = (w - svcW) / 6;

    drawCell(pdf, x, curY, svcW, 3.5, 'Svc', 4, 'normal', GREY_LIGHT);
    ['I', 'II', 'III', 'IV', 'V', 'VI'].forEach((pos, i) => {
        drawCell(pdf, x + svcW + i * posW, curY, posW, 3.5, pos, 5, 'bold', GREY_LIGHT);
    });
    curY += 3.5;

    const formationIdx = teamLabel === 'A' ? set.startingFormationA : set.startingFormationB;
    const starters = formationIdx.map(idx => team.players[idx]);

    drawCell(pdf, x, curY, svcW, 3.5, 'N°', 4, 'bold', GREY_LIGHT);
    starters.forEach((p, i) => {
        const txt = p ? p.number.toString() : '';
        drawCell(pdf, x + svcW + i * posW, curY, posW, 3.5, txt, 7, 'bold');
    });
    curY += 3.5;

    drawCell(pdf, x, curY, svcW, 3.5, 'Remp', 3.5, 'normal', GREY_LIGHT, RED);
    starters.forEach((p, i) => {
        const subs = teamLabel === 'A' ? set.subsA : set.subsB;
        // Logic to find first substitution for this starter
        const sub = p ? subs.find(s => s.playerOutId === p.id && !s.isReturn) : null;
        const subP = sub ? team.players.find(pl => pl.id === sub.playerInId) : null;
        const txt = subP ? subP.number.toString() : '';

        const cellX = x + svcW + i * posW;
        drawCell(pdf, cellX, curY, posW, 3.5, txt, 6, 'normal', null, RED);

        // Check for return (2nd substitution) to circle the player number
        if (sub && subP) {
             const hasReturn = subs.some(s => s.playerOutId === subP.id && s.isReturn);
             if (hasReturn) {
                 pdf.setLineWidth(0.3);
                 pdf.setDrawColor(225, 29, 72); // RED 
                 pdf.circle(cellX + posW/2, curY + 1.75, 1.5); 
             }
        }
    });
    curY += 3.5;

    drawCell(pdf, x, curY, svcW, 3.5, 'Sc.', 3.5, 'italic', GREY_DARK);
    starters.forEach((p, i) => {
        const subs = teamLabel === 'A' ? set.subsA : set.subsB;
        const cx = x + svcW + i * posW;

        // Find substitutions for this position
        // 1. First sub OUT
        const subIn = p ? subs.find(s => s.playerOutId === p.id && !s.isReturn) : null;
        // 2. Second sub OUT (Original player coming back)
        const subOut = subIn ? subs.find(s => s.playerOutId === subIn.playerInId && s.isReturn) : null;

        pdf.setDrawColor(0);
        pdf.setLineWidth(0.1);
        pdf.rect(cx, curY, posW, 3.5);

        pdf.setFontSize(4);
        pdf.setFont('helvetica', 'normal');
        pdf.setTextColor(BLACK);

        if (subIn) {
            const scoreIn = subIn.scoreAtSub || '';
            const scoreOut = subOut?.scoreAtSub || '';

            if (scoreOut) {
                // Diviser la case en deux si deux remplacements
                pdf.line(cx, curY + 1.75, cx + posW, curY + 1.75);
                pdf.setFontSize(3.5);

                // Centrage vertical précis (Middle Baseline)
                // Haut (0 à 1.75) -> Milieu 0.875
                pdf.text(scoreIn, cx + posW/2, curY + 0.875, { align: 'center', baseline: 'middle' });
                // Bas (1.75 à 3.5) -> Milieu 1.75 + 0.875 = 2.625
                pdf.text(scoreOut, cx + posW/2, curY + 2.625, { align: 'center', baseline: 'middle' });
            } else {
                // Un seul remplacement : centré totalement (0 à 3.5) -> Milieu 1.75
                pdf.text(scoreIn, cx + posW/2, curY + 1.75, { align: 'center', baseline: 'middle' });
            }
        }
    });
    curY += 3.5;

    const history = getServiceHistory(set, teamLabel, team);
    const rowH = 4;

    for (let r = 0; r < 4; r++) {
        const suffix = r === 0 ? 'ère' : 'ème';
        pdf.setDrawColor(0);
        pdf.rect(x, curY, svcW, rowH);
        pdf.setFontSize(4);
        pdf.setTextColor(BLACK);
        pdf.text((r+1).toString(), x + 1.5, curY + 3);
        pdf.setFontSize(3);
        pdf.text(suffix, x + 3, curY + 2);

        for(let c=0; c<6; c++) {
            const cx = x + svcW + c * posW;
            const data = history[c][r];

            if (data?.isBlocked) {
                pdf.setFillColor(220, 220, 220);
                pdf.rect(cx, curY, posW, rowH, 'F');
            }
            pdf.setDrawColor(0);
            pdf.rect(cx, curY, posW, rowH); 

            if (data?.value) {
                pdf.setFontSize(6);
                pdf.setFont('helvetica', 'bold');

                // COULEUR SCORE : VERT si carré, BLEU sinon
                pdf.setTextColor(data.isSquare ? GREEN : BLUE);
                pdf.text(data.value, cx + posW/2, curY + 2, {align: 'center', baseline: 'middle'});

                if (data.isEnd) {
                    pdf.setLineWidth(0.3);
                    pdf.setDrawColor(30, 64, 175); // BLUE
                    pdf.circle(cx + posW/2, curY + 2, 1.8);
                    pdf.setLineWidth(0.1);
                } else if (data.isSquare) {
                    pdf.setLineWidth(0.3);
                    pdf.setDrawColor(4, 120, 87); // GREEN
                    pdf.rect(cx + (posW/2) - 1.5, curY + 2 - 1.5, 3, 3);
                    pdf.setLineWidth(0.1);
                }
            }
        }
        curY += rowH;
    }

    const timeouts = match.history.filter(e => e.type === 'TIMEOUT' && e.team === teamLabel && e.setIndex === match.sets.indexOf(set));
    const t1 = timeouts[0]?.score || '';
    const t2 = timeouts[1]?.score || '';

    const tmH = 6;
    pdf.setDrawColor(0);
    pdf.rect(x, curY, w, tmH);
    pdf.setFontSize(5);
    pdf.setTextColor(RED);
    // Alignement T.M.
    pdf.text('T.M.', x + 2, curY + 3, {baseline: 'middle'});

    const tmBoxW = 10;
    const tmX = x + 8;
    drawCell(pdf, tmX, curY + 1, tmBoxW, 4, t1, 6, 'bold', null, RED);
    drawCell(pdf, tmX + tmBoxW + 2, curY + 1, tmBoxW, 4, t2, 6, 'bold', null, RED);
};

const drawSetBlock = (pdf: jsPDF, set: MatchSet, setNum: number, match: MatchState, x: number, y: number, w: number) => {
    // Hauteur optimisée: 41mm
    const h = 41; 

    pdf.setLineWidth(0.3);
    pdf.rect(x, y, w, h);

    const headerText = `SET ${setNum}   |   Début: ${set.startTime}   |   Fin: ${set.endTime}   |   Durée: ${set.duration} min`;
    drawCell(pdf, x, y, w, 5, headerText, 7, 'bold', BLUE_DARK, WHITE);

    const cy = y + 5;
    const colW = w / 2;
    const isTeamALeft = setNum % 2 !== 0;

    drawSetColumn(pdf, set, isTeamALeft ? match.teamA : match.teamB, match, isTeamALeft ? 'A' : 'B', x, cy, colW);
    drawSetColumn(pdf, set, isTeamALeft ? match.teamB : match.teamA, match, isTeamALeft ? 'B' : 'A', x + colW, cy, colW);

    return y + h + 5;
};

export const generateScoreSheetPDF = (match: MatchState) => {
  const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

  const pageW = 210;
  const pageH = 297;
  const margin = 5;
  const contentW = pageW - (margin * 2);

  let y = margin;
  y = drawHeader(pdf, match, margin, y, contentW);

  const colLeftW = 65;
  const colRightW = contentW - colLeftW - 2; 
  const colRightX = margin + colLeftW + 2;

  let leftY = y;
  let rightY = y;

  leftY = drawRoster(pdf, match.teamA, 'A', margin, leftY, colLeftW);
  leftY = drawRoster(pdf, match.teamB, 'B', margin, leftY, colLeftW);
  leftY = drawResultsTable(pdf, match, margin, leftY, colLeftW);
  leftY = drawSignatures(pdf, match, margin, leftY, colLeftW);

  // Dessin des Sets
  for(let i=0; i<match.sets.length; i++) {
      rightY = drawSetBlock(pdf, match.sets[i], i+1, match, colRightX, rightY, colRightW);
  }

  let footerY = Math.max(leftY, rightY) + 5;

  if (footerY > 275) footerY = 275;

  // Dessin Sanctions (Gauche) - Hauteur dynamique
  drawSanctions(pdf, match, margin, footerY, colLeftW);

  // Dessin Remarques (Droite) - Hauteur dynamique
  drawRemarks(pdf, match, colRightX, footerY, colRightW);

  // --- FOOTER COPYRIGHT ---
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(7);
  pdf.setTextColor(100);
  pdf.text("Élaborée par M. HAMANI Omar Tous droits réservés 2026", pageW / 2, pageH - 5, { align: 'center' });

  pdf.save(`Feuille_Match_${match.matchId}.pdf`);
};
